module.exports=[["e7619f8bf5","奥尔良风味烤鸡腿是一道简单易做的菜，富含蛋白质和铁。总共花费约 3 小时，其中手动操作时间约 20 分钟。",[["必备","烤箱","t",0],["必备","烤盘","t",0],["必备","铝箔纸","f",0],["必备","手枪腿鸡腿","f",0],["必备","新奥尔良烤翅调料（推荐品牌 McCormick 味好美）","f",0],["必备","豉油调味汁（推荐品牌 日和，\"薄盐肠粉豉油调味汁\"）","f",0]],[["参考用量",[["手枪腿鸡腿","2 只（每个手枪腿大约重 200g，共约 400g）","f"],["新奥尔良烤翅调料","15 - 20 g","f"],["水 ≥30 mL","","f"]],["一份正好够 1 个人吃。","每份："]]],[["制作步骤",["解冻手枪腿鸡腿并洗净。","手枪腿鸡腿改花刀：在每只手枪腿鸡腿的\"枪管\"处，平行于\"枪管\"用小刀切 4-6 刀，下刀尽可能深。","拿一个锅，加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水。","将改完花刀的手枪腿鸡腿放入锅内，搅匀。","将整个锅放入冰箱冷藏层冷藏 2 - 4 小时，时间越长越入味。","在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。丢弃锅内剩余的液体。","放入烤箱中上层，按照如下参数烘烤：","上层 230 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时","取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","对所有手枪腿鸡腿翻面。","放入烤箱上层，按照如下参数烘烤：","上层 150 ℃, 下层 230 ℃, 上下层烘烤, 20 分钟定时","取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","放入烤箱上层，按照如下参数烘烤：","上层 60 ℃, 下层 60 ℃, 上下层烘烤, 15-20 分钟定时","取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","取一个小碗，按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁。调味汁越多越咸，具体加入量取决于个人口味。","抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。","若小碗中的液体中途用尽，重复上一步。"]]],["冷藏中途可以拿出搅匀。冷藏时间切勿过长。","该指南基于的烤箱参数为容积 25 L，功率 1400 W。","若烤箱功率低于/高于此值，可以适当延长/缩短烤箱定时，但请确保鸡腿是熟的。"]],["502deeb458","这是一道经典的澳门葡式风味快餐，牛肉碎嫩滑咸香，裹着浓郁酱汁和半熟蛋液，拌入米饭后口感油润诱人。牛肉末提供优质蛋白质，搭配鸡蛋和洋葱，营养均衡管饱。操作步骤简单易上手，特别适合新手尝试，从备料到出锅大约只需 30 分钟。",[["必备","牛肉末（可以用稍微肥一点的猪肉末代替）","f",0],["必备","洋葱","f",0],["必备","鸡蛋","f",0],["必备","黄油（可用普通食用油代替）","s",0],["必备","小葱（可选）","f",1],["必备","生抽","s",0],["必备","老抽","s",0],["必备","番茄酱","s",0],["必备","白糖","s",0],["必备","料酒","s",0],["必备","黑胡椒","s",0],["必备","淀粉","s",0],["必备","米饭","f",0]],[["参考用量",[["牛肉末","200g","f"],["洋葱","半个","f"],["鸡蛋","1 个（用于制作水波蛋或半熟煎蛋）","f"],["生抽","3 汤匙（1 汤匙用于腌制，2 汤匙用于料汁）","s"],["老抽","半汤匙","s"],["番茄酱","2 汤匙","s"],["白糖","半汤匙","s"],["料酒","1 汤匙","s"],["淀粉","1 汤匙","s"],["清水","50ml","f"]],["每次制作前需要确定计划做几份。一份正好够 1 个人吃。","每份："]]],[["制作步骤",["将 200g 牛肉末放入碗中，加入 1 汤匙生抽、半汤匙白糖和 2g 黑胡椒，搅拌均匀，等待腌制 10 分钟。","将半个洋葱切成小丁，备用。","调制料汁：在碗中加入 2 汤匙生抽、2 汤匙番茄酱、1 汤匙料酒、1 汤匙淀粉、半汤匙老抽和 50ml 清水，搅拌均匀备用。","另起一锅，制作一个水波蛋或半熟煎蛋，备用。","热锅，放入 10g 黄油。待黄油融化后，放入洋葱丁，小火煎熟至散发香味。","加入腌制好的牛肉末，与洋葱一起翻炒至牛肉变色。","倒入调好的料汁，撒上 2g 黑胡椒，继续炒制直至汤汁变粘稠后关火。","将炒好的免治牛肉浇在热米饭上，放上提前准备好的水波蛋或半熟煎蛋。","（可选）表面撒上 5g 切好的小葱花作装饰。"]]],["如果没有黄油，使用普通食用油也可以，但黄油会增加独特的奶香味。","吃的时候将半熟的蛋黄戳破，与牛肉和米饭拌匀食用，口感最佳。"]],["0cea8dcc52","这道巴基斯坦风味咖喱牛肉香浓软糯，酸辣开胃，带着浓郁的香料气息。牛肉提供优质蛋白，搭配番茄和酸奶，营养均衡。做法不算繁琐，但慢炖需要一点耐心，很适合在闲暇的周末从容准备。从头到尾大约两个半小时，就能端出一锅温暖的异国美味。",[["必备","普通的炒锅","t",0],["必备","电饭煲/电炖锅","t",0],["必备","Masala 粉（品牌可选 Shan）","f",1],["必备","牛肉","f",0],["必备","番茄","f",0],["必备","螺丝椒","f",0],["必备","原味酸奶","f",0],["必备","蒜粉","f",0],["必备","姜粉","f",0]],[["参考用量",[["番茄🍅","4 个","f"],["螺丝椒","2 个（大个的）","f"],["原味酸奶","1 盒","f"],["Masala 粉一包","50g","f"],["蒜粉","5g","f"],["姜粉","5g","f"]],["这里以 1kg 牛肉的所需要的配菜量作为标的，可以通过它计算出不同菜量。1kg 牛肉做出的咖喱大概够 5 个人吃。","1kg 牛肉所需要的配菜量："]]],[["制作步骤",["全部螺丝椒切成段状，备用","全部番茄打成番茄蓉，备用","牛肉切成 2cm 的小块，洗净备用","炒锅中倒入一层油（用来防止番茄蓉沸腾蒸发）","倒入番茄蓉，持续搅拌 2-3 分钟，等待它越变越红","加入 5g 蒜粉，5g 姜粉和 1 包 50g 的 Masala 粉，搅拌均匀","加入牛肉和螺丝椒段，搅拌均匀","加入 1 盒酸奶（为了让整个酱汁变得粘稠），搅拌均匀","将整锅材料转移到电饭煲/电炖锅，并加入 250 ml 的水，开启炖肉/慢炖档，设定时间 2-3 个小时","等待完成，开锅检查牛肉软糯，就可以吃了"]]],["这道菜是从一个巴基斯坦的朋友那里偷师而来，特地整理了笔记，绝对正宗。","通常配以 烙饼(roti)、馕(naan) 或 米饭 食用。","如果想做 Chicken karahi 流程几乎是一样的，除了是先用油和各种花椒胡椒煎鸡肉变黄。"]],["92300c6ae5","猪肉白菜炖粉条是东北地区经典的家常炖菜，汤汁浓郁咸鲜，五花肉软烂、粉条吸饱肉香后滑韧入味，白菜清甜解腻。整道菜荤素搭配均衡，能提供蛋白质、维生素和碳水化合物，营养饱腹。制作过程需要一些耐心，特别是粉条处理和炖煮火候，对新手有一定挑战，但按步骤操作不易失败，从头到尾大约需要 45 分钟即可上桌。",[["必备","五花肉","f",0],["必备","白菜","f",0],["必备","土豆干粉条","f",0],["必备","十三香","s",0],["必备","鸡精","s",0],["必备","食用盐","s",0],["必备","老抽","s",0],["必备","生抽","s",0]],[["参考用量",[["五花肉","300g","f"],["大白菜","500g","f"],["土豆干粉条","50g","f"],["十三香","10g","s"],["鸡精","5g","s"],["食用盐","15g","s"],["老抽","5ml","s"],["生抽","5ml","s"]],["每份："]]],[["制作步骤",["锅内烧水，水开后放入干粉条，煮 5 分钟后同水一起倒出容器中，盖上盖子继续浸泡泡 备用（第一步先做这个，期间可以进行以下步骤）","五花肉切 3mm 的肉片，备用","大白菜嫩叶与白菜帮子分开切成 2 份菜片，备用","热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","放入五花肉，保持翻炒至肉变色","加入老抽，炒 1 分钟，给肉上色","加入白菜帮子，加入食用盐、生抽，炒一分钟（如果粘锅，烹入 10ml 水）","加水没过所有食材，加入鸡精 ，十三香，沸腾后，将火调小然后等待 20 分钟","粉条滤水切成小段放入碗中 备用","加入白菜嫩叶，炒匀后将粉条放在菜上方，加盖再煮 5 分钟","尝味、关火，收汁"]]],["土豆干粉条煮制时间长，可以放在第一步，期间进行其他步骤","最后一步尝味，如果发现有味道淡、未熟，继续加盖煮一段时间"]],["a221160e13","这是一道粤式茶楼里的人气蒸点，豉香醇厚，排骨滑嫩脱骨。排骨提供优质蛋白和钙质，发酵豆豉增添风味也更利吸收。做法需经过泡洗、腌制和控火蒸制，对新手稍有考验，但步骤清晰易上手，从备料到出锅大约只需 1 小时。剩余的汤汁用来拌饭或拌面格外鲜美。",[["必备","肋排","f",0],["必备","阳江豆豉","f",0],["必备","蒜蓉","f",0],["必备","姜末","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","蚝油","s",0],["必备","白砂糖","s",0],["必备","生粉","f",0],["必备","食用油","s",0],["必备","清水","f",0],["必备","葱花（可选）","f",1],["必备","白芝麻（可选）","f",1]],[["参考用量",[["肋排","500 g","f"],["阳江豆豉","15 g","f"],["蒜蓉","10 g","f"],["姜末","5 g","f"],["生抽","15 ml","s"],["老抽","3 ml","s"],["蚝油","10 g","s"],["白砂糖","5 g","s"],["生粉","8 g","f"],["食用油","20 ml（不打算淋热油为 10 ml）","s"],["清水","30 ml","f"]],["每次制作前需要确定计划做几份。一份正好够 2-4 个人吃。","每份："]]],[["制作步骤",["将排骨用冷水浸泡 10 分钟泡去血水，换水重复 2 次，用厨房纸吸干","将豆豉放入水中浸泡 5 分钟","将所有食材混合（食用油放 10 ml），腌制 8-30 分钟","水开后上锅蒸 18 分钟","焖 2 分钟","锅中倒入 10 ml 热油，加热到 180-200 ℃","均匀撒上葱花和白芝麻，热油浇在撒料上"]]],["豆豉浸泡后稍微剁碎会更入味","蒸制时间随排骨大小调整，以筷子能轻松插入软骨处为准","传统的豉汁排骨不放撒料和淋热油","吃剩的汤汁可以用来拌饭或者拌面"]],["bfdb68990d","豉汁蒸白鱔是一道粤式经典蒸菜，豆豉蒜蓉的酱香渗透进鱼肉，口感嫩滑鲜美。白鱔富含优质蛋白和多种不饱和脂肪酸，对身体有滋补作用。操作步骤清晰，但处理生鱼和掌握火候稍有挑战，适合有一定基础的厨友。从备料到上桌大约需要 30 分钟。",[["必备","白鱔（白鳝）","f",0],["必备","豆豉","f",0],["必备","蒜头","f",0],["必备","姜","f",0],["必备","葱","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","糖","s",0],["必备","麻油","s",0],["必备","生粉（可选）","f",1],["必备","红椒（可选，装饰用）","f",1],["工具","蒸锅或电蒸炉","f",0],["工具","耐热盘（适合蒸的盘子）","f",0],["工具","刀和砧板","t",0],["工具","小碗（调酱汁用）","t",0]],[["参考用量",[["白鱔","250g （约一条小白鱔，已去内脏并切成段）","f"],["豆豉","1 汤匙","f"],["蒜头","2 瓣 （剁碎）","f"],["姜","3 片 （切丝）","f"],["葱","1 根 （切段或丝）","f"],["生抽","1.5 汤匙","s"],["老抽","0.5 茶匙","s"],["糖","0.5 茶匙","s"],["麻油","0.5 茶匙","s"],["生粉","1 茶匙 （可选，用于腌制）","f"],["水","1 汤匙 （调酱汁）","f"],["红椒","10g （切丝，装饰用）","f"]],["一人份量","每份："]]],[["制作步骤",["检查与清洗白鱔：","购买时已请鱼贩去内脏、刮去黏液并切成约 5 厘米长的段。","回家后检查白鱔，冲洗干净，确保无残留黏液或杂质。","可选：用 3g 盐和 1 茶匙生粉轻搓白鱔段，腌制 5 分钟后冲洗干净，去腥并增加嫩滑口感。","准备酱汁：","在小碗中混合 1 汤匙豆豉、2 瓣蒜末、1.5 汤匙生抽、0.5 茶匙老抽、0.5 茶匙糖、0.5 茶匙麻油和 1 汤匙水，搅拌均匀。","若喜欢更浓郁的豉汁，可多加 0.5 汤匙豆豉。","摆盘：","将已切好的白鱔段平铺在耐热盘中，尽量不重叠。","将姜丝均匀撒在白鱔上。","将调好的豉汁均匀淋在白鱔上。","蒸制：","在蒸锅或电蒸炉中加入水 (500ml)，烧开。","将装有白鱔的盘子放入蒸锅，盖上锅盖。","用中大火蒸约 8-10 分钟 （视白鱔段大小调整时间），至白鱔熟透但不过老 （肉质变白，无血水）。","装饰与完成：","蒸好后取出，撒上葱丝和红椒丝 （可选） 作装饰。","可再淋热麻油提升香气。","趁热上桌，搭配白饭享用。"]]],["注意事项：","确保白鱔新鲜，购买时选择活鱼，肉质更鲜嫩。","鱼贩切段时可指定长度 （约 5 厘米为宜），方便蒸制和食用。","蒸制时间不宜过长，以免白鱔肉质变韧。","变种做法：","可加入辣椒或 XO 酱，增加辣味和层次感。","若喜欢更软嫩的口感，可在腌制时加入米酒。"]],["c9be155ef0","葱烧鸡腿是一道只靠鸡腿和大葱两种核心食材就能完成的下饭家常菜。鸡腿肉外焦里嫩，葱香浓郁，做法简单，全程一口锅，新手也能一次成功。蛋白质丰富，搭配米饭尤其合适，适合工作日快手晚餐。",[["必备","鸡腿 2 个（约 500g）","f",0],["必备","大葱 1 根","f",0],["必备","小葱 3-4 根","f",0],["必备","生抽（推荐海天金标）","s",0],["必备","老抽（上色用，可选）","s",1],["必备","蚝油（可选）","s",1],["必备","白砂糖","s",0],["必备","料酒或花雕酒","f",0],["必备","盐","s",0],["必备","白胡椒粉","s",0],["必备","食用油","s",0],["必备","生姜 3-4 片（可选，主要用于去腥提香）","f",1],["必备","花椒 10 粒（约 1g，可选，提麻香）","f",1]],[["参考用量",[["鸡腿","2 个（去骨后净肉约 350g）","f"],["大葱","1 根（约 100g）","f"],["小葱","3-4 根（约 30g）","f"],["生抽","15ml","s"],["老抽","5ml（上色用，没有可以全用生抽）","s"],["蚝油","10ml（可选，没有就多放 5ml 生抽）","s"],["白砂糖","5g","s"],["料酒","10ml","s"],["盐","2-3g","s"],["白胡椒粉","1g","s"],["食用油","15-20ml","s"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["鸡腿去骨：用剪刀从鸡腿大的那头伸进去，贴着骨头把肉剪开，再沿骨剪两下把骨肉分离，最后把骨头整根抽出。比用刀去骨更安全。","去骨后的鸡腿肉切成 2-3cm 的丁。","大葱切厚片（约 0.5cm 厚），小葱切 1cm 长的小段。","鸡腿丁加入 10ml 料酒、5ml 生抽、2g 盐、1g 白胡椒粉抓匀，腌制 10 分钟。","取一个小碗调好料汁：10ml 生抽 + 5ml 老抽 + 10ml 蚝油 + 5g 糖，搅匀备用。","热锅，锅内放入 15-20ml 食用油。","放入姜片和花椒，保持小火炸到姜片微微焦黄、花椒颜色变深。","用漏勺把姜片和花椒捞出丢弃，留底油。","保持中大火，将腌好的鸡腿丁平铺下锅，不要急着翻动。","等待 2-3 分钟让鸡腿丁底部煎出焦壳，再翻炒到所有面都变色、鸡肉完全断生。","下入大葱片，保持中大火翻炒 1 分钟炒出葱香。","倒入调好的料汁，翻炒均匀后盖上锅盖。","等待 2 分钟让料汁和葱香完全融合到鸡肉里。","开盖，下入小葱段和 2g 熟白芝麻（可选），翻炒 5-10 秒即可关火出锅。"]]],["鸡腿去骨技巧（剪刀法）","把鸡腿洗干净，用厨房纸吸干表面水分。","从鸡腿较粗的一头找到骨头的末端。","用剪刀尖贴着骨头剪开外层的皮和肉，沿着骨头一侧剪到底。","把鸡腿翻个面，沿骨头的另一侧继续剪。","用手指把肉和骨头之间的连接处剥开。","找到骨头的关节处剪断，把骨头整根抽出。","整个过程不需要用刀，比传统的\"片开剔骨\"法安全很多，新手也能一次成功。","关于\"只需葱和鸡腿\"","这道菜的核心是葱和鸡腿，但只靠这两样会缺少层次。视频中使用的姜、花椒、蚝油、老抽、白芝麻都是为了让葱香和鸡香更立体。","极简版：只用葱 + 鸡腿 + 盐 + 生抽 + 糖也能做出来，但葱香会比较单一。","推荐版：加上姜、花椒、蚝油，香味会丰富很多。","完美版：再加点老抽上色 + 熟白芝麻点缀，卖相和口感都能上一个台阶。","储存与回热","冷藏保存：密封后放冰箱冷藏，可保存 2 天。","冷冻保存：放凉后分装冷冻，可保存 1 个月。","回热方式：微波炉中火加热 2 分钟，或回锅加一点点水翻炒。"]],["81dc908df0","带把肘子是陕西大荔的传统名菜，因脚爪形似把柄而得名。成菜肘皮胶粘软糯，肉质酥烂不腻，蘸甜面酱佐葱段食用，咸香醇厚。富含胶原蛋白和优质蛋白质，滋补养颜。制作需去骨、定形、长时间蒸制，对新手有一定挑战，预计整个制作过程约需 3.5 小时。",[["原料","带脚、爪猪前肘","f",0],["原料","红豆腐乳","f",0],["原料","甜面酱","s",0],["原料","精盐","s",0],["原料","红酱油","s",0],["原料","白酱油","s",0],["原料","料酒","s",0],["原料","蒜片","f",0],["原料","姜末","f",0],["原料","八角","f",0],["原料","桂皮","f",0],["原料","葱","f",0],["工具","小斧头（砸断骨头用）","f",0],["工具","消毒纱布（能盖住肘子）","f",0]],[["参考用量",[["带脚、爪猪前肘: 一个（大约二斤五两","1250 克）","f"],["红豆腐乳: 1 块","10 克","f"],["甜面酱:","150 克","f"],["精盐:","15 克","f"],["红酱油:","35 克","f"],["白酱油:","25 克","f"],["料酒:","25 克","f"],["蒜片:","50 克","f"],["姜末:","10 克","f"],["八角:","3 个","f"],["桂皮:","5 克","f"],["葱:","200 克","f"]],["每份：三人量"]]],[["制作步骤",["将肘子刮洗干净，肘头朝外、肘把（脚爪）朝里、肘皮朝下放在案板上。","用刀在正中由肘头向肘把沿着腿骨将皮剖开，剔去腿骨两边的肉（三面离肉），底部骨与肉相连，使骨头露出，然后将两节腿骨由中间用刀背（还是用斧头吧）砸断。","肘子放入煮锅煮至七成熟捞出（外观正常，内部淡红色），用干净抹布擦干水，趁热用红酱油涂抹肉皮。","取蒸锅一个，锅底放入八角、桂皮，先将肘把的关节处用手掰断，不伤外皮，再将肘皮朝下装进蒸锅内，装锅时根据肘子体型，将肘把贴住锅边窝着装进锅内，成为圆形。","撒入精盐，用消过毒的干净纱布盖在肉上，再将甜面酱（50 克）、葱（75 克）、红豆腐乳、红酱油、白酱油、姜、蒜等在纱布上抹开，用旺火蒸大约三小时（以蒸烂为准）。","蒸完取出，揭去纱布，扣入盘中，拣去八角，上桌时另带葱段和甜面酱小碟（或将甜面酱抹到肘面上，另带葱段小碟亦可）。"]]],["肘子七成熟要根据实际情况判断，有条件可询问家中长辈。","蒸锅下半放水，上半放肘子，蒸时及时加水防止蒸干。"]],["b00a0e1604","冬瓜酿肉是一道荤素搭配的家常蒸菜，口感鲜嫩爽滑，肉馅的咸香与冬瓜的清甜相互融合，清爽不腻。猪肉末提供优质蛋白质和必需氨基酸，冬瓜则有助于清热利尿、补充水分。做法简单，即使是新手也能轻松上手，只需稍加练习卷肉技巧即可。从备料到出锅，大约需要 30 分钟。",[["必备","冬瓜","f",0],["必备","猪肉末","f",0],["必备","鸡蛋","f",0],["必备","葱","f",0],["必备","葱姜末","f",0],["必备","胡椒粉","s",0],["必备","生抽","s",0],["必备","淀粉","s",0]],[["参考用量",[["猪肉末","300g","f"],["鸡蛋","1 个（可选,不习惯的人可能会有点腥）","f"],["冬瓜","200g","f"],["葱花（一根,约","20g）","f"],["胡椒粉","5g","s"],["生抽","10ml","s"],["淀粉","5g","s"],["水淀粉","25g（淀粉 25g,水 50ml）","s"],["葱姜末（姜","3-4 片约 30g, 取上面一根葱花中的葱白部分即可）","f"],["盐","20g","s"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["冬瓜去皮，切成 25cm 长 3cm 厚的片","将切好的冬瓜放入碗中，放入 15g 盐，将冬瓜抹匀，放置 10 分钟","放置冬瓜的同时，换个碗放入肉末，葱姜末， 5g 盐，淀粉 5g，胡椒粉，生抽，胡椒粉","使用筷子在肉末中进行顺时针搅拌，搅拌到食材颜色没有明显对比（约 2 分钟）","将腌制好的冬瓜（会变软）使用清水洗三遍","拿出 1 片冬瓜片卷起来，并把肉塞进去","放入碟子中摆到碟子的边缘","打入 1 个鸡蛋到中间圆圈处","放入普通铁锅中水烧开后，蒸 15 分钟，盖上锅盖","开盖，取出蒸好的冬瓜酿肉","将冬瓜酿肉碟子的水倒入锅中，放入水淀粉，加入 50ml 清水倒入锅中烧开","淋到冬瓜酿肉上"]]],["操作时，拿出冬瓜酿肉时注意碟子很烫，小心操作。","参考资料：b站视频"]],["93dbffaee0","豆豉鲮鱼油麦菜是一道咸香下饭的快手家常小炒，源于粤式罐头菜肴，油麦菜清脆、鲮鱼酥香。荤素搭配，富含蛋白质和膳食纤维。做法简单，对新手十分友好，一般十五分钟即可完成。",[["必备","油麦菜","f",0],["必备","甘竹牌鲮鱼罐头","f",0],["必备","蒜","f",0],["必备","生抽","s",0],["必备","白糖","s",0],["必备","食用油","s",0]],[["参考用量",[["油麦菜","500g","f"],["鲮鱼罐头","1 罐（250g 上下）","f"],["蒜","4 瓣","f"],["生抽","20g","s"],["白糖","3g","s"],["食用油","15ml","s"]],["每份（约 2 人份）："]]],[["制作步骤",["食材处理：","油麦菜洗净后切段","鲮鱼罐头打开后，把鲮鱼主刺去除，切成小段后备用","大蒜切成末","炒制过程：","锅热倒入食用油，油热后加入洗净的油麦菜，炒到萎蔫出水后盛出备用，倒掉炒制出的水分","重新热锅后，加入鲮鱼罐头中的油，放入蒜末煸香","蒜末煸香后加入鲮鱼罐头中的豆豉，翻拌后加入切碎的鲮鱼块，再次翻拌","翻拌均匀后加入油麦菜，加入生抽和糖调味","调味加入后简单翻拌即可出锅装盘"]]],["注意事项：","鲮鱼罐头本身带味道，加入生抽后够味，无需下盐"]],["0ca4f99328","这款意式风味酱料香浓可口，蔬菜与牛肉的搭配带来丰富口感。它富含蛋白质和多种维生素，营养均衡。制作过程稍有繁琐，需要一些烹饪基础，例如炒出颗粒感的牛肉和控火慢煮。从备料到完成约需一小时，一次可多做一些冷冻保存，随取随用十分方便。",[["必备","碎牛肉","f",0],["必备","蒜瓣","f",0],["必备","胡萝卜","f",0],["必备","芹菜","f",0],["必备","洋葱","f",0],["必备","橄榄油","s",0],["必备","糖","s",0],["必备","食盐","s",0],["必备","胡椒粉","s",0],["必备","番茄酱","s",0],["必备","牛奶","f",0],["必备","干罗勒或百里香（可选）","f",1]],[["参考用量",[["碎牛肉","500g","f"],["蒜瓣","2 个","f"],["胡萝卜","半根","f"],["芹菜","一根","f"],["洋葱","半个","f"],["橄榄油","","s"],["糖","2g","s"],["食盐","10g","s"],["黑胡椒粉","5g","s"],["番茄酱","300g","s"],["牛奶","300ml","f"]],["每份："]]],[["制作步骤",["将胡萝卜、芹菜、洋葱切碎，蒜瓣切片。","加入 10ml 橄榄油，热油下锅蔬菜，大火翻炒开始略微变色后盛出。","锅内加油 10ml，加蒜翻炒 10 秒，加入碎牛肉、糖、盐、胡椒粉和香料将牛肉炒脆（有颗粒感）。","加入炒好的蔬菜们和番茄酱继续翻炒，搅拌均匀。","分多次缓缓倒入牛奶，中小火煮 30 分钟，完成。"]]],["考虑各个品牌的番茄酱内含盐量不同，建议在炒牛肉时少放盐，煮的时候尝一下再调味","煮酱料期间请搅动，以免粘锅。如果酱料变粘稠就可以出锅啦！","可根据个人口味，将碎牛肉替换成一半碎猪肉一半碎牛肉，牛奶替换成鸡汤或饮用水。"]],["73dfeec2cb","粉蒸肉是一道经典中式蒸菜，香味浓郁，口感软糯，属于广泛流传的家常风味。五花肉提供优质蛋白质和脂肪，搭配土豆等根茎蔬菜，营养均衡。此菜适合有一定烹饪经验的人士制作，从准备到完成大约需要 90 分钟。",[["必备","五花肉 500g（肥瘦相间）","f",0],["必备","蒸肉米粉 100g（推荐使用李锦记或自制）","f",0],["必备","生抽 15ml","f",0],["必备","老抽 10ml","f",0],["必备","料酒 15ml","f",0],["必备","郫县豆瓣酱 10g（可选）","f",1],["必备","姜末 10g","f",0],["必备","蒜末 10g","f",0],["必备","白砂糖 5g","f",0],["必备","土豆 300g（或南瓜 300g，作为垫底食材）","f",0],["必备","清水（蒸锅用）2000ml","f",0]],[["参考用量",[["五花肉","250g","f"],["蒸肉米粉","50g","f"],["生抽","7.5ml","s"],["老抽","5ml","s"],["料酒","7.5ml","s"],["郫县豆瓣酱","5g（可选）","s"],["姜末","5g","f"],["蒜末","5g","f"],["白砂糖","2.5g","s"],["土豆或南瓜","150g","f"],["蒸锅用水","1000ml","f"]],["每次制作前需要确定计划做几份。一份正好够 3 个人吃。","每份："]]],[["制作步骤",["将五花肉洗净，切成长约 5cm、宽约 3cm、厚度约 0.5cm 的肉片","将姜、蒜切成颗粒直径不大于 1mm 的细末","取一大碗，放入切好的五花肉、15ml 生抽、10ml 老抽、15ml 料酒、10g 郫县豆瓣酱、10g 姜末、10g 蒜末、5g 白砂糖","用筷子搅拌均匀后，盖上保鲜膜，室温(20°C - 25°C)静置腌制 30 分钟","腌制完成后，加入 100g 蒸肉米粉，继续翻拌 2 分钟，确保每片肉都均匀裹粉","土豆去皮，切片厚度控制在 0.8cm，片面积约为 5cm x 5cm，重量控制在 300g","在直径 20cm 的深碗底部铺满土豆片，尽量无重叠","将拌好粉的五花肉均匀铺在土豆片上，压实","蒸锅中加入 2000ml 清水，开火加热至水面持续冒泡(100°C)","将装好食材的碗放入蒸锅内，盖好锅盖","保持中火蒸 60 分钟（火力保持在可持续沸腾的程度，约 600W 热功率）","时间结束后，用筷子插入肉块中央，若能轻松穿透并无明显阻力，则表明蒸熟","若未达到此状态，则继续加热 10 - 15 分钟，直至肉质软烂，油脂渗出","取出盛盘，即可食用"]]],["如需自制米粉，可将大米 150g 放入锅中，中小火炒至微黄色（约 8 分钟），再加入干辣椒 1g、花椒 1g、八角 0.5g，炒香后用料理机打碎，过筛备用","蒸制期间如水量低于锅底高度 1cm，应立即补充 500ml 热水（90°C 以上），以维持蒸汽充足"]],["43d8d58a41","这是一道经典的江南家常菜，五花肉与红腐乳同炖，色泽红亮如琥珀，肉质酥烂到入口即化，咸甜交织的酒香与豆香在舌尖层层展开。富含优质蛋白质和 B 族维生素，经慢火煨煮后更易消化。制作流程需要耐心把控火候和收汁，对新手来说有一定挑战，预计制作时长约 1 小时。",[["必备","带皮五花肉","f",0],["必备","红腐乳（推荐咸亨牌玫瑰腐乳）","f",0],["必备","冰糖","s",0],["必备","老抽","s",0],["必备","料酒","s",0],["必备","香葱（可选）","f",1],["必备","生姜","f",0],["必备","清水","f",0],["必备","食用油","s",0]],[["参考用量",[["带皮五花肉","400 g","f"],["红腐乳","30 g（约 2 块）","f"],["腐乳汁","15 ml","f"],["冰糖","25 g","s"],["老抽","5 ml","s"],["料酒","15 ml","s"],["葱白","15 g","f"],["葱花","5 g","f"],["生姜","10 g","f"],["清水","500 ml","f"],["食用油","10 ml","s"]],["每次制作前需要确定计划做几份。一份大约够 2 个人吃。","每份："]]],[["制作步骤",["五花肉切成长宽 2.5 cm 的小块","冷水放料酒姜片，五花肉放入开火慢慢加入到水沸腾后捞出","玫瑰腐乳块和腐乳汁碾成泥，加冰糖、老抽调成酱汁","热锅冷油爆香葱姜，下肉块煸到金黄","倒入腐乳酱炒匀加热水焖煮","小火慢炖 40 分钟","大火收汁，看到汤汁冒浓稠鱼眼泡时关火"]]],["建议用单晶冰糖","腐乳自带咸鲜，不用额外放盐","大火收汁时要不断晃动锅体避免粘底","参考资料：【步骤图】腐乳肉的做法腐乳肉的做法步骤菜谱下厨房"]],["b3ce433a03","这是一道源自北大食堂、甜辣风味的创新川菜，鸡肉先腌后炸，外酥里嫩，土豆香糯，青椒脆爽，裹满红亮的甜辣酱汁，咸甜微辣十分开胃。富含蛋白质、碳水化合物及维生素。制作涉及油炸和酱汁熬制，对新手稍有挑战，但按步骤操作即可成功，全程约需 1 小时。",[["必备","鸡腿","f",0],["必备","土豆","f",0],["必备","青椒","f",0],["必备","大蒜","f",0],["必备","盐","s",0],["必备","胡椒粉","s",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","料酒","s",0],["必备","淀粉","s",0],["必备","郫县红油豆瓣酱（注意区分，不是那种棕黄色的豆瓣酱）","s",0],["必备","白糖","s",0],["必备","花椒碎","f",0]],[["参考用量",[["鸡腿肉","400g","f"],["土豆","200g","f"],["青椒","60g","f"],["蒜瓣","10g","f"],["盐","3g","s"],["鸡精","3g （可选）","s"],["胡椒粉","2g","s"],["生抽","5g","s"],["老抽","2g","s"],["料酒","5g","s"],["淀粉","20g","s"],["郫县红油豆瓣酱","40g","s"],["白糖","30g","s"],["花椒碎","2g","f"]],["1-2 人份："]]],[["制作步骤",["鸡腿去骨（如使用鸡腿排可忽略此步骤），鸡腿肉用刀背砸一砸，切成 2cm 的块。","鸡腿肉中加入盐、鸡精（可选）、胡椒粉、生抽、老抽、料酒，抓拌至粘手时加入淀粉拌匀，加入食用油防止粘连，腌制 30 分钟。","土豆去皮，切成 2cm 的块，沸水煮 5 分钟后捞出，控干水分，防止油炸时爆锅。","青椒去籽，切成 2cm 小片，放在笊篱中备用。","锅中加入宽油（根据锅的形状，能没过食材即可），油温烧至 180℃ 时，下入土豆块炸 3 分钟后捞出。","待油温再次升高到 180℃时，下入鸡块炸 2 分钟后捞出。","待油温再次升高到 180℃时，下入鸡块复炸 1 分钟后捞出。","待油温再次升高到 180℃时，下入土豆块复炸 1 分钟后，将锅中的油和土豆块经过笊篱过滤倒出，让笊篱上的青椒片断生。","锅中加入 5ml 食用油，小火煸炒蒜瓣至发黄，下入红油豆瓣酱煸炒出香，下入白糖炒融化，下入花椒碎，加 40ml 清水，不停搅拌至酱汁粘稠。","下入炸好的鸡块、土豆块、青椒片，搅拌均匀后出锅。"]]],["不舍得使用宽油油炸的话，可改用更少的油煎鸡块和土豆块。会增长用时，部分影响口感，但不会影响总体味道。","参考资料：北大餐饮中心官方资讯"]],["54eb66b2b1","这道川味名菜以糊辣荔枝味见长，小酸甜中透着干辣椒与花椒的香气，鸡丁嫩滑、花生酥脆，口感层次丰富。富含优质蛋白和不饱和脂肪酸，开胃下饭。做法分成简易和进阶两版，对新手比较友好，提前规划好腌制时间即可。从备料到出锅大约需要 1.5 小时。",[["必备","手枪腿（或者鸡胸脯肉）","f",0],["必备","大葱","f",0],["必备","干辣椒（或者二荆条）","f",0],["必备","熟花生","f",0],["必备","生抽酱油","s",0],["必备","香醋","s",0],["必备","白糖","s",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","鸡精","s",0],["必备","淀粉","s",0],["必备","植物油","s",0],["必备","芝麻油","s",0],["可选原料","油泼辣子","f",1],["可选原料","莴笋","f",1],["可选原料","生花生","f",1],["可选原料","豆瓣酱","s",1]],[["参考用量",[],["注意，这道菜默认一人版本，两人也够吃，理论上多人只需简单加倍即可。"]],["必须配料",[["手枪腿（或者鸡胸脯肉）","1 支（约 350g）","f"],["大葱","1 根（约 180g）","f"],["熟花生","150g","f"],["姜片","10g","f"],["干辣椒（或者二荆条）","10g（若选择二荆条，则需要大约 4 支）","f"],["生抽酱油","10g","s"],["白糖","2g","s"],["盐","2g","s"],["植物油","20g","s"],["淀粉","15g","s"],["料酒","15g","s"]],[]],["进阶配料",[["老抽酱油","5g","s"],["花椒","5g","s"],["香醋","5g","s"],["鸡精","2g","s"],["芝麻油","10g","s"],["淀粉（用以勾芡）","10g","s"],["豆瓣酱","10g","s"]],[]],["可选配料",[["莴笋","约 250g","f"],["油泼辣子","5g","f"]],["使用上述条件，计算出计划使用的原材料比例，依口味调整。"]]],[["简易版本",["手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）","取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用；取花生放入微波炉高火 5 分钟焙干备用","鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时","干辣椒切段；起锅，大火烧热转小火；放入干辣椒焙干至微微发糊，捞起备用；花椒焙干至有香味，捞起备用","转大火，倒入 20g 植物油，7 成热（竹筷子起泡）下入鸡丁，煎至上面开始发白，用锅铲翻面，煎 30s 后翻炒均匀","下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；盖上锅盖，转中小火焖 2 分钟；","转大火，下入熟花生，干辣椒和花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；","淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度","关火，淋入芝麻油 10g，即可出锅"]],["稍加复杂但是更加令人垂涎欲滴的版本",["相较于简单版本，这里更加推荐使用二荆条与生花生。并且加入了莴笋陪衬花生的香脆与鸡肉的松软","莴笋去皮切至 1cm 见方的小块，备用；","二荆条切成 1cm 长段；","手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）；","取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用","鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时","转中火，倒入 20g 植物油，放入生花生翻炒至其表面微微焦糊，捞起花生但是油留在锅内；","继续加热，7 成热（竹筷子起泡）下入鸡丁，放入豆瓣酱，翻炒大概 1 分钟；","加入备好的莴笋丁，继续翻炒 1 分钟；","下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；加入二荆条段；盖上锅盖，转中小火焖 2 分钟；","转大火，下入先前捞起来备用的花生，花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；","淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度","关火，淋入芝麻油 10g 与油泼辣子 5g 再翻炒 10s，即可出锅"]]],["辣椒依据个人口味酌量添加，怕辣可去籽；"]],["5486108617","咕噜肉是一道经典粤式家常菜，酸甜开胃、外酥里嫩，菠萝的果香让肉块吃起来格外清爽解腻。猪肉提供优质蛋白质，青椒和菠萝则补充维生素与膳食纤维。这道菜的难点在于掌握炸肉的火候，对新手略有挑战，但只要按步骤操作便能成功。从腌制到出锅，全程大约需要 40 分钟，很适合为家人做一道下饭快菜。",[["必备","梅头猪肉","f",0],["必备","青椒","f",0],["必备","罐头菠萝片","f",0],["必备","盐","s",0],["必备","茄汁","f",0],["必备","白醋","s",0],["必备","蒜蓉","f",0],["必备","生抽","s",0],["必备","生粉","f",0],["必备","白砂糖","s",0]],[["参考用量",[["1 汤匙","15ml","f"],["1 茶匙","5ml","f"],["梅头猪肉","100g","f"],["青椒","25g","f"],["罐头菠萝片","75g","f"],["盐","1/4 茶匙","s"],["茄汁","4 汤匙","f"],["白醋","2 茶匙","s"],["蒜蓉","1 汤匙","f"],["生抽","1/2 茶匙","s"],["生粉","2 1/2 茶匙","f"],["白砂糖","2 汤匙","s"],["水","200 毫升","f"]],["每份："]]],[["制作步骤",["将梅头猪肉（100 克）洗净，然后用厨房纸抹干水份，将猪肉切成比想要的成品小一圈的大小。","用盐（1/2 茶匙）腌制梅头猪肉 20 分钟。","将青椒（25 克）切碎。","将菠萝片（75 克）切件。","在碗中加入茄汁（4 汤匙）﹑白醋（2 茶匙）﹑蒜蓉（1 汤匙）﹑生抽（½ 茶匙）﹑生粉（2½ 茶匙）﹑白砂糖（2 汤匙）﹑盐（¼ 茶匙）和水（200 毫升），拌匀成酱汁。","将梅头猪肉粒沾上生粉（6 汤匙）。","加入油（500 毫升）中火加热。","将梅头猪肉粒放至锅里中火炸 5 分钟，然后盛起。","加入梅头猪肉粒，再大火翻炸 1 分钟。","加入油（1 茶匙）和酱汁，中火加热 3 分钟。","加入青椒和菠萝，大火加热 2 分钟。","将已炸好的梅头猪肉粒与酱汁拌匀即可。"]]],["想让肉更有层次可以在生粉中加鸡蛋，炸出来会更香脆"]],["06a3cb7222","这是一道广式家常炖菜，牛腩软烂入味，萝卜吸饱汤汁后清甜浓郁，整体酱香回甘。富含优质蛋白和膳食纤维，开胃助消化。制作步骤稍多但难度适中，新手按部就班也能成功。预计从头到尾大约需要 2.5 小时完成。",[["必备","牛腩","f",0],["必备","白萝卜","f",0],["必备","姜片","f",0],["必备","蒜瓣","f",0],["必备","葱","f",0],["必备","八角","f",0],["必备","桂皮","f",0],["必备","干辣椒","f",0],["必备","香叶","f",0],["必备","南乳","f",0],["必备","柱侯酱","s",0],["必备","蚝油","s",0],["必备","酱油","s",0],["必备","冰糖","s",0],["必备","盐","s",0],["必备","老抽","s",0]],[["参考用量",[["牛腩","500g","f"],["白萝卜","1 根","f"],["姜片","8 片","f"],["蒜瓣","5 片","f"],["葱结","一把","f"],["八角","2 片","f"],["桂皮","1 小块","f"],["干辣椒","2 个","f"],["香叶","2 片","f"],["南乳","1 块","f"],["柱侯酱","30g","s"],["蚝油","15g","s"],["酱油","15g","s"],["冰糖","10g","s"],["盐","5g","s"],["老抽","15g","s"]],["一份正好够 3-4 人吃。"]]],[["开始制作",["萝卜滚到切块备用","牛腩整块焯水，加入 2 片姜和一把葱结，等水开之后煮 5-10 分钟，然后捞出切件","将牛腩切块，切成自己喜欢的大小（牛腩焯过水，待会儿焖的时候基本不会缩水了，大块的会焖相对就一点的时间）","准备焖牛腩的酱料，将南乳、柱侯酱、酱油、蚝油、糖、盐按上面的量调和（冰糖刚刚没了换成了白糖）","热锅下油，将姜蒜爆香，放入牛腩，炒至干身，加入调好的酱料，炒香，如果喜欢色泽浓一点的可以加一点老抽润色一下","调料充分混合之后倒入热水","将牛腩换到汤锅中，放入桂皮、八角、香叶和干辣椒，焖大概 2 个小时","牛腩焖到半软之后加入白萝卜继续焖 30 分钟","等到萝卜焖软之后就完成，一锅浓香的萝卜牛腩就完成了"]]],[]],["8a6a6f8648","贵州辣子鸡是贵州地区的经典家常菜，以糍粑辣椒和多种香料烹制而成，鸡肉香糯软烂，土豆绵密入味，整体风味香辣浓郁。鸡肉富含优质蛋白质，搭配土豆等配菜，营养均衡。这道菜步骤较多，对新手有一定挑战，但按部就班也能成功。从备料到出锅，预计需要 1.大约 5 小时。",[["必备","农村玉米鸡","f",0],["必备","土豆","f",0],["必备","大蒜","f",0],["必备","香叶","f",0],["必备","姜","f",0],["必备","老抽","s",0],["必备","花椒 or 麻椒","f",0],["必备","糍粑辣椒（花溪党武的辣椒，遵义的子弹头，条子椒，大方的皱椒混合之后打碎的辣椒）","f",0],["必备","豆瓣酱","s",0],["必备","啤酒","f",0],["必备","蒜苗","f",0],["必备","酒糟","f",0],["必备","食用油","s",0]],[["参考用量",[["鸡三到四个人的量是四斤，人多可以依次累加","","f"],["啤酒半瓶","","f"],["姜手指头大小两个","","f"],["糍粑辣椒","500g，会是拳头大小两坨","f"],["蒜苗三根","","f"],["香叶","2 片","f"],["大蒜两个","","f"],["土豆两个","","f"],["菜籽油两斤，开始炸鸡会用很多","","f"],["老抽","20 ml","s"]],["每份："]]],[["制作步骤",["在锅中加入和锅一半高度的油，将切成长条的土豆先炸至表面金黄然后捞出备用，等油温上至烤手时候将切好的鸡块放入锅中炸，并放入切好的生姜片和花椒","刚开始炸鸡的时候，油是浑浊的，因为鸡块里面有水的原因，等到油炸至清澈，鸡块就炸好了，然后捞出备用","现在锅里面的油可以捞三分之一出来，现在用不到这么多的油","将锅中剩余的油加热，加入糍粑辣椒，豆瓣酱，生姜片，炒出红油状，将炸好的鸡块翻炒均匀","等到鸡块都上色，加入老抽，倒入啤酒，啤酒一定要盖过鸡块，加上香叶盖上盖，闷十分钟，期间间隔翻炒","然后加入土豆条，大蒜（不用切，一颗一颗的最好），然后再闷 20 分钟","最后加入酒糟翻炒均匀再加入切好的蒜苗，就可以出锅了"]]],["操作时，需要注意翻炒，因为糍粑辣椒会糊掉"]],["8e00f49894","桂林传统酿菜系列，将调好味的猪肉、虾滑等馅料酿入青椒、苦瓜、田螺、茄子等十多种中空食材中，煎焖成菜，一菜一味，鲜香多汁，口感软嫩或弹牙，属于浓郁的地方家常风味。馅料提供优质蛋白质，搭配多种蔬菜，富含维生素与膳食纤维，营养较为均衡。制作步骤需要逐一填馅和掌控火候，稍需耐心，但操作逻辑简单，厨艺新手也能尝试，预计全部完成约需 1.5 小时。",[["必备","青椒、苦瓜、茄子、田螺、豆腐、香菇、南瓜花","f",0],["必备","柚子、笋、冬瓜、香芋、蒜、番茄、豆芽、蛋、香菌","f",0],["必备","原则：万物皆可酿","f",0],["必备","猪肉馅（基础款，肥瘦比例 3:7）","f",0],["必备","虾滑馅（fork 版本）","f",0],["必备","鱼肉馅","f",0],["必备","混合馅（猪肉 + 虾滑，猪肉 + 螺肉等自由组合）","f",0]],[["参考用量",[],["18 种容器 × 4 种馅料 = 72 种组合，实际常用组合约 20 余种。","核心公式：管状物 + 肉馅 + 煎/焖 = 酿"]]],[["核心思路",["所谓\"酿\"，就是找一个中空的管状食材作为容器，把调好味的肉馅塞进去，再煎或焖熟。","以两道已收录的酿菜为例：","青椒酿：青椒去籽挖空 → 塞入猪肉馅或虾滑 → 煎至虎皮色 → 酱汁焖煮","田螺酿：田螺焯水取肉 → 螺肉与猪肉剁碎混合 → 塞回螺壳 → 紫苏薄荷焖煮","换成其他管状食材，同样的工序再来一遍，就是一道新菜。苦瓜酿、茄子酿、豆腐酿……皆是如此。","酿心（馅料）同样可以变化：","猪肉馅：最基础通用的选择，肥瘦 3:7 口感最佳","虾滑馅：鲜甜弹牙，青椒酿里常用","螺肉猪肉混合馅：田螺酿的灵魂，螺肉与猪肉 1:1，加紫苏薄荷","混合馅：猪肉 + 虾滑混搭，鲜甜与油脂香兼得","一个容器配一种馅，换一个就是一道新酿。当地有\"万物皆可酿\"的说法，正是这个道理。"]],["桥接模式(Bridge Pattern)",["将\"容器\"与\"馅料\"解耦，二者独立变化、自由组合：","抽象层（Abstract Wrapper）：管状物（CylindricalContainer）","├── 青椒酿 extends CylindricalContainer","├── 苦瓜酿 extends CylindricalContainer","├── 茄子酿 extends CylindricalContainer","├── 螺蛳酿 extends CylindricalContainer","├── 豆腐酿 extends CylindricalContainer","├── 香菇酿 extends CylindricalContainer","├── 南瓜花酿 extends CylindricalContainer","├── 柚子酿 extends CylindricalContainer","├── 笋酿 extends CylindricalContainer","├── 冬瓜酿 extends CylindricalContainer","├── 香芋酿 extends CylindricalContainer","├── 蒜酿 extends CylindricalContainer","├── 番茄酿 extends CylindricalContainer","├── 豆芽酿 extends CylindricalContainer","├── 蛋酿 extends CylindricalContainer","├── 香菌酿 extends CylindricalContainer","└── ... 万物皆可酿","实现层（Filling Implementation）：肉馅（MeatFilling）","├── 猪肉馅 implements MeatFilling","├── 虾滑馅 implements MeatFilling","├── 鱼肉馅 implements MeatFilling","└── 混合馅 implements MeatFilling // 猪肉 + 虾滑，猪肉 + 螺肉...","换一个 wrapper 就是一道新菜，换一种 filling 又是一个变体。"]]],["已有菜谱","青椒酿 — 青椒酿肉 / 虾滑酿青椒（fork 版本）","田螺酿 — 螺肉猪肉 1:1，配紫苏薄荷","酿菜图鉴"]],["582b979497","荷兰豆炒腊肠是一道清爽咸香的家常小炒，腊肠的油脂润着翠绿的荷兰豆，口感脆嫩不腻。荷兰豆富含优质蛋白质和多种维生素，有助于增强机体抗病能力。做法简单，几乎不需要刀工，初学者也能快速上手，从备料到出锅大约只需 15 分钟。",[["必备","荷兰豆","f",0],["必备","腊肠","f",0],["必备","生抽","s",0],["必备","食用油","s",0]],[["参考用量",[["荷兰豆大约","50 个","f"],["腊肠约","100 g","f"],["食用油","10ml","s"],["生抽","10ml","s"]],["下面是一人份。","每份："]]],[["制作步骤",["把荷兰豆去掉蒂，有时间的也可以同时把尾部去掉","买腊肠之前可以问老板是生的还是熟的，如果是生的，需要提前蒸一下，如果是熟的可以直接使用","把荷兰豆清洗一下，然后焯一下水，大概 45s，荷兰豆焯至变色即可，捞出过凉水备用","热锅，锅内放入大约 10ml 食用油。等待 10 秒让油温升高","放入腊肠，保持翻炒至腊肠微微卷边，注意这里一定要保持小火，小到不能小的那种，不然容易糊","放入荷兰豆，转为中大火，翻炒 30s 放入生抽，接着再翻炒 20-30s 即可"]]],["在制作过程中没有放盐，是因为腊肠本身会有一些味道，同时生抽也会有一些咸味。","腊肠虽然味道不错，但属于不太健康的食物，建议少放。"]],["4dd2ff761a","黑椒牛柳是一道广受欢迎的家常小炒，黑椒风味浓郁，牛柳嫩滑，搭配甜脆的洋葱和彩椒，荤素均衡，口味老少咸宜。牛肉富含优质蛋白和铁，彩椒和洋葱能补充多种维生素。这道菜对新手十分友好，从备料到出锅，通常一小时以内就能完成。",[["必备","牛肉（可以用牛里脊肉或者牛排肉）","f",0],["必备","洋葱","f",0],["必备","菜椒（红/黄椒）","f",0],["必备","淀粉","s",0],["必备","黑胡椒（粉）","s",0],["必备","黑椒（腌料）","f",0],["必备","盐","s",0],["必备","花生油","s",0]],[["参考用量",[["牛肉量","份数 100 克 （视就餐者胃容量和锅容量酌情增减）","f"],["洋葱量","份数 1/12 个（即 3 人时约切 1/4 ）","f"],["菜椒量","份数 1/12 个（即 3 人时约切 1/4 ）","f"],["盐量","份数 1 克","f"],["淀粉","份数 3 克","s"],["黑椒腌料","参照所购商品的说明按比例腌制","f"],["黑胡椒粉","份数 1 克（实际上是随便撒）","s"],["花生油","份数 10ml （实际上油量是依据菜量变动的，如对牛肉的量有增减请按对应比例变动）","s"]],["每次制作前需要确定计划做几份。一份正好够 2-3 个人食用","总量：","使用上述条件，计算出计划使用的原材料比例。"]]],[["制作步骤",["将牛肉切条，长度最好控制在 8 厘米以下，厚度约 5-10 毫米，宽度约 1 厘米（要求不严格）","利用腌料腌制牛肉，混合均匀后静置，用量与时间请参照商品说明，可以延长不能缩短。","如果使用液态腌料，可以在腌制结束前三分钟撒一层黑胡椒粉，然后再加入淀粉，再次混合均匀后静置 20 分钟。","开火，热锅，加入花生油。","当能看到锅里的油冒出一丝烟时，放入牛肉，翻炒。","开中火偏大，翻炒 2 分钟至牛肉外表变色（即不出现明显血色，有血色部分说明翻炒不到位）（此处应小心油滴溅射）。","放入洋葱和菜椒，翻炒 2 分钟。","加入盐，再次撒一份黑胡椒粉，翻炒 30 秒，搅拌均匀。","观察洋葱已经变软即可关火，出锅，盛盘。"]]],[]],["1464c9472e","红烧鸡翅是一道家常下饭菜，咸鲜带甜、色泽红亮，肉质嫩滑易脱骨。鸡翅富含优质蛋白质与胶原蛋白，营养好吸收。制作难度适中，新手按步骤操作也能顺利掌握，从备料到出锅大约需要 40 分钟。",[["必备","新鲜鸡翅（推荐选择鸡翅中，肉质更嫩）","f",0],["必备","姜片（推荐使用生姜，去腥效果更佳）","f",0],["必备","葱段（推荐使用大葱白部分，香味更浓郁）","f",0],["必备","大蒜","f",0],["必备","香叶","f",0],["必备","八角","f",0],["必备","干辣椒（可选，不吃辣可省略）","f",1],["必备","冰糖","s",0],["必备","黄酒或料酒（二选一即可，黄酒风味更醇厚）","s",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","盐","s",0],["必备","白糖","s",0],["必备","胡椒粉（推荐白胡椒粉，辛辣味较淡）","s",0],["必备","白芝麻（熟）","f",0],["必备","小葱花（点缀用）","f",0]],[["参考用量",[["新鲜鸡翅","500g（约 8-10 个，单个鸡翅约 50-60g）","f"],["姜片","4-5 片（约 10g，切片厚度约 2mm）","f"],["葱段","2-3 段（约 15g，每段长度约 3cm）","f"],["大蒜","3-4 瓣（约 15g）","f"],["香叶","1 片","f"],["八角","1 个","f"],["干辣椒","2 个（可选，约 5g，不吃辣可省略）","f"],["冰糖","15g（颗粒状冰糖）","s"],["黄酒或料酒","35ml","s"],["生抽","15ml","s"],["老抽","5ml","s"],["盐","3g","s"],["白糖","2g","s"],["胡椒粉","1g","s"],["白芝麻","3g","f"],["小葱花","5g","f"],["食用油","10-15ml","s"]],["每次制作前需确定计划做几份，一份够 3-4 人食用。","每份："]]],[["制作步骤",["将鸡翅洗净。用刀在鸡翅厚处划三刀，背面扎一刀，便于入味。","如果鸡翅不新鲜，可在打完花刀之后用姜水泡 10-20 分钟。","将 10g 姜片（3-4 片）、15g 葱段（2-3 段）备好；3-4 瓣大蒜（约 15g）用刀拍散（无需剁碎）；1 片香叶、1 个八角、2 个干辣椒（可选）整理好备用。","起锅开火，锅中加入清水没过所有鸡翅，冷水下锅放入处理好的鸡翅，加入 20ml 黄酒或料酒、2 片姜片（约 5g），开大火烧至沸腾，沸腾后保持大火继续煮 2-3 分钟，撇去浮沫。","煮好后将鸡翅捞出，用温水清洗 2 遍，彻底去除血沫，控干水分备用。","另起锅，开火烧热后放入 10-15ml 食用油。","待油温至 5 成热，加入 15g 冰糖，开大火将冰糖熬至完全融化，冰糖融化变色后转小火，继续炒至冰糖呈枣红色，立即放入控干水分的鸡翅，快速翻炒 1-2 分钟，使每只鸡翅均匀裹上糖色。","加入准备好的 1 片香叶、1 个八角、2 个干辣椒（可选）、剩下的 2 片姜片（约 5g）、15g 葱段、拍散的大蒜，继续煸炒 30 秒至香料香味完全释放。","沿锅边淋入 15ml 料酒或黄酒，15ml 生抽，快速翻炒 10 秒。","加入温水（水温约 50-60℃），水量以稍微没过所有鸡翅为准。","加入 5ml 老抽、3g 盐、2g 白糖、1g 胡椒粉，用炒勺轻轻搅拌均匀。","盖上锅盖，开中火烧煮 7-8 分钟。","打开锅盖，用筷子将锅中的香叶、八角、姜片、葱段、大蒜捡出丢弃。","转大火，保持不断翻炒，将汤汁烧至粘稠状态（约 1-2 分钟）。","关火，将鸡翅盛入盘中，淋上锅中剩余的粘稠汤汁。","最后撒上 3g 白芝麻和 5g 小葱花，完成制作。"]]],["如果闻着有腥味，可以增加一倍香料用量。"]],["0a2190375a","红烧猪蹄是一道汤汁浓郁、肉质软糯的经典家常菜，咸香甜美，极为下饭。猪蹄富含胶原蛋白和蛋白质，营养丰富。这道菜对新手有一定挑战，但借助高压锅可以简化流程，有一定烹饪基础更易上手。从备料到完成大约需要 1 小时。",[["必备","猪蹄","f",0],["必备","香叶","f",0],["必备","姜","f",0],["必备","葱","f",0],["必备","老抽","s",0],["必备","桂皮","f",0],["必备","冰糖","s",0],["必备","料酒","s",0],["必备","生抽","s",0],["必备","盐","s",0],["必备","八角","f",0],["必备","食用油","s",0]],[["参考用量",[["猪蹄：23 根","","f"],["食用油：30ml","","f"],["香叶","2 片","f"],["姜","5 片","f"],["葱半根","","f"],["桂皮","1 块","f"],["冰糖","7-8 粒","s"],["料酒","30 ml","s"],["生抽","20 ml","s"],["老抽","20 ml","s"],["盐","8 克","s"],["八角","4 个","f"]],["一份正好够 3-4 人吃。"]]],[["开始制作",["冷水锅中放入热心摊主剁好的猪蹄，加入 20 ml 料酒与葱姜，煮 15 分钟去掉血腥","热锅冷油，倒入 30ml 食用油，放入 7-8 粒冰糖，开小火，熬成糖色，期间用锅铲把冰糖压碎，大概熬 2 分钟","熬成糖色后，放入焯过水的猪蹄，继续小火，翻炒猪蹄，直至所有猪蹄两面微黄","加入香叶 2 片、桂皮 1 块、八角 4 个、生抽 20 ml、老抽 20 ml、料酒 10 ml、姜 3 片、盐 8 克，转中火、继续翻炒 1 分钟","加入开水或者冷水，水需要没过猪蹄，盖上锅盖，大火烧开，烧开之后关火","把锅内的食材全部倒入高压锅中，高压锅中需要 15 分钟（如果同学没有高压锅，可放在锅中大火转小火熬制即可）","15 分钟之后，把高压锅的食材倒入炒锅中，开大火收汁，此时可用筷子尝下味道、淡的话可以加 23g 盐","大火收汁时长根据锅中的水来算，一般 30 秒即可，多留点也无碍、红烧猪蹄汤也是很下饭的"]]],[]],["107946c553","湖南家常红烧肉是一道湘味浓郁的家常菜，五花肉经慢炖后肥而不腻、入口软糯，咸香中带着微辣回甘。富含优质蛋白和脂肪，能为身体提供充足能量。制作需要一些耐心，对新手有一定挑战，但按步骤操作不难掌握，预计全程约 1 小时。",[["必备","带皮五花肉","f",0],["必备","干小米椒🌶（根据个人情况而定）","f",0],["必备","姜","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","香叶","f",0],["必备","桂皮","f",0],["必备","八角","f",0],["必备","冰糖","s",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","冰糖（锁油上色）","s",0],["必备","食用油","s",0],["必备","开水","f",0]],[["参考用量",[["五花肉：500g","","f"],["食用油：10g","","f"],["香叶","5 片","f"],["姜","3 片","f"],["桂皮","1 小块","f"],["冰糖","6 颗","s"],["料酒","20 克","s"],["生抽","5 克","s"],["老抽","2 克","s"],["盐","2 克","s"],["八角","3 颗","f"]],["一份正好够 2 人吃。"]]],[["制作步骤",["带皮五花肉洗净冷水下锅，加入姜片 23 片去腥味，煮到沸腾捞出冷水冲净白沫","五花肉切块，尺寸 1.5cm1.5cm 块状大小","热锅加入油，加入冰糖小火搅拌至焦糖色即可，加入切好的五花肉，中火翻炒上色","加入备好的姜片、八角、桂皮、生抽、老抽、料酒、干小米椒、盐，小火翻炒 1 分钟，加开水没过肉","加盖中火煮沸，转小火慢顿 30 分钟，慢炖期间，间隔 10 分钟搅拌一次防止粘锅","小火慢炖汤汁剩三分之一的时，调成中火收汁出锅。"]]],[]],["607035e51e","这道菜成品色泽红亮，肘皮呈现诱人的虎皮纹路，口感软烂入味，肥而不腻，瘦肉松软，属于传统中式宴客大菜。猪肘富含胶原蛋白和优质蛋白，经过长时间炖煮后更易吸收，对皮肤和关节有一定滋养效果。制作过程包含烧皮、油炸、炒糖色和高压炖煮等多个步骤，对新手来说挑战较大，建议有一定烹饪基础再尝试。从预处理到上桌，预计总耗时约 2.5 小时。",[["必备","猪前肘","f",0],["必备","食用植物油","s",0],["必备","冰糖","s",0],["必备","盐","s",0],["必备","老抽","s",0],["必备","生抽","s",0],["必备","白醋","s",0],["必备","香叶","f",0],["必备","肉桂皮","f",0],["必备","豆蔻","f",0],["必备","花椒","s",0],["必备","大料","f",0],["必备","淀粉","s",0],["必备","葱","f",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","水","f",0],["必备","料酒","s",0]],[["参考用量",[["1 汤匙","15ml","f"],["1 茶匙","5ml","f"],["猪前肘","数量：1；单位：个","f"],["食用植物油","数量：1；单位：桶","s"],["冰糖","数量：5；单位：桶","s"],["盐","数量：1-2；单位：茶匙","s"],["老抽","数量：1；单位：茶匙","s"],["生抽","数量：1；单位：汤匙","s"],["白醋","数量：1；单位：汤匙","s"],["香叶","数量：3；单位：片","f"],["肉桂皮","数量：2-3；单位：克","f"],["豆蔻","数量：3；单位：个","f"],["花椒","数量：8-12；单位：个","s"],["大料","数量：2-4；单位：个","f"],["淀粉","数量：1；单位：汤匙","s"],["葱","数量：2；单位：棵","f"],["姜","数量：6；单位：克","f"],["蒜","数量：6；单位：粒","f"],["料酒","数量：2；单位：汤匙","s"]],[]]],[["预处理",["猪肘解冻后水泡 1 小时去除血水。","如有火焰喷枪，则使用火焰喷枪灼烧猪肘皮表面至棕黑色以去除猪毛，破坏汗腺。注意不要长时间炙烤同一个位置以避免烧焦，当猪肘皮几乎完全呈现棕黑色时则停止灼烧。","如无火焰喷枪，将铁锅烧至 200 以上，将猪肘直接放入锅内，用锅铲或筷子使猪肘皮充分接触铁锅表面，当猪肘皮与铁锅接触位置呈现出棕色时，更换位置继续烫猪肘皮，直到整个猪肘被充分烫过。注意再次过程中注意铁锅温度，不要使铁锅红热。","使用清洁球在水中刷洗猪肘，将其表面烧焦的部分去除。刷洗结束后，猪肘再次呈现出未被灼烧前的状态。","将猪肘置于铁锅中，加尽量多的冷水，具体视铁锅深度与猪肘大小而定，在保证可以拿得动铁锅及其内容物的情况下，能浸没猪肘 3/4 以上为最佳。"]],["去腥",["取 1 棵葱的葱白，分成 3 段，放入锅中。","取 3 粒蒜，分别用刀身拍扁，放入锅中。","取 3 克姜，放入锅中。","将 2 汤匙料酒加入锅中。","锅中水烧开后，等待五分钟，随后将猪肘取出，捡出锅中所有配料，更换容器保留所有肉汤备用。"]],["油炸",["向锅中加入冷油，以之前水量为参考，能浸没猪肘 3/5 以上为佳，开中火加热。","当油温达到五成时，转为小火，放入猪肘油炸。","在油炸过程中烹饪者应注意人身安全。","在油炸过程中，使用锅铲或其他耐高温厨具将锅中的油均匀淋到猪肘未被浸没的部分，如果条件允许应以 3 分钟的间隔翻转猪肘，使其油炸均匀。","油炸过程持续大约 20 分钟，当观察到猪肘皮已经全部呈现出浅棕色，而瘦肉部分已经微焦，则可捞出备用。","炸制完后的油可用于制作其他油炸类食物，但注意不要使用太多次。"]],["炒糖色",["炒糖色200ml 备用。"]],["炖煮",["将猪肘加入高压锅内，加入所有肉汤、糖色、香叶、肉桂皮、豆蔻、花椒、大料、老抽、生抽、白醋。如果喜欢甜口，可以再额外加入 2-3 克冰糖。","取 1 棵葱的葱白，分成 3 段，放入锅中。","取 3 粒蒜，分别用刀身拍扁，放入锅中。","取 3 克姜，放入锅中。","盖上锅盖，加压炖煮 40 分钟。"]],["收汁",["在炖煮期间调制水淀粉。取碗 1 个，加入 1 汤匙淀粉，100ml 水，搅拌使其成为白色悬浊液","炖煮时间结束后，打开高压锅锅盖，捡出锅中所有的配料，只保留猪肘。","将高压锅中剩余的肉汤转移至铁锅内，猪肘转移至盘子或盆内","将铁锅置于灶台上，开大火。在收汁过程中可以用筷子头蘸取锅内汤汁判断咸淡，并根据口味添加盐。注意，汤汁多的时候味道会比汤汁少的时候味道更淡，加入盐时需要考虑这一点。","当肉汤沸腾时，注意观察剩余肉汤余量","当剩余肉汤少于原肉汤体积的 1/2 时，再次搅拌之前调制好的水淀粉，并加入一半","等待肉汤沸腾，加入剩下的一半","等待肉汤沸腾，沸腾后等待 1-2 分钟关火，此时锅内的肉汤呈红棕色粘稠状","用汤匙舀起肉汤均匀地淋在猪肘上，尽量使猪肘的每一处都淋到汤汁。如果在猪肘被完全淋到前汤汁已经用完则可直接上桌，否则剩余汤汁不需要再淋，可直接上桌。"]]],["参考资料：Bilibili老饭骨的视频教程"]],["745b2964ca","这是一道清爽脆嫩的家常快手菜，咸鲜适口，带有蒜香与微辣。富含蛋白质和多种维生素，有助于清热补水。对新手比较友好，只要注意火候就能成功，预计制作时长约 25 分钟。",[["必备","黄瓜","f",0],["必备","猪瘦肉","f",0],["必备","食用油","s",0],["必备","生抽","s",0],["必备","盐","s",0],["必备","蒜","f",0],["必备","小米辣","f",0]],[["参考用量",[["黄瓜","100 克 份数","f"],["猪肉","50 克 份数","f"],["油量","50 克 份数","f"],["盐量","10 克 份数","f"],["酱油","5 克 份数","s"],["蒜瓣","2 瓣 份数","f"],["小米辣","1 根 份数","f"]],["每次制作前需要确定计划做几份。一份正好够 1 个人食用","总量："]]],[["制作步骤",["将猪瘦肉切片，放入碗中，倒入食用油 10 克，生抽，搅拌均匀，腌制 10 分钟","将黄瓜切去 5 厘米的头尾，剩余部分斜着切成 0.5 厘米的薄片","将黄瓜倒入碗中，撒上盐 8 克，搅拌均匀，腌制 5 分钟","将蒜瓣去皮，压扁，切成蒜末备用","将小米辣去丁切分成均匀 0.5 厘米的段状","热锅，倒油 40 克，等油温到冒烟，放入蒜蓉小米辣翻炒 5 次","放入腌制好的猪瘦肉，翻炒至肉熟变色","放入黄瓜，加入盐 2 克，大火翻炒均匀半分钟，出锅","如果无法保证大火，可能会有点生。可以考虑增加到 50 秒。"]]],[]],["2a7b484d16","黄焖鸡是一道以鸡腿、香菇、青椒为主料的家常菜，汤汁浓郁，鸡肉滑嫩，咸鲜微甜，十分下饭。富含优质蛋白质和菌菇多糖等营养。炒糖色环节稍有挑战，但可用老抽替代，整体难度不高，新手也能顺利掌握。从备菜到出锅，大约需要 40 分钟。",[["必备","鸡腿","f",0],["必备","香菇（干香菇最佳）","f",0],["必备","青椒","f",0],["必备","生姜片","f",0],["必备","干辣椒","f",0],["必备","盐","s",0],["必备","料酒","s",0],["必备","白胡椒粉","s",0],["必备","白糖","s",0],["必备","酱油","s",0],["必备","味精","s",0],["必备","土豆（可选）","f",1]],[["参考用量",[["鸡腿","两只","f"],["香菇（干香菇最佳）","5 朵","f"],["青椒","两个","f"],["生姜片","两片","f"],["干辣椒","5，6 个","f"],["盐","10g","s"],["料酒","10ml","s"],["白胡椒粉","5g","s"],["白糖","5g","s"],["酱油","5ml","s"],["土豆","一个（可选，可使汤汁更粘稠）","f"]],[]]],[["备菜阶段",["鸡腿洗净，剁成4cm大小的块","生姜切片、干辣椒切成小圈","香菇切片，青椒切成细长的马蹄状，若为干香菇，洗净灰尘后泡一晚上并留香菇水备用","若有土豆，切为与鸡肉大小类似的滚刀块"]],["炒制阶段",["炒糖色：锅里倒入底油，冷油时放入白糖（有一定难度，新手可跳至鸡肉炒制并使用老抽替代）","小火慢慢加热，待油温逐渐升高，白糖开始融化并变成较深的棕色（期间要不断搅拌，防止糊锅）","迅速倒入鸡块，转大火，快速翻炒！烹入料酒，继续翻炒片刻","将生姜片和干辣椒倒入","放入酱油，炒匀","倒入香菇水或清水，以能淹住鸡肉为准","倒入香菇片，白胡椒粉，盐，土豆","翻炒均匀后，盖上锅盖焖煮，转中小火15——20分钟，有条件可以转至砂锅","待鸡肉软烂，汤汁浓稠后（汤汁不要收的太干），最后放入青椒","放入味精，兜炒均匀后，关火！青椒基本断生即可，不要炒时间久了"]]],[]],["d807baa0da","这是一道源自印度的经典咖喱菜肴，以烤制后再炖煮的鸡腿肉搭配番茄、黄油和奶油制成的酱汁，口感醇厚丝滑，酸甜微辣，带有独特的香料复合香气。鸡肉、酸奶和腰果提供了丰富的蛋白质与健康脂肪，番茄和香料也带来一定的维生素与抗氧化物。制作有一定挑战，需要掌握火候和香料的平衡，加上腌制时间共约 1 小时 45 分钟方可完成。",[["必备","鸡腿肉（去骨）","f",0],["必备","酸奶","f",0],["必备","黄油","s",0],["必备","淡奶油(Heavy Cream)","s",0],["必备","番茄","f",0],["必备","洋葱","f",0],["必备","生姜","f",0],["必备","大蒜","f",0],["必备","腰果（用于增稠）","f",0],["必备","姜黄粉","f",0],["必备","红辣椒粉（Kashmiri 红辣椒粉最佳，色红味不辣）","s",0],["必备","印度综合香料粉(Garam Masala)","f",0],["必备","香菜粉","f",0],["必备","孜然粉","s",0],["必备","小豆蔻粉","f",0],["必备","干葫芦巴叶(Kasuri Methi)— 可选但强烈推荐","f",1],["必备","糖","s",0],["必备","盐","s",0],["必备","食用油","s",0],["必备","炒锅","t",0],["必备","搅拌机/料理机","t",0]],[["参考用量",[["鸡腿肉","500g（去骨，切大块）","f"],["酸奶","80ml","f"],["生姜","10g，磨碎","f"],["大蒜","4 瓣（约 12g），磨碎","f"],["红辣椒粉","5g","s"],["姜黄粉","3g","f"],["盐","3g","s"],["柠檬汁","15ml","f"],["食用油","15ml","s"],["番茄","5 个（约 500g），切块","f"],["洋葱","1 个（约 100g），切块","f"],["腰果","30g","f"],["生姜","10g","f"],["大蒜","4 瓣","f"],["黄油","50g","s"],["淡奶油","100ml","s"],["红辣椒粉","5g（Kashmiri 红辣椒粉最佳）","s"],["香菜粉","5g","f"],["孜然粉","3g","s"],["印度综合香料粉","3g","f"],["小豆蔻粉","2g","f"],["干葫芦巴叶","3g（用手搓碎）","f"],["糖","10g","s"],["盐","5g","s"],["水","100ml","f"]],["每次制作前需要确定计划做几份。一份正好够 3-4 个人食用。","每份：","腌鸡部分：","酱汁部分："]]],[["腌制鸡肉（提前 1 小时）",["在大碗中混合酸奶、生姜泥、大蒜泥、红辣椒粉、姜黄粉、盐、柠檬汁","放入鸡肉块，充分裹上腌料","盖保鲜膜，冷藏腌制至少 1 小时"]],["烤制鸡肉",["在平底锅中倒入 15ml 食用油，大火加热","将腌好的鸡肉块放入锅中（不要倒入腌料汁）","大火煎至两面焦黄（每面约 3 分钟），鸡肉不需要完全煮熟","盛出备用"]],["制作酱汁底料",["在锅中放入番茄块、洋葱块、腰果、生姜、大蒜和水 100ml","大火煮沸后转中火，煮 15 分钟，直至所有材料完全软烂","稍微冷却后，倒入搅拌机中打成细腻顺滑的泥状","用滤网过滤一遍，去除渣滓，得到顺滑的酱汁，备用"]],["炖煮",["在炒锅中放入黄油 50g，中火加热融化","倒入过滤好的番茄酱汁","加入红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g","翻炒 3-5 分钟，直至酱汁颜色变深且油花浮出","放入烤好的鸡肉块，翻拌均匀","加入糖 10g（平衡番茄的酸味），搅拌","倒入淡奶油 100ml，搅拌均匀","小火炖 10-12 分钟，使鸡肉完全熟透且吸收酱汁","加入印度综合香料粉 3g、小豆蔻粉 2g","撒入干葫芦巴叶 3g（用手搓碎后撒入）","搅拌均匀，关火","盛盘，可额外淋上少量淡奶油作为装饰"]]],["干葫芦巴叶(Kasuri Methi)是这道菜独特风味的关键配料，能赋予一种特殊的草本香气。在印度食品店或电商平台可以购买到。","使用 Kashmiri 红辣椒粉可以使颜色更鲜红但辣度较低。如果买不到，可以用普通红辣椒粉减半并加入 3g 红甜椒粉。","腰果的作用是使酱汁更加浓稠丝滑。如果对坚果过敏，可以用等量的淡奶油替代。","此菜通常搭配印度烤饼(Naan)或巴斯马蒂米饭食用。","黄油鸡被认为是印度对世界美食最大的贡献之一，在全球各地的印度餐厅菜单上几乎都名列前茅。"]],["a0ab3bffe9","徽派红烧肉是一道色泽红亮、肥而不腻的经典徽式家常菜，口感软糯 Q 弹，咸甜交融。以五花肉为主料，富含优质蛋白质和脂肪，能提供充沛能量。烹制需掌握炒糖色与火候，稍有挑战，预估制作时长约 45 分钟。",[["必备","五花肉","f",0],["必备","白砂糖","s",0],["必备","食用油","s",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","老抽","s",0],["必备","姜片","f",0],["必备","蒜头","f",0],["必备","料酒","s",0],["必备","葱","f",0],["必备","五香粉","s",0],["必备","盐","s",0]],[["参考用量",[["五花肉","300 g","f"],["白砂糖","100 g","s"],["食用油","200 g","s"],["生抽","10 ml","s"],["蚝油","5 ml","s"],["老抽","5 ml","s"],["姜片","2 片","f"],["蒜头","3 颗","f"],["料酒","100 ml","s"],["葱","1 根","f"],["五香粉","10 g","s"],["盐","10 g","s"]],["每份："]]],[["制作步骤",["五花肉切块，每块 2-3 cm 大小","锅中加入 150 ml 食用油，倒入五花肉，煎炸 2 分钟 后，加入盐，翻炒五花肉，2 分钟 后出锅","锅中加入 50 ml 食用油，倒入白砂糖，翻炒到咖啡色","倒入五花肉，翻炒 30 S ，加入姜片、蒜头后翻炒 30 S","加入料酒，五香粉、葱，加入水没过五花肉，盖上锅盖煮 10 分钟","加入生抽、老抽、蚝油，中火煮 20 分钟","开锅，大火烧汁，端盘"]]],["葱是整根，不需要切碎","步骤二加盐的目的是锁住五花肉的油脂","制作过程，用部分五花肉做了水煮处理，跟未处理的一起做后续制作，发现未水煮的肉质更 Q 弹"]],["26e6c18ca0","回锅肉是四川传统名菜，以二刀肉或五花肉为主料，成菜色泽红亮，肥肉透明微卷、瘦肉干香不柴，口感肥而不腻，咸鲜微辣，带有蒜苗与豆瓣酱的复合香气。猪肉富含优质蛋白和必需脂肪酸，搭配青红椒、蒜苗可补充维生素。这道菜步骤稍多，包含煮、切、煸炒，对火候和刀工有一定要求，但按流程操作新手也能成功，预计全程耗时约 40 分钟。",[["必备","五花肉","f",0],["必备","小葱","f",0],["必备","生姜","f",0],["必备","青红椒","f",0],["必备","蒜苗","f",0],["必备","料酒","s",0],["必备","豆瓣酱","s",0],["必备","生抽酱油","s",0],["必备","味精","s",0]],[["参考用量",[["五花肉的用量为","0.5 斤/男人 0.3 斤/女人 （正宗回锅肉使用二刀肉[俗称：臀尖]制作，肉质坚实，肥瘦合适）","f"],["小葱","2 棵","f"],["生姜","10-40g","f"],["青红椒（根据受辣程度选择,","0-30g）注：不建议使用肉厚的菜椒","f"],["蒜苗","1 把","f"],["料酒","5ml","s"],["豆瓣酱","10ml","s"],["味精","5g","s"],["生抽","5ml","s"]],[]]],[["五花肉一段处理",["锅烧热，用手将五花肉紧紧压在锅上炙皮","这一步是为了处理猪皮上的汗腺（或者买肉的时候让师傅烧一下皮，喜欢汗腺的可以无视）","用钢丝球把皮刷干净，至黑色部分碳化部分被完全去除，不刷干净会有苦味","将五花肉放入锅中，放入能淹没五花肉的冷水，放入生姜片、料酒和小葱（取 2 棵小葱打结）","开大火煮，水开后撇去浮沫，继续煮 15 分钟，煮至瘦肉部分可以用筷子轻松刺穿"]],["配菜处理",["青红椒切圈","蒜苗切段","生姜切小薄片","将 5ml 豆瓣酱和 5ml 生抽提前混合"]],["五花肉二段处理",["将煮熟的五花肉捞出放入冷水晾凉","擦干五花肉的水，切成上肥下瘦的 2mm 的薄片（切厚了口感不好，而且很油）"]],["开始炒肉",["注意，此步骤操作要迅速，小心糊锅","锅烧热，放入一层底油滑锅","放入五花肉煸炒至肥肉透明，肉片微卷（欲称起灯盏窝），二刀肉效果最佳。","倒入豆瓣生抽混合物，5g 味精翻炒 15 秒","放入青红椒圈和小姜片，放入另 5ml 豆瓣酱翻炒 30 秒","放入蒜苗翻炒 60 秒","出锅"]],["简易版本",["选用冰冻五花肉常量放置 0.5 小时 或者鲜五花肉放冰箱冷藏 1 个小时，切成 2-5 mm 薄片","开中火，辣椒放过锅中干煸 30-45 秒后取出","锅烧热，放入一层底油滑锅，放入姜片煸炒 15 秒","倒入五花肉，间隔 10 S 翻炒一次，待五花肉出现焦黄色（翻炒时间越久五花肉口感越硬）","倒入之前干煸过的辣椒、10ml 豆瓣酱，生抽调味，继续翻炒 60 秒","倒入切成段的蒜苗翻炒 10 秒","出锅"]]],["不喜欢蒜苗可以换成洋葱或者其他蔬菜，但是要注意蔬菜的易熟程度将蔬菜提前炒至，不然会出现蔬菜半生不熟的情况","如果回锅肉比较大块可以切成 5 厘米见方的块，五花肉煮至筷子稍微用力即可插入猪皮即可","回锅肉过冷水晾凉后肉质会更紧致","回锅肉擦干水是为了避免炒至的时候爆油溅伤","回锅肉切记不要切厚了，不然很腻"]],["65a79a5442","一道家常小炒，咸香微辣，牛肉滑嫩入味，尖椒清脆爽口。牛肉提供优质蛋白和铁，尖椒富含维生素 C，搭配起来营养均衡。虽然腌制需要一些耐心，但操作步骤明确，新手也能上手，难度适中。从备料到出锅大约需要 1 小时。",[["必备","牛肉","f",0],["必备","葱、姜、蒜","f",0],["必备","尖椒","f",0],["必备","酱油","s",0],["必备","盐","s",0],["必备","糖","s",0]],[["参考用量",[["牛肉用量为","250 g/人","f"],["葱的用量为","0.5 根/人","f"],["姜的用量为","1 个/人","f"],["盐的用量为","3 g/人","f"],["糖的用量为","1.5 g/人","f"],["酱油的用量为","9 ml/人","f"]],["使用上述条件，计算出计划使用的原材料比例。"]]],[["配菜处理",["蒜剁成蒜泥","葱切段","姜切成姜片","尖椒切成段"]],["牛肉的预处理",["牛肉放入碗中","加姜、盐、酱油、糖进行腌制 30-40 分钟","腌制完姜可以去掉"]],["炒熟",["冷油下锅，待油变热至偶有气泡","加入蒜泥","蒜泥变金黄后加入尖椒","待尖椒表皮微皱，加入腌制好的牛肉翻炒","翻炒变熟之前加入葱，继续翻炒","翻炒至牛肉变熟，关火出锅"]]],["腌制可以加入小苏打使牛肉变嫩，牛肉苏打比例为 500g：3g。","腌制的时候姜片可用料酒代替，料酒的用量为 3 g/人"]],["3083b0cc25","这道菜鲜辣开胃，蛙肉滑嫩弹牙，是一道典型的川味家常菜。牛蛙本身高蛋白、低脂肪，搭配泡姜泡椒等发酵食材，有助于促进食欲。做法相对直接，但油温控制和调味比例需要稍加留意，一般初学者也能在 1 到 2 小时内完成。",[["必备","牛蛙肉","f",0],["必备","泡姜","f",0],["必备","泡椒","f",0],["必备","野山椒（也可以用干红辣椒替代）","f",0],["必备","青红辣椒","f",0],["必备","大蒜","f",0],["必备","豆瓣酱（推荐郫县豆瓣）","s",0],["必备","盐巴","f",0],["必备","胡椒粉","s",0],["必备","生粉（干淀粉也可）","f",0],["必备","啤酒（推荐雪花）","f",0],["必备","料酒","s",0],["必备","藤椒油（可选）","s",1],["必备","猪油（可选）","s",1],["必备","葱花","f",0]],[["参考用量",[["牛蛙肉块","800g （买 3 斤活蛙，建议挑小个头的，肉质鲜嫩）","f"],["泡姜","20-30 克 （看个人口味，喜欢重口一点可以多放）","f"],["泡椒","5-10 克 （看个人吃辣的承受能力，不能吃辣的建议减半为 2.5 克，微微辣）","f"],["野山椒","10 克","f"],["青红辣椒","20 克","f"],["大蒜","30-50 克 （可以根据口味偏好调整，最好不低于 30 克）","f"],["豆瓣酱","20-30 克 （重口选 30，想吃清淡点 20 克。PS 这菜不可能太清淡，哈哈）","s"],["盐巴","15 克","f"],["胡椒粉","10 克","s"],["啤酒","400-500ml","f"],["料酒","10ml","s"],["藤椒油","5-10ml","s"],["生粉","30 克 （干淀粉可以平替）","f"],["猪油","20ml（没有猪油也可，用食用油替代）","s"],["食用油","200ml","s"],["葱花","5 克","f"]],["1 份","每份："]]],[["制作步骤",["牛蛙肉洗净后控干水分，加入 10 克以上的盐巴和 50ml 以上的啤酒，用手抓 5 分钟，去除牛蛙肉的腥味","然后对着清水冲洗，直至不再流出血水和杂质，控干水分，放到合适的器皿中，准备腌制","加入 5 克盐，30 克生粉，10ml 料酒，5 克胡椒粉，用手抓均匀，腌制 5-10 分钟","将泡姜 泡椒 野山椒 切丝或者片（根据自己刀工选择），青红辣椒切成圈圈 大蒜拨开即可","起锅烧热，加入 200ml 食用油（锅底比较平的可以再加 100ml）,烧至 6 成油温（有小气泡出现），将腌制好的牛蛙倒入，快速过油炸制，10 秒钟后捞出（不能超时太多，否则会导致蛙肉老柴）","捞出蛙肉后，控油，并将锅中的热油倒出到碗中，保留 30ml,加入 20ml 猪油（如果没有，则在锅中保留总共 50ml 食用油）","待油温 6 成热，加入泡姜、泡椒、野山椒、大蒜，超出香味，加入豆瓣酱 20 克，中火翻炒至出红油（时间控制在 30 秒），倒入 400ml 啤酒，","然后倒入炸过的牛蛙肉，用勺子推着翻，不要用力搅拌，加入 5 克胡椒粉，加入 5ml 藤椒油，中火慢焖 3 分钟","加大火力，大火收汁半分钟，加入青红辣椒圈，再煮 10 秒准备起锅","盛到盆里，撒上葱花，可以开动了！"]]],["控干水分的时候可以选择漏勺按压","生粉抓揉的时候要均匀覆盖蛙肉"]],["3975867498","一道外酥里嫩、香气浓郁的料理，先以香料炖煮再煎出金黄脆壳，风味浓郁不腻，是家常宴客两相宜的硬菜。羊肉富含优质蛋白和铁、锌等矿物质，有助于温补气血。做法步骤稍多，但只要按流程走，新手也能拿下；使用高压锅全程约 1 小时，普通锅约 1.5 小时。",[["必备","羊排","f",0],["必备","桂皮","f",0],["必备","花椒","s",0],["必备","八角","f",0],["必备","白芷","f",0],["必备","香叶","f",0],["必备","盐","s",0],["必备","料酒","s",0],["必备","辣椒粉","s",0],["必备","孜然粒","f",0],["必备","烧烤撒料","f",0],["必备","孜然粉","s",0],["必备","白芝麻","f",0],["必备","糖","s",0],["必备","高压锅","t",0],["必备","炒锅 / 煎锅","t",0]],[["参考用量",[["羊排","750g（建议选择带一些肥肉的）","f"],["桂皮","2g","f"],["花椒","5g","s"],["八角","1 颗","f"],["白芷","6g","f"],["香叶","5 片","f"],["盐","25g（注：若计划喝煮羊排的汤，则此处的盐在炖煮步骤中省略，在最后的煎烤步骤中加入）","s"],["料酒","10ml","s"],["辣椒粉","5g","s"],["孜然粒","2g","f"],["烧烤撒料","2g","f"],["孜然粉","2g","s"],["白芝麻","2g","f"],["糖","1g","s"]],["每次制作前需要确定计划做几份。一份正好够 3 - 4 个人吃。","每份："]]],[["制作步骤",["将羊排按照骨头分布，切成块状。","炒锅中加入冷水，放入全部羊排块，水沸腾后继续焯水 2 - 3 分钟，捞出备用。","将焯好水的羊排、桂皮、花椒、八角、白芷、香叶、料酒放入锅中（高压锅或普通锅）。","加入饮用水没过所有食材。如果使用高压锅，上汽后压 30 分钟。如果使用普通锅，炖煮 80 分钟。","将炖煮完成的羊排捞出，沥干水分，放入无油无水的炒锅 / 煎锅中。","中大火煎 6 - 7 分钟，直至羊排中的油脂被煎出，表面呈金黄酥脆状态。","锅中保留煎出的羊油，加入辣椒粉、孜然粒、烧烤撒料、孜然粉、白芝麻，翻炒均匀。","加入糖和盐（如果在炖煮步骤中未添加），翻炒均匀。","翻炒均匀后即可关火，盛盘。"]]],["花椒和白芷是这道菜的关键调料，不可缺少。","炖煮时间不宜过长，羊排过于软烂则在煎制时容易碎裂。","煎制时利用羊排自身煎出的油脂来炒香调料，风味更佳。","焯水、炖煮、煎制过程中会产生较多羊油，处理时请注意不要直接倒入下水道，以防堵塞。"]],["477090e25d","这道家常美味色泽红润油亮，口感软糯，肥而不腻，酱香浓郁，搭配米饭特别过瘾。五花肉提供优质蛋白质和必需脂肪酸，加上鹌鹑蛋或豆皮，营养更全面。做法对新手相当友好，从备料到出锅大约需要 1.5 小时。",[["必备","注：如果有可能，请尽量把刀磨的锋利一些。","f",0],["必备","主料：大肉、鸡蛋（可选）、豆皮（可选）","f",1],["必备","辅料：生姜、冰糖、生抽、老抽、料酒、香叶、八角、盐、水、葱（记得要开水）","f",0]],[["参考用量",[["猪五花肉：约","34 斤","f"],["姜：","6 片","f"],["冰糖：15 克（约","7 块）","f"],["生抽：10ml","","f"],["老抽：15ml","","f"],["料酒：5ml","","f"],["开水：没过食材的量，需要","600ml-900ml","f"],["香叶：3 片","","f"],["八角：2 个","","f"],["鹌鹑蛋（可选，没有鹌鹑蛋，可以用同等重量的鸡蛋代替）：0-2 个","","f"],["豆皮（可选）：0-80g","","f"],["盐：2-3g","","f"]],["每次制作前需要确定计划做几份。一份正好够 2-3 个人吃。","如果只有 1 人食用，可以考虑食材减半。"]]],[["原材料准备",["猪五花肉切大块（约 4.5cm ，冷冻半小时至一小时更好切）","豆皮切 2cm 的宽度","生姜切片（每片厚度约 3mm ）","水烧开","鹌鹑蛋煮熟并用叉子/牙签扎孔（尽量多些好入味）","大葱大葱白色的部分葱白"]],["开始制作",["冷水锅中放入切好的猪五花肉，加入料酒与葱姜，煮 15 分钟去掉血腥","锅中放入两片生姜提味","开中小火后直接加入五花肉，不需要放入食用油，每块五花肉六个面都煎一下，煎至出油即可","将煎出的油倒出备用，并将五花肉推至一边，加入 15g 冰糖，翻炒至冰糖融化；","融化后将五花肉与冰糖炒至融合上色，加入","生抽 10ml","老抽 15ml","料酒 5ml","翻炒至上色；","加入烧好的开水炖煮 40 分钟（刀工差的同学切的过大请自觉延长炖煮时间），并放入","生姜 2 片","香叶 3 片","八角 2 个","盖上锅盖煮至沸腾后，加入煮好扎好孔的鹌鹑蛋和豆皮，开中小火，等待 40 分钟。（中途可适当翻搅防止粘锅）；","打开锅盖，待汤汁快没有的时候开大火收汁（切记不可收干）；","加入 2-3g 盐，翻炒一下，就可以出锅了。"]]],[]],["06c15f4b28","姜炒鸡是湖南风味的下饭菜肴，鸡肉干香入味，姜香浓郁，辣而不燥。鸡肉富含优质蛋白，生姜有助于驱寒暖胃、促进食欲。做法简单，新手也能轻松掌握。从腌制到出锅大约需要 1 小时。",[["必备","鸡","f",0],["必备","生姜","f",0],["必备","啤酒","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","盐","s",0],["必备","小米椒","f",0],["必备","美人辣","f",0],["必备","泡椒","f",0],["必备","大蒜","f",0]],[["参考用量",[["鸡","半只（土鸡最好，预计 650g）","f"],["食用油","50ml（茶油最好，没有就用菜籽油）","s"],["生姜","半斤 (250g)","f"],["啤酒","半瓶 250ml","f"],["生抽","20ml","s"],["老抽","10ml","s"],["盐","3g","s"],["小米椒","0-5 个 (0-50g)（根据辣口味调整）","f"],["美人辣","0-5 个 (0-50g)（没有可以用小米椒代替）","f"],["泡椒","5 个 (50g)","f"],["大蒜","3 头 (50g)","f"]],[]]],[["制作步骤",["鸡尽量剁成 1cm 的小块，洗净后滤干，再放生抽腌和料酒腌制 30 分钟","大先热锅到微微冒烟，放入食用油，等 5 秒","下入姜片后转中火炒 30 秒，","下入鸡块翻炒 3 分钟，炒干水分，炒出鸡油","放入各种剁碎的辣椒和大蒜子，加盐和老抽继续翻炒 30 秒","倒入啤酒，中小火焖 2 分钟","大火收汁盛盘"]]],[]],["24c850c790","姜葱捞鸡是一道粤式经典家常菜，鸡肉嫩滑多汁，葱姜香气浓郁，咸鲜适口，十分下饭。鸡腿肉提供优质蛋白质，搭配姜葱能温中散寒、促进食欲。整体操作以蒸制和手撕为主，步骤清晰，对新手来说比较容易上手。从备料到完成大约需要 40 分钟。",[["必备","鸡腿肉","f",0],["必备","盐焗鸡粉","f",0],["必备","葱，姜","f",0]],[["参考用量",[["鸡腿","4 个， 约 400g","f"],["盐焗鸡粉","5g","f"],["姜","50g","f"],["葱","1 根","f"],["盐","5g","s"],["糖","5g","s"],["油","35ml","s"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["四个鸡腿清洗干净，放入碗中","碗中加入盐焗鸡粉和 5ml 油，搅拌均匀","让鸡腿静置腌制 15 分钟， 同时准备蒸锅并把水煮开","鸡腿腌制完成后， 放入水开后的蒸锅中，蒸制 20 分钟","将姜根据个人口味切成 1）姜蓉或 2）姜丝或 3）姜粒","将葱切成 0.5cm 小段","将葱姜放入蘸料碗，并加入盐和糖","将剩余的油倒入另一个锅中加热至六至七层热","将热油淋入葱姜碗中","鸡腿蒸好后将其撕碎成鸡丝，不需要特别细，大概 1cm 粗就可以","姜葱姜油淋在鸡丝上，搅拌均匀即可"]]],["参考: 白饭杀手来啦 #姜葱捞鸡-哔哩哔哩"]],["b262dbe753","酱牛肉是一道北派家常冷荤，酱香浓郁，口感紧实不散，嚼劲十足。牛腱子肉富含优质蛋白和多种氨基酸，慢炖后更易消化吸收。制作过程不算复杂，但包含腌制、慢炖和长时间冷藏，对新手来说需要些耐心，从头到尾大约需要 10 小时。",[["必备","牛腱子肉","f",0],["必备","香叶","f",0],["必备","姜","f",0],["必备","葱","f",0],["必备","老抽","s",0],["必备","桂皮","f",0],["必备","冰糖","s",0],["必备","花椒","s",0],["必备","料酒","s",0],["必备","生抽","s",0],["必备","盐","s",0],["必备","八角","f",0],["必备","黄豆酱","s",0]],[["参考用量",[["牛腱子肉","2000 克","f"],["香叶","1 片","f"],["姜","3 片","f"],["葱半根","","f"],["老抽","15ml","s"],["桂皮","1 块","f"],["冰糖","7-8 粒","s"],["花椒","15 粒","s"],["料酒","30ml","s"],["生抽","15ml","s"],["盐","8 克","s"],["八角","4 个","f"],["黄豆酱","15ml","s"]],["每份："]]],[["制作步骤",["牛腱子肉清洗干净，用清水浸泡 1 小时，去除血水","用牙签或者叉子在牛腱子肉表面扎孔，加料酒、花椒、姜片后，用保鲜膜紧密包裹容器，腌制 4-6 小时","牛腱子肉切成 8cm，不超过 10cm 的肉块","牛腱子肉放入锅中，加入冷水至水面没过牛肉，开锅至水沸腾开始计时，同时捞出浮沫。3 分钟后停火，捞出牛肉，用温水洗净","将洗净后的牛腱子肉放入砂锅或炖锅，加水没过牛腱子肉，开大火，放入除盐之外其他未使用的配料","水开之后，大火转为小火，持续加热 90 分钟，加盐","加盐后，继续小火 90 分钟（注：每 30 分钟确认水位线，要求至少达到牛肉面高度的 80%）","加热 180 分钟后，捞出牛腱子肉，捞出牛腱子肉，用保鲜膜紧密包裹，放入冰箱冷藏数小时","取出后沿牛肉纹路切片，上桌食用，其他牛腱子肉建议不切片冷藏"]]],["操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水至没过食材（约每 30 分钟确认一次）。","用保鲜膜紧密包裹牛肉，放入冰箱冷藏数小时，可以使得切片肉质紧实不散。","用牙签或者叉子在牛肉表面扎孔可以破坏筋膜，便于入味。","参考资料","下厨房app中的食谱"]],["b6cc2c4b47","酱排骨色泽酱红，肉质酥烂，骨香浓郁，汁浓味鲜，咸中带甜，是一道经典的家常菜。排骨富含优质蛋白质和钙质，营养均衡。制作涉及炒糖色和较长时间炖煮，对新手有一定挑战，但只要按步骤操作，也能顺利掌握。预计从备料到出锅约需 1 小时。",[["必备","排骨","f",0],["必备","五香粉","s",0],["必备","料酒","s",0],["必备","食用油","s",0],["必备","白砂糖","s",0],["必备","老抽","s",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","小米椒","f",0],["必备","蒜","f",0],["必备","姜","f",0]],[["参考用量",[["排骨","300 g","f"],["五香粉","20 g","s"],["料酒","10 ml","s"],["食用油","30 ml","s"],["白砂糖","15 g","s"],["老抽","10 ml","s"],["生抽","10 ml","s"],["蚝油","5 ml","s"],["小米椒","1 个","f"],["蒜","2 粒","f"],["姜","2 片","f"]],["每份："]]],[["制作步骤",["起锅烧热水，放入排骨、姜片、料酒，煮开后用勺子舀去白色油沫，2-3 分钟后出锅","冷水清洗排骨，清洗 2-3 遍","小火起锅，加入食用油，加入白砂糖 ，轻轻搅拌到糖水变成黄色","倒入排骨翻炒 30 S 后，加入生抽、蚝油、五香粉、蒜、小米椒后翻炒 30 S 后，加入清水没过排骨","大火煮 30 分钟，加入老抽上色，再煮 10 分钟","起锅摆盘"]]],["增加味道的可以考虑加入豆瓣酱、番茄酱等","大火煮时间可以根据每个人情况做调整","煮排骨期间，可以顺道放入 2-3 个 鸡蛋一起煮，做成简易版卤蛋"]],["2a1e79427b","茭白炒肉是一道家常快手菜，口感鲜嫩爽脆，咸鲜适口，属于典型的江南家常风味。茭白富含膳食纤维和多种维生素，搭配瘦肉提供优质蛋白，荤素搭配均衡营养。烹饪难度中等，新手稍加练习即可掌握，预计制作时长约 20 分钟。",[["必备","茭白","f",0],["必备","瘦肉","f",0],["必备","淀粉","s",0],["必备","食用油","s",0],["必备","鸡精","s",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","料酒","s",0],["必备","盐","s",0]],[["参考用量",[["茭白","2 根","f"],["瘦肉","100 g","f"],["淀粉","15 g","s"],["食用油","30 ml","s"],["鸡精","5 g","s"],["姜","1 片","f"],["蒜","1 个","f"],["料酒","5 ml","s"],["盐","2 g","s"]],["每份："]]],[["准备",["茭白切片，每片厚度 0.5 cm","瘦肉切条，厚度 0.3-0.5 cm，加入料酒、生粉、盐、水搅拌","姜切片、蒜头剁碎"]],["制作",["起锅水烧开，放入茭白，水煮 60-90 S 后取出沥干","起锅，倒入 15 ml 油，倒入瘦肉，反复翻炒 60 S 取出","起锅，倒入 15 ml 油，倒入姜、蒜翻炒 30S，加入茭白继续翻炒 30 S","继续加入瘦肉翻炒 60 S，加入 20 ml 水，加入盐、鸡精后翻炒 60S 出锅"]]],["最后一个步骤，可以考虑加蚝油、生抽代替盐上色"]],["f8adddc284","椒盐排条是上海本帮菜里的经典家常菜，外酥里嫩，咸香适口。猪大排提供优质蛋白质和必需氨基酸，能补充体力。这道菜虽然步骤稍多，但跟着流程走并不难，新手也可以大胆尝试。从备料到出锅，大约需要 40 分钟。",[["必备","大排","f",0],["必备","鸡蛋","f",0],["必备","盐","s",0],["必备","椒盐粉","f",0],["必备","葱姜水","f",0],["必备","面粉","f",0],["必备","淀粉","s",0],["必备","吉士粉（增色增香，没有可以不放）","f",0],["必备","水","f",0],["必备","油","s",0]],[["参考用量",[["大排","4 块（大约 360 克）","f"],["鸡蛋","1 个 50 g","f"],["盐","1 g","s"],["椒盐粉","10 g","f"],["葱姜水","100 ml","f"],["面粉","80 g","f"],["淀粉","80 g","s"],["吉士粉","2-3 g（增色增香，没有可以不放）","f"],["水","10 g","f"],["油","10 g","s"]],["每次制作前需要确定计划做几份。一份够 1 - 2 个人吃。"]]],[["制作步骤",["大排洗干净，剔骨，用刀面拍松，切成厚片，再改成粗条。","加入椒盐粉，搅匀，待到出胶质了分次加入葱姜水，放入冰箱腌制 20 分钟。","制作炸糊。放入 80 g 面粉，20 g 淀粉（注意是 20 g 淀粉，剩下 60 g 备用），2 - 3 g 吉士粉，盐 1 g。","打入一个鸡蛋，搅拌，再分次加入水 100 g ，再加 10 g 油，反复搅拌。直到炸糊完全调开，略粘稠即可。","取出剩余的 60 g 淀粉，取出排条，裹上一层淀粉，再裹上面糊。","锅中加入油，能没过食材即可，加热到大约 150 ℃ - 160 ℃ 。下入排条炸成浅金黄色后捞出。刚下入排条时可能会有粘连，不要动。待排条定型后可用筷子翻动，即可分开。","待油温再次升高到 150 ℃ - 160 ℃ 时，下入排条复炸至金黄色后捞出。","撒上椒盐粉，搅拌均匀后出锅。"]]],["也可以用面包糠代替炸糊，但口感差距很大。","炸糊也可以用来炸鸡腿、炸鱼等。","参考：椒盐排条的做法"]],["32a1566cc6","这道菜鲜香微辣，芥末风味浓郁，虾肉紧实弹嫩，是一道快手家常海鲜菜。虾本身富含优质蛋白和钙，脂肪含量低，搭配芥末开胃解腻。中等难度，只要按步骤调制碗汁、控制火候，新手也能较快上手，全程约需 30 分钟。",[["必备","罗氏虾","f",0],["必备","蒜","f",0],["必备","青芥末","f",0],["必备","生抽","s",0],["必备","生粉","f",0],["必备","胡椒粉","s",0],["必备","白糖","s",0],["必备","蚝油","s",0],["必备","盐","s",0],["必备","小米辣（不吃辣可不放或替换成红菜椒）","f",0],["必备","黄油","s",0],["必备","食用油","s",0]],[["参考用量",[["罗氏虾","250g","f"],["蒜","1-2 个","f"],["青芥末","20g，用于碗汁","f"],["生粉","10g，用于碗汁","f"],["生抽","30g，用于碗汁","s"],["胡椒粉","5g，用于碗汁","s"],["白糖","3g，用于碗汁","s"],["蚝油","15g，用于碗汁","s"],["盐","3g，用于碗汁","s"],["小米辣","1-2 个","f"],["黄油","20g","s"],["食用油","80ml","s"]],["每份（约 2 人份）："]]],[["制作步骤",["处理虾：","将虾从背部切开，去除虾线和沙袋，也可从腹部切开，炸出来会胀开，成菜比较漂亮","用清水洗干净，控干水分后可拍上生粉，也可不拍","蒜蓉及碗汁处理：","将 2 颗大蒜切成蒜末","准备碗汁，放入生抽、蚝油、白糖、胡椒粉、盐，依据个人口味挤入芥末，加清水稀释后加入生粉化开","炒制过程：","锅热倒入食用油，大概能覆盖锅底","放入控干水分的罗氏虾，慢慢煎制","虾油煎出来后（表现为锅中出现大量气泡），加入准备好的蒜蓉及小米辣","闻到蒜蓉的香味后，加入黄油","黄油融化后翻拌均匀，加入准备好的碗汁","盖锅盖焖煮 2 分钟汤汁浓稠后出锅"]]],["注意事项：","黄油入锅后不宜炸制太久，融化翻拌均匀即可烹入碗汁"]],["676bf4172d","咖喱肥牛是一道浓郁下饭的家常菜，咖喱的辛香与肥牛的脂香融合，搭配土豆、胡萝卜等蔬菜，口感绵软醇厚。富含蛋白质、维生素和钙质，荤素搭配均衡。做法简单，对新手友好，一般只需 40 分钟就能端上餐桌，很适合作为便当菜。",[["必备","香叶","f",0],["必备","纯牛奶（推荐卫岗鲜奶）","f",0],["必备","洋葱","f",0],["必备","胡萝卜","f",0],["必备","土豆","f",0],["必备","肥牛卷","f",0],["必备","咖喱块","f",0]],[["参考用量",[["香叶","1 片","f"],["纯牛奶","50ml","f"],["洋葱","100g","f"],["胡萝卜","150g","f"],["土豆","200g （挺饱腹的，酌情添加）","f"],["肥牛卷","300g （喜欢吃肉就多来点）","f"],["咖喱块","2 块 （大约 100g）","f"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["洋葱切成条状、胡萝卜以及土豆切成块状，备用","烧一锅开水，水沸时将肥牛卷下锅，捞出血沫后放在一边沥水，备用","热锅，锅内放入 10ml - 15ml 食用油，等待 10 秒让油温升高","放入洋葱，翻炒至洋葱变软变透明","放入土豆以及胡萝卜翻炒 2 分钟","加入冷水至淹没所有食材即可","将香叶、咖喱块投入锅中，盖上锅盖，待水沸腾后将火调小然后等待直至土豆块以及胡萝卜块炖至软烂（可用筷子确认）","加入肥牛卷以及牛奶，盖上锅盖再小火煮 2-3 分钟即可出锅（用勺子搅拌食材，注意力度，避免肥牛卷破碎）"]]],["咖喱块不用捣碎，直接整块投入即可。","操作时，需要注意搅拌食材，避免食材调味料不均匀。"]],["4ac39e69ec","腌制入味的鸡中翅经高温烘烤，外皮微焦、内里鲜嫩多汁，带有黑胡椒和酱油的咸香。富含优质蛋白质和胶原蛋白。难度适中，新手也能轻松上手，从准备到出炉大约需要 1 小时。还可按喜好添加蜂蜜或五香粉增添风味。",[["必备","鸡翅中","f",0],["必备","盐","s",0],["必备","黑胡椒粉","s",0],["必备","酱油","s",0],["必备","料酒","s",0],["必备","烤箱","t",0]],[["参考用量",[["鸡翅用量为","3-4 个/人","f"],["盐的用量为","2 g/人","f"],["黑胡椒粉的用量为","1 g/人","f"],["酱油的用量为","3 ml/人","f"],["料酒的用量为","3 ml/人","f"]],["使用上述条件，计算出计划使用的原材料比例。"]]],[["鸡翅的预处理",["鸡翅放入碗中","加盐、黑胡椒粉、酱油、料酒进行腌制 30-40 分钟"]],["烤制过程",["将烤箱预热至 200℃","将腌制好的鸡翅均匀地放在烤盘上","将烤盘放入烤箱中层，烤 15-20 分钟","取出烤盘，将鸡翅翻面，再烤 15-20 分钟，直到熟透"]]],["可以在腌制鸡翅时加入蜂蜜、酱油、姜蒜粉、五香粉等作为调味料，提升口感和香气","烤鸡翅时，建议将烤盘底部垫上一层锡纸，便于清洁烤盘"]],["51b75ae999","可乐鸡翅色泽红亮、口感嫩滑，味道咸甜适口，是一道流行于家庭餐桌的创意菜肴。鸡翅富含优质蛋白质与脂肪，搭配可乐烹煮后肉质更为软烂。制作过程需要掌握煎制与收汁的火候，对新手有一定挑战，但跟随步骤仍可成功。从备料到完成大约耗时 40 分钟。",[["必备","鸡翅中","f",0],["必备","可乐","f",0],["必备","白糖","s",0],["必备","生抽","s",0],["必备","盐","s",0],["必备","生姜","f",0],["必备","料酒或啤酒","f",0],["必备","小葱","f",0]],[["参考用量",[["鸡翅","10 ～ 12 只","f"],["可乐","500ml","f"],["白糖","10 克","s"],["生抽","15 克","s"],["老抽","3 克","s"],["盐","2 克","s"],["生姜","2 片","f"],["料酒","20 毫升","s"],["小葱挽成结","","f"]],["按照 1 盘的份量："]]],[["制作步骤",["鸡翅入锅，倒入冷水淹没。放生姜 1 片和料酒 10 ～ 20 毫升。大火煮开（ 大约 2 分钟 ）后，撇去浮沫，沥出水分","这一步针对冰鲜鸡翅，刚买来的鸡翅直接改刀用生抽进行腌制即可。","捞出鸡翅，可用刀将两边各划上两口改刀。生抽约 10 克腌制鸡翅 10 分钟（生抽能完全包裹鸡翅表面入味就行）","锅重新小火起油，先将剩余姜片爆香，然后下入腌好的鸡翅。将鸡翅煎至金黄翻面（直到两面金黄），用炒菜勺子翻动一下鸡翅，与姜片一起翻炒 4～5 下（目的是防止鸡翅和姜片粘黏）。","鸡翅金黄，倒入可乐没过鸡翅，开大火将锅中可乐煮沸，然后撇去漂浮的黑色浮沫（包含血水）。此时加入葱结。","调味：加入食用盐 2 克，白糖 10 克，生抽 3 克调味（可以适当用老抽调底色，3 克）。","等到葱结变黄，和姜片一起捞出，转中火继续慢煮可乐鸡翅。","等到可乐呈现挂丝状态，关小火让汁牢牢挂在鸡翅上。出锅，装盘。"]]],["加入生姜爆香的同时能防止鸡翅粘锅。","最后收汁时勿开过大火，防止味道偏苦。","本菜品偏甜。"]],["f9172e9b6d","空气炸锅炸鸡是一道先腌后炸的家常肉菜，外壳酥脆、内里多汁，调味可以按口味灵活切换。鸡翅富含优质蛋白和脂肪，适合作为正餐主菜或加餐。实操约 55-70 分钟（含一次裹粉；若选二次裹粉时约 70-90 分钟），如追求最佳效果，可冷藏腌制过夜（提前一天准备，第二天再炸）。",[["必备","新鲜鸡翅中","f",0],["必备","生抽","s",0],["必备","蒜粉","f",0],["必备","paprika（红甜椒粉）","f",0],["必备","洋葱粉","f",0],["必备","黑胡椒粉","s",0],["必备","中筋面粉","f",0],["必备","淀粉（玉米淀粉或土豆淀粉均可）","s",0],["必备","食用油（用于喷涂或刷涂）","s",0],["必备","空气炸锅","t",0],["必备","酸奶或牛奶（可选，帮助肉质更滑嫩）","f",1],["必备","鸡蛋（可选，帮助形成更饱满的外壳）","f",1],["必备","泡打粉（可选，帮助形成更酥脆的外壳）","s",1]],[["参考用量",[["鸡翅中","6 个（约 300g）","f"],["生抽","15ml","s"],["酸奶或牛奶","5ml（可选）","f"],["鸡蛋","1 个（可选，用于裹浆）","f"],["蒜粉","13g","f"],["paprika","10g（红甜椒粉）","f"],["洋葱粉","5g","f"],["黑胡椒粉","5g","s"],["中筋面粉","60g","f"],["淀粉","30g","s"],["泡打粉","1g","s"],["食用油","5ml","s"]],["每次制作前需要确定计划做几份。本菜谱按 1 份（6 个鸡翅中，约 300g）编写，适合大多数空气炸锅一层平铺。","1 份："]]],[["腌制鸡翅（提前一晚）",["鸡翅中清洗后擦干水分，每个鸡翅两面各划 2 刀，方便入味。","调制腌料：生抽 15ml、蒜粉 8g、红甜椒粉 5g、洋葱粉 3g、黑胡椒粉 3g，牛奶或希腊酸奶 5ml（可选，让鸡肉更滑嫩）搅拌均匀。","将腌料和鸡翅中一起放到大 zip 保鲜袋里充分搅拌按摩，在冰箱里静置一晚。"]],["裹粉准备",["裹粉：中筋面粉 60g、淀粉 30g、蒜粉 5g、红甜椒粉 5g、洋葱粉 2g、黑胡椒粉 2g、泡打粉 1g（可选，让外壳更酥脆）搅拌均匀。","裹浆（可选）：鸡蛋 1 个，牛奶或水 5ml，充分打散。"]],["裹粉",["裹粉：将鸡翅中抖干水分，放入裹粉中轻轻按压，抖落多余的粉，一旁静置 10 分钟。","裹浆（可选）：如想要更饱满的外壳，可以再裹一层浆，然后重复裹粉步骤。","将裹粉静置后的鸡翅放入裹浆，然后轻轻抖落多余的浆。","再次放入裹粉，轻轻按压，抖落多余的粉。","一旁静置 20 分钟（如有条件可以更久一点，外壳更牢固不易脱落）。"]],["炸制",["空气炸锅预热到 180°C，预热 5 分钟。","炸篮内刷薄油，鸡皮面朝下，鸡翅上喷或者刷薄油。","设定空气炸锅 180°C，先炸 10 分钟。","打开炸篮翻面，在鸡翅表面补喷或者刷薄油，再以 180°C 炸 6 分钟。","观察鸡皮颜色，并用牙签扎一下最厚的部分，看是否有血水流出。","如需要再以 200°C 炸 1-2 分钟补脆上色（可迭代进行，先炸 1 分钟观察再决定是否继续）。"]]],["本菜谱也可以用来炸带骨鸡腿，只需相应调整配料的用量和炸制的时间。","蒜粉、红甜椒粉和洋葱粉可以根据个人口味调整用量。","想做辣味：在裹粉中加入辣椒粉 3g，或在出锅后撒辣椒面 2g。","想做孜然味：在出锅后撒孜然粉 2g 和白芝麻 2g。","不建议鸡翅叠放，会导致接触面受热不足，外壳不够脆。"]],["c2319ceda2","口水鸡是一道经典的四川凉菜，红油包裹的鸡肉冰爽 Q 弹、麻辣鲜香，夏季食用开胃解腻。鸡肉富含优质蛋白，搭配花生碎和香料，提供能量与风味。制作难度中等，需注意煮鸡火候和红油调味，适合有一定下厨经验的烹饪者。从备料、煮鸡、冷却到淋汁完成，预计耗时约 1.5 小时。",[["必备","半只鸡","f",0],["必备","辣椒粉","s",0],["必备","花椒","s",0],["必备","花生","f",0],["必备","葱姜蒜","f",0],["必备","花椒","s",0],["必备","白糖","s",0],["必备","生抽","s",0],["必备","醋","s",0],["必备","味精","s",0]],[["参考用量",[["食用油","20ml","s"],["鸡","半只(500g)","f"],["辣椒粉","20g","s"],["花椒","30 颗(20g)","s"],["花生","10 颗(30g)","f"],["小葱","2 颗(50g)","f"],["姜","1 小块(20g)","f"],["蒜","2 个 (10g)","f"],["白糖","5g","s"],["生抽","5ml","s"],["醋","5ml","s"],["味精","5g","s"],["花椒粉","5g","s"],["香菜","5g","f"]],["每份："]]],[["制作步骤",["姜切片，1 颗小葱，15 颗花椒备用","鸡肉洗干净，放入锅中，清水没过鸡肉，放入姜片、小葱和花椒，开大火烧开。","大火烧开后，转中小火 20 分钟关火","取出鸡肉，放入冰水中，直至冰凉","取出鸡肉，切块摆盘子中，备用","小火把锅烧热，导入花生，烘烤至表皮爆裂。（注意随时翻动，不要糊了）","一颗葱切成段，蒜拍成末，花椒 15 颗，花生去皮切碎。","锅内导入油烧热后，放入葱段，花椒和一半蒜末，炒香","炒至油温 8 成热，关火，滤出热油","将热油倒入放辣椒粉的碗中，搅拌，并滤出红油","红油中放入剩余蒜末、生抽、醋、盐、味精、糖、香油、花椒粉。拌匀放凉","在鸡肉上撒上花生碎，把红油淋到切好的鸡肉上，撒上香菜。成盘"]]],["口水鸡第二种做法待更"]],["9a225a27f6","辣椒炒肉是一道湘味浓郁的家常菜，辣椒干香微焦，肉片滑嫩入味，咸鲜微辣十分下饭。猪肉富含优质蛋白质和 B 族维生素，青椒则提供丰富的维生素 C。这道菜需要掌握干煸和快炒的火候，适合有一定烹饪基础的朋友尝试。从备料到出锅，大约需要 30 分钟。",[["必备","青椒（吃辣的话推荐用杭椒，螺丝椒，不吃辣的用尖椒，甜椒）","f",0],["必备","猪瘦肉","f",0],["必备","盐","s",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","大蒜","f",0],["必备","姜","f",0],["必备","酱油（可选）","s",1],["必备","豆豉（可选）","f",1]],[["参考用量",[["青椒的数量","份数 3 个","f"],["肉量","份数 200g","f"],["盐量","份数 3g","f"],["生抽","份数 3ml","s"],["蚝油","份数 3ml","s"],["大蒜","份数 5g","f"],["生姜","份数 5g","f"],["酱油","份数 2ml","s"],["豆豉","份数 3g","f"]],["每次制作前需要确定计划做几份。一份正好够 1 个人食用","总量：","使用上述条件，计算出计划使用的原材料比例。"]]],[["制作步骤",["将青椒洗净，去除青椒把以及青椒籽，再用滚刀手法切好备用。","大蒜用刀拍一下，再横切成蒜瓣，生姜切碎成姜末。","将猪瘦肉切成肉片（顺着猪肉的纹理切，即刀和肉的纹理呈水平线，出来的肉片，纹路呈“川”字）。","将切好的猪肉洗净，放入空碗，再加入计算好的生抽、蚝油、盐搅拌均匀，腌制 10 分钟。","热锅，不用倒油，把切好的青椒放入锅中，大火干煸至虎皮状后，再加 2g盐继续翻炒 1 分钟 后捞起。","不用洗锅，大火热锅，加入份数 8ml油，等待 30s，加入蒜瓣、姜末翻炒 15s。","加入腌制好的猪肉倒入锅内翻炒 2 分钟，再加入干煸过的青椒翻炒 1 分钟。","根据个人口味喜好加入豆豉，最后加入酱油，继续翻炒 30s。","出锅，盛盘。"]]],["辣椒只能选择青椒，螺丝椒为最优解，切勿选择其他品种辣椒！"]],["2cff1179f1","老妈蹄花汤色奶白，猪蹄软烂脱骨，口感细腻，配上酸辣蘸汁十分开胃，是经典的川式家常菜。猪蹄富含胶原蛋白，白芸豆增添绵密口感，营养丰富。操作需要高压锅和提前浸泡，对新手有一定挑战，但按步骤来做不难掌握。含浸泡和压煮，全程大约需要 2 小时（不含提前一晚浸泡白芸豆的时间）。",[["必备","猪蹄（尽量选择猪前蹄：肉多筋多骨头少）","f",0],["必备","葱","f",0],["必备","姜","f",0],["必备","料酒","s",0],["必备","生抽","s",0],["必备","白芷","f",0],["必备","当归（可选）","f",1],["必备","鸡精","s",0],["必备","盐","s",0],["必备","蒜","f",0],["必备","小米椒","f",0],["必备","白胡椒粉","s",0],["必备","生抽","s",0],["必备","香醋","s",0],["必备","花椒油","s",0],["必备","油泼辣子（可选）","f",1],["必备","白芸豆（没有可用海带）","f",0]],[["参考用量",[["猪蹄：3 根","","f"],["白芸豆：200g","","f"],["当归：2g","","f"],["白胡椒粉：5g","","f"],["姜片：30g","","f"],["当归：2g","","f"],["蒜末：8g","","f"],["鸡精：2g","","f"],["生抽：25g","","f"],["葱花：10g","","f"]],[]]],[["开始制作",["200g 白芸豆提前一晚清水浸泡备用","准备猪前蹄，买菜的时候让师傅从中间劈开，用喷火枪去除毛囊，拿回家清洗","冷水锅中加入猪蹄、大葱段、姜片、料酒，焯水十分钟，撇去浮沫，捞出洗干净备用","高压锅中放入猪蹄、当归、白芷、白胡椒粉、姜片，上汽后压三十分钟，放入白芸豆，再压十分钟，这个时候如果汤底是奶白色，那么恭喜是正确的（如果中途需要加水，只能加热水）","揭盖后加入盐、鸡精、葱花调味","调制灵魂汁子：放入葱、蒜、小米椒，白胡椒粉、生抽、香醋、油泼辣子、花椒油、猪蹄原汤","灵魂汁子，浇给"]]],[]],["e3b3d15df5","锅包肉是东北经典名菜，起源于哈尔滨道台府，以白醋调出鲜明酸香，外壳酥脆、肉片滑嫩，酸甜爽口。猪肉提供优质蛋白质，搭配葱姜等蔬菜开胃解腻。这道菜需要掌握挂浆、油温和复炸技巧，烹饪难度中等偏上，新手需要耐心练习。从腌肉、调糊到炸制出锅，预计制作时长约 90 分钟。",[["必备","猪通脊肉","f",0],["必备","大葱","f",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","胡萝卜（可无）","f",0],["必备","香菜","f",0],["必备","白醋（建议使用 9 度的醋，这样才会有较为突出的老式锅包肉特有的醋香）","s",0],["必备","白糖","s",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","味精","s",0],["必备","土豆淀粉","s",0],["必备","中筋面粉","f",0],["必备","小苏打","s",0],["必备","白熟芝麻（可无）","f",0],["必备","食用油","s",0]],[["参考用量",[["猪通脊肉","300g","f"],["料酒","5ml","s"],["大葱","50g","f"],["姜","30g","f"],["蒜","3-4 瓣","f"],["胡萝卜","10g（可无）","f"],["香菜","10g","f"],["小苏打","5g（可无）","s"],["盐","5g","s"],["生抽","4g","s"],["白醋","55g","s"],["白糖","65g","s"],["玉米淀粉","1.5g（可用土豆淀粉代替）","s"],["方法一：土豆淀粉","170g","s"],["方法二：土豆淀粉","210g 和 中筋面粉 70g","s"],["食用油","1000ml（用于炸制）","s"],["白熟芝麻","5g（可无）","f"]],["每份（约 2 人份）："]]],[["制作步骤",["处理猪肉：","将猪通脊肉切成厚度 8mm 的均匀肉片，去除白色筋膜。","用清水冲洗肉片，去除血水。","可选：加入小苏打 5g，抓匀，静置 5 分钟。","用清水冲洗 1-2 次，去除多余小苏打。","腌制肉片：","在肉片中加入盐 3g、料酒 5ml，拌匀，腌制 15 分钟。","挂浆：","方法一（推荐）：","将土豆淀粉 170g 加入过量清水，搅匀，静置 60 分钟，等待淀粉沉降分层。","倒出上层全部的的清水，保留底部淀粉浆（形如非牛顿流体）。","放入肉片，放入 5ml 清水，放入 3ml 食用油，搅拌均匀。","方法二：","将土豆淀粉 210g 和中筋面粉 70g 混合。","少量多次加入清水，搅拌至酸奶状，提起可拉丝，浆糊能在盆中堆积。","加入食用油 10ml，小苏打 1g，搅拌均匀。","将腌制好的肉片放入浆糊中，拌匀，使每片肉均匀裹上浆。","调制糖醋汁：","混合白糖 65g、白醋 55g、生抽 4g、盐 2g，搅拌均匀，备用。","可选：水 4g、玉米淀粉 1.5g，用于糖醋汁更加粘稠。","准备配菜：","大葱、姜、胡萝卜切丝，香菜切段，蒜切片。","炸制肉片：","第一次炸制：","锅中加入食用油，加热至 170℃（六成热）。","将肉片逐片放入油中，炸至表面定型，表面挂浆不粘筷子，肉上浮，颜色浅黄，约 30 秒（取决于肉片大小），捞出备用。","第二次炸制：","油温升至 200℃（七成热）。","将所有肉片放入油中，炸至外壳金黄酥脆，约 30 秒，捞出备用。","第三次炸制（可选）：","油温升至 220℃（八成热）。","将肉片快速复炸，直到能看到肉片黄里透红，约 30 秒（取决于油温维持能力），增强酥脆度，捞出沥油。","炒制：","锅中留 20ml 底油， 倒入调好的糖醋汁，大火加热至沸腾，熬至汤汁粘稠，约 30-60 秒。","可选：盛出 1/2 的糖醋汁，可以让后面翻炒更加方便","放入炸好的肉片、葱丝、蒜片、胡萝卜丝、香菜段，浇上前面盛出的糖醋汁，快速翻炒 3 次，使汤汁均匀裹在肉片上。","出锅装盘：","将锅包肉盛入盘中，撒上白熟芝麻（可无），即可上桌。"]]],["注意事项：","肉片厚度应为 8mm，过厚过薄都会影响口感。","炸制时控制油温，避免外壳过深或不酥脆，这点非常重要。","熬糖醋汁时，注意熬至粘稠但不结块，避免变成糖浆。","参考资料：","老饭骨版本","老东北美食版本","村驴版本"]],["ed046bdbaf","这是一道经典的四川自贡盐帮菜，麻辣干香，兔肉紧实有嚼劲，入口先辣后鲜，回味悠长。兔肉高蛋白低脂肪，富含卵磷脂和多种氨基酸，营养丰富且易于消化。制作过程需处理多种香料并严格控制火候，对新手有一定挑战。从备料到炒制完成约需 1.5 小时，但放置一夜后风味更佳，值得提前准备。",[["必备","兔肉","f",0],["必备","盐","s",0],["必备","味精","s",0],["必备","蚝油","s",0],["必备","料酒","s",0],["必备","蒜","f",0],["必备","姜","f",0],["必备","小葱/大葱/洋葱","f",0],["必备","干辣椒","f",0],["必备","青花椒","s",0],["必备","八角","f",0],["必备","桂皮","f",0],["必备","香叶","f",0],["必备","山奈","f",0],["必备","白蔻","f",0],["必备","小茴香","f",0],["必备","白芝麻","f",0]],[["参考用量",[["盐量","兔肉斤数 2 克","f"],["味精量","兔肉斤数 1 克","f"],["蚝油量","兔肉斤数 5 克","f"],["料酒量","兔肉斤数 10 克","f"],["油量","兔肉斤数 0.9 ～ 1 升","f"],["蒜量","兔肉斤数 二分之一头蒜","f"],["姜量","蒜量","f"],["小葱/大葱/洋葱总量","兔肉斤数 15 克","f"],["干辣椒量","辣椒段的总体积等于兔肉的总体积","f"],["青花椒量","3 斤兔肉对应吃饭用的小碗，一整碗花椒","f"],["八角量","兔肉斤数 1 粒","f"],["桂皮量","兔肉斤数 大拇指长短的一块","f"],["香叶量","兔肉斤数 5 片","f"],["山奈量","兔肉斤数 黄豆大小的一块","f"],["白蔻量","兔肉斤数 2 颗","f"],["小茴香量","兔肉斤数 15 克","f"],["白芝麻量","兔肉斤数 25 克","f"]],["使用上述条件，计算出计划使用的原材料比例。"]]],[["制作步骤",["蒜、姜扒皮并剁碎备用，八角、桂皮、香叶、山奈、白蔻、小茴香洗净备用。","干辣椒剪成 2 厘米的小段，洗净备用。","小葱/大葱/洋葱洗净，洋葱切成小块。","兔肉剁成 2 厘米的小块，加入盐、料酒、味精调味，腌制 15 分钟。","锅中倒油，油温 4 成热下小葱/大葱/洋葱，中小火煸炒出香味，待到小葱/大葱/洋葱微焦，将其捞出。","开大火升高油温，油温 8 成热时下入兔肉，炸制过程转中小火，炸至兔肉微微焦黄时捞出兔肉。","升高油温，倒入干辣椒、青花椒、八角、桂皮、香叶、山奈、白蔻、小茴香；转小火将辣椒段炸脆。","重新倒入兔肉，加入蚝油、翻炒几分钟。","关火，加入蒜、姜、白芝麻，翻炒均匀。","放置一夜更加入味。"]]],["在操作的第 6 步骤中要注意：油量应该淹没兔肉，若未淹没需要及时补充。","在操作的第 7 步骤中要注意：辣椒极容易炸糊，炸糊会变成黑色，这个过程非常快，所以一定要小火，基本等到没太多水气蒸发时，就可以下兔肉了。"]],["55a0094b37","荔枝肉是一道酸甜酥香的福州传统闽菜，外焦里嫩的肉块裹着红亮的酱汁，搭配水果添入清爽果香。猪瘦肉富含优质蛋白质，凤梨含有膳食纤维和维生素，能帮助开胃解腻。制作过程需要切肉、挂糊和两次油炸，略有挑战但步骤明确，适合有一定下厨基础的美食爱好者尝试，大约 45 分钟就能端上餐桌。",[["必备","瘦肉","f",0],["必备","凤梨","f",0],["必备","鸡蛋","f",0],["必备","食用油","s",0],["必备","白砂糖","s",0],["必备","淀粉","s",0],["必备","生抽","s",0],["必备","鸡精","s",0],["必备","姜末","f",0],["必备","芝麻","f",0],["必备","番茄酱","s",0],["必备","香醋","s",0]],[["参考用量",[["鲜香菇","2 朵","f"],["蟹味菇","30 g","f"],["瘦肉","150 g","f"],["凤梨","100 g","f"],["鸡蛋","1 个","f"],["食用油","500 ml","s"],["白砂糖","5 g","s"],["淀粉","100 g","s"],["生抽","5 ml","s"],["鸡精","5 g","s"],["姜末","5 g","f"],["芝麻","2 g","f"],["番茄酱","20 g","s"],["香醋","2 ml","s"]],["每份："]]],[["制作步骤",["瘦肉切块（每块 2-3 cm ），放入大碗中，加入鸡蛋 1 个 、生粉 50 g 、生抽 3 ml 、鸡精 2 g","充分搅拌，直至生粉包裹住瘦肉块（太稀则继续加生粉，太干则加水），然后加入 5 ml 油，在充分搅拌后备用","在准备一个碗，加入番茄酱、鸡精 3 g 、生抽 2 ml 、姜末、白砂糖、生粉 10 g \\香醋、凉水 200 ml ,充分搅拌后备用","切一个凤梨, 准备 6 个 （每个 1.5-2 cm）凤梨块","起锅烧油，倒入 500 ml 油，一直烧油直到听到油炸声","将瘦肉一个一个放入锅中（切记不可以整碗倒入），保证每个肉不要粘在一起","全部放入瘦肉后，每 30 S 用勺子来回两面翻转瘦肉块，直至瘦肉块表面金黄","取出瘦肉，一分钟后倒入油锅中继续炸，直至瘦肉块表面出现焦黄后，取出放入大碗备用","起锅，倒入汤汁，30 S 后倒入瘦肉块、凤梨块，充分翻炒后 出锅","摆上芝麻"]]],["更多情况下，福州当地会选用马蹄（解腻）和马铃薯（洗油），因为疫情期间买不到，所以选用了凤梨","闽菜以甜为主，如果吃不惯的可以放弃白糖","可以通过勺子敲打瘦肉块，听到声响来判断是否炸透瘦肉"]],["f5107f31d9","一道少油低卡的家常凉菜，鸡丝嫩滑入味，麻油与香醋调和出微麻微酸的清爽口感，适合夏日解腻。鸡胸肉富含优质蛋白且脂肪含量低。做法简单，新手也能轻松上手，从备料到完成大约只需 30 分钟。",[["必备","鸡胸肉（常温冷冻均可）","f",0],["必备","麻油（花椒油）","s",0],["必备","生抽","s",0],["必备","香醋","s",0],["必备","白糖","s",0],["必备","盐","s",0],["必备","料酒","s",0],["必备","姜","f",0],["必备","凉白开水","f",0]],[["参考用量",[["鸡胸肉","200 克","f"],["麻油","5 毫升","s"],["生抽","4 毫升","s"],["香醋","4 毫升","s"],["白糖","3 克","s"],["盐","2 克","s"],["姜","20 克","f"]],["每份："]]],[["制作步骤",["姜切片，备用","锅中倒入 4 升水","加入鸡胸肉、姜片","倒入 20 毫升料酒","开大火不盖盖将水烧开","水开后转中火，用勺子将浮沫捞出","继续煮 5-7 分钟，如果是非冷冻肉煮 5 分钟，冷冻肉煮 7 分钟","鸡胸肉大小会影响成熟时间，用筷子插入鸡胸肉，如果能轻松插入，代表鸡肉熟了。如果不熟需延长煮制时间","用凉白开水冲泡鸡胸肉，使鸡胸肉降至室温","顺着鸡胸肉纹理将鸡胸肉撕成细丝","准备一个碗","碗中加入准备好的麻油、生抽、香醋、白糖、盐","搅拌料汁，使糖和盐尽量溶化","将料汁倒入鸡丝中，搅拌均匀"]]],["这道菜是隔离期间用现有材料做的，有条件可以加入香菜、小葱等进行调味，喜欢吃辣的可以加入辣椒油"]],["f4c88d5af5","这是一道经典中式卤味，肉质鲜嫩入味，香气浓郁，卤汁可反复使用、越陈越香，适合做凉菜、下酒或搭配主食。菜品富含优质蛋白和多种维生素，营养均衡。制作需要一点耐心，但步骤清晰，对新手比较友好。提前浸泡去血水、熬糖色和高压卤制约需 1 小时，再浸泡过夜让风味充分渗入，第二天取出切片即可享用。",[["必备","卤料包（超市即可购买）","f",0],["必备","黄豆酱","s",0],["必备","豆瓣酱","s",0],["必备","蚝油","s",0],["必备","南腐乳","f",0],["必备","洋葱","f",0],["必备","生姜","f",0],["必备","大蒜","f",0],["必备","干辣椒","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","盐","s",0],["必备","白糖（最好是黄冰糖，用于熬糖色）","s",0],["必备","啤酒","f",0],["必备","牛腱子（或其他肉类）","f",0],["必备","高压锅","t",0],["必备","滤网","t",0]],[["参考用量",[["卤料包","1 包（约 10g）","f"],["黄豆酱","15ml","s"],["豆瓣酱","15ml","s"],["蚝油","15ml","s"],["南腐乳","15ml","f"],["洋葱","半个（约 100g）","f"],["生姜","30g","f"],["大蒜","40g","f"],["干辣椒","10g","f"],["生抽","120ml","s"],["老抽","60ml","s"],["盐","10-15g","s"],["白糖","30g（用于熬糖色）","s"],["啤酒","1 罐(330ml)","f"],["牛腱子","500g","f"],["清水 足量（需要没过所有肉类）","","f"]],["每次制作前需要确定计划做几份。一份约可供 2-3 人食用。","每份："]]],[["制作步骤",["建议在此之前查看炒糖色教程","牛腱子提前浸泡在冷水中 3 小时以上，去除血水"]],["准备卤水",["准备糖色：锅中加入 30g 白糖，小火加热至糖完全融化并呈现棕褐色，加入 150ml 热水，搅拌均匀备用","将洋葱切块，生姜和大蒜拍碎，干辣椒掰断备用","在锅中加入足量的水，放入卤料包、洋葱、生姜、大蒜、干辣椒，大火烧开","加入黄豆酱、豆瓣酱、蚝油和南腐乳各 15ml，搅拌均匀","倒入准备好的糖色，混合均匀","加入生抽 120ml 和老抽 60ml，搅拌均匀","加入 10-15g 盐调味","倒入 1 罐啤酒(330ml)，再次烧开"]],["卤制牛肉",["牛腱子放入锅中焯水 2-3 分钟，捞出并用热水冲洗干净表面的浮沫","将焯水后的牛腱子放入已烧开的卤水中，确保卤水没过所有肉类","盖上高压锅盖，上汽后继续烹饪 25-30 分钟","烹饪完成后，不要开盖保温，自然冷却并浸泡一晚上（这样会更入味）","将卤好的肉取出放入冰箱冷藏，使其成型","食用前取出切片，可直接食用或凉拌"]],["保存卤水",["卤水重复使用方法：每次卤完肉后，将卤水过滤，去除所有固体内容物，重新烧开杀菌，冷却后可冷藏或冷冻保存。使用时按原配方比例重新添加调味料。（加水量根据卤水使用情况而定）","卤水保存得当可以使用很长时间，且越老越香。","重要提示：如卤制素菜，必须另取一部分卤水，单独使用，并且卤制完素菜的卤水不可重复使用。"]],["凉拌调料",["将蒜末、葱花、白芝麻、辣椒粉按 1:1:1:1 的比例混合，依个人口味加小米辣，热植物油中加入少量芝麻油或藤椒油，分次泼在调料上，再加入生抽、醋、蚝油各 10ml，5ml 糖，味精/鸡精，最后 15ml 卤汤混合均匀。","凉拌时可搭配拍黄瓜、木耳、油炸花生米、香菜等配菜。"]]],["卤水可另取一部分做牛肉面，作为白水面条的汤底，再加上自己喜欢的蔬菜，味道极佳。","卤水："]],["559e643a38","这道汤菜清鲜不腻，羊肉软烂入味，萝卜饱吸汤汁后甘甜绵糯，是北方冬季常见的家常暖身菜。羊肉富含优质蛋白和铁，萝卜含有维生素与膳食纤维，两者搭配温补脾胃、驱寒助消化。虽然需经焯水去腥和两次炖煮，但步骤清晰易循，新手也能顺利上手。整体制作大约需要两小时，若用高压锅可缩短至大约一 小时。",[["必备","羊排","f",0],["必备","白萝卜","f",0],["必备","大葱","f",0],["必备","花椒","s",0],["必备","白芷（可选）","f",1],["必备","姜","f",0],["必备","料酒或者黄酒","f",0],["必备","食用盐","s",0],["必备","冰糖","s",0],["必备","水","f",0]],[["参考用量",[["羊排","400g","f"],["白萝卜一根","","f"],["大葱一根","","f"],["花椒","10 粒","s"],["姜","10g ，一般买一头姜，从中切大约 4 片即可","f"],["料酒或者黄酒","30ml-40ml","f"],["食用盐","10g","s"],["冰糖","2-4 粒","s"],["水：没过食材的量，需要","1000ml","f"]],["每份："]]],[["制作步骤",["萝卜去皮、滚刀切成 3-5cm 的大块，备用","羊排在购买时可以让卖家切好，因为家用刀一般难以切动，备用","羊肉冷水下锅，加入一半的料酒，一半的葱姜，煮 10 分钟去掉血腥，（可选）把焯的过程中出现的血沫子可以用勺子盛出来","另起一锅冷水，放入切好的白萝卜，放入一半的冰糖，等水开后煮 5 分钟去掉白萝卜的辣味","盛出来焯好的羊排，放入高压锅中，加水没过所有食材后再增加大约 300ml 的水","将剩余的葱姜料酒，花椒，冰糖，白芷（可选），盐放入锅中，盖锅等待上汽后计时，中火炖大约 15 分钟。","如没有高压锅，则放入普通锅中，炖大约 40 分钟到 1 小时。","关火，等待高压锅放气完毕，开盖，加入之前焯好的萝卜，调味，加入 3-10g 的食盐或者水，品尝汤的咸淡，","再开火，中火，高压锅上汽再炖 10 分钟，普通锅盖盖再炖 20 分钟","关火，盛盘"]]],["操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水至没过食材。"]],["5f0ecc0a98","一道麻辣浓郁的川味家常菜，汇集蔬菜、肉类和豆制品，口感香辣过瘾、层次丰富。荤素搭配提供了优质蛋白质和多种维生素，营养全面。操作步骤清晰，需要掌握焯水和翻炒火候，对新手有一定挑战，总制作时间约 30 分钟。",[["必备","青菜（油菜、油麦菜、菠菜）","f",0],["必备","无骨肉（猪肉、牛肉、鸡肉、鱼丸、火腿肠）","f",0],["必备","干豆腐","f",0],["必备","北京麻辣方便面","f",0],["必备","干辣椒","f",0]],[["参考用量",[["青菜共需","455 克，其中油菜、油麦菜、菠菜的比例按自己喜好分配即可","f"],["无骨肉共需","430 克，其中猪肉、牛肉、鸡肉、鱼丸、火腿肠的比例按自己喜好分配即可","f"],["干豆腐","152 克","f"],["北京麻辣方便面","1 袋","f"],["干辣椒","5 克","f"],["麻辣香锅调料","110 克","f"]],["此数值大约是 3 个人的量。","以上内容中，青菜、无骨肉、干豆腐、北京麻辣方便面的配比为推荐配比，如果有自己喜欢的食材，可以按喜好重新分配比例。"]]],[["制作步骤",["烧开一锅水（水量能没过第 2-4 步中的食材即可）。","在开水中放入青菜，焯 5 分钟后盛出备用。","在开水中放入无骨肉，焯 4 分钟后盛出备用。","在开水中放入北京麻辣方便面，煮 2 分钟后盛出备用。","倒出开水，擦干锅具，放入 105 克食用油，大火加热 30 秒。","放入麻辣香锅调料，翻炒 20 秒。","放入干辣椒，翻炒 10 秒。","放入焯过的青菜，改中火，翻炒 3 分钟。","放入焯过的无骨肉，翻炒 3 分钟。","放入煮过的北京麻辣方便面，用筷子翻动 1 分钟。","关火，出锅。"]]],["关于火候的说明：","大火通常温度在 240 摄氏度，以电磁炉为例，输入功率大约 2 千瓦。","中火通常温度在 120 摄氏度，以电磁炉为例，输入功率大约 1.4 千瓦。"]],["47662cf259","这道香辣滑嫩的豆腐菜以咸鸭蛋替代传统豆瓣酱，咸鲜中带着微麻微辣，格外开胃下饭。富含优质蛋白和钙、铁等多种微量元素。制作难度适中，对新手友好，全程约需 40 分钟。",[["必备","内脂豆腐（推荐清美）","f",0],["必备","水果刀","t",0],["必备","咸鸭蛋（推荐留夫鸭的，这个是灵魂）","f",0],["必备","五花肉（超市的肉糜也行）","f",0],["必备","大蒜","f",0],["必备","生姜","f",0],["必备","小米椒（不吃辣的可选）","f",1],["必备","香辣酱（推荐广乐的）","s",0],["必备","花椒","s",0],["必备","食盐","s",0],["必备","酱油（味极鲜酱油）","s",0]],[["参考用量",[["1 盒内脂豆腐","","f"],["1 枚咸鸭蛋","","f"],["20-30g","五花肉","f"],["两瓣大蒜","","f"],["2 片生姜","","f"],["5 根小米辣","","f"],["5g 蒜蓉辣酱","","s"],["20 颗花椒","","s"],["3g 食盐","","s"],["10g 酱油","","s"]],[]]],[["制作步骤",["大蒜和生姜切碎，备用","小米辣切成辣椒圈，备用","五花肉切成肉糜（本来就是买的肉糜的跳过）","肉糜中加入一半的食盐和味极鲜酱油，搅拌均匀，备用","鸭蛋用菜刀竖着对半切开（注意安全），去除蛋黄（一定要去除，不然会腥），剩下的蛋白捣碎成大约 2 mm 2 mm 大小，不用太碎，备用","打开豆腐包装，用水果刀将在盒子中的豆腐划成大约 2.5 cm 3 cm 大小，备用","热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","调成小火，放入大蒜、生姜、辣椒圈、花椒、咸鸭蛋、蒜蓉辣酱翻炒 20 秒，炒出香味","调成中火，放入肉糜，翻炒大约 1 分钟，肉炒变色","调成小火，放入豆腐，将剩下的食盐、味极鲜酱油酱油均匀的洒在豆腐上","从锅边倒入开水（不然豆腐容易破），没过豆腐即可","开大火，水沸腾后立马转入中火，等待大约 10 分钟","等到水只剩 1/5 并且豆腐表面已经入色，关火，盛盘"]]],["期间一定要注意观察，防止糊锅"]],["9d94804193","蚂蚁上树是一道经典的川味家常菜，咸香微辣，粉丝软滑吸汁，肉末细嫩鲜香。以红薯粉丝和肉末为主料，富含碳水化合物与蛋白质，能快速补充能量。制作难度中等，步骤清晰，对新手比较友好，全程约需 20 分钟即可完成。",[["必备","红薯粉丝","f",0],["必备","猪肉末（或牛肉末）","f",0],["必备","郫县豆瓣酱","s",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","食用油","s",0],["必备","蒜末、姜末","f",0],["必备","小葱（可选）","f",1]],[["参考用量",[["红薯粉丝","80g（干重）","f"],["猪肉末","150g","f"],["郫县豆瓣酱","15g","s"],["生抽","10ml","s"],["老抽","5ml","s"],["食用油","10ml","s"],["蒜末","10g","f"],["姜末","5g","f"],["清水","300ml（用于煮粉丝）","f"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["红薯粉丝提前泡软，泡水时间为 20 分钟，备用","将蒜、姜分别剁碎，备用","锅烧热，加入 10ml 食用油，加入蒜末、姜末炒香","加入猪肉末翻炒至肉色发白且微微出油","加入郫县豆瓣酱，炒至红油析出","加入生抽和老抽，翻炒均匀","倒入 300ml 清水，煮沸","放入泡软沥干的粉丝，用筷子轻轻拨动防止粘连","中小火煮约 5 分钟，直至粉丝完全吸收汤汁、呈现微微收干状态","依据口味可撒入小葱末，关火装盘"]]],["粉丝不建议煮太久，易断且口感变差；若时间过长汤汁应适当减少","郫县豆瓣酱含盐量较高，可根据口味酌情减少生抽用量","可加入 0.5g 白胡椒粉调味，风味更佳"]],["074f1fb325","这是一道客家传统名菜，成菜酱红油亮、汤汁黏稠，扣肉肥而不腻、软烂醇香。五花肉富含优质蛋白和脂肪酸，搭配梅干菜能提供膳食纤维。整体工序稍多，需要掌握煮、炸、蒸的火候，对新手有一定挑战。从备料到出锅，连同浸泡梅菜的时间在内，大约需要 2.5 小时。",[["必备","五花肉","f",0],["必备","梅菜","f",0],["必备","五香粉","s",0],["必备","食用油","s",0],["必备","白砂糖","s",0],["必备","老抽","s",0],["必备","生抽","s",0],["必备","小米椒","f",0],["必备","蒜末","f",0],["必备","食用盐","s",0],["必备","鸡精","s",0]],[["参考用量",[["五花肉","200 g","f"],["梅菜","30 g","f"],["五香粉","2 g","s"],["食用油","300 ml","s"],["白砂糖","5 g","s"],["老抽","30 ml","s"],["生抽","20 ml","s"],["小米椒","1 个","f"],["蒜末","10 g","f"],["食用盐","2 g","s"],["鸡精","2 g","s"]],["每份："]]],[["制作步骤",["梅菜放到清水中，浸泡 1 小时","锅中倒入 50 ml 食用油，将整个五花肉猪皮朝下，放到锅中 1 分钟 ，取出挂掉猪皮 【可选】","锅中加入开水，放入五花肉，大火煮 20 分钟 （筷子可以插进五花肉），取出五花肉","在五花肉表面涂抹均匀老抽、五香粉、白砂糖，放置 15 分钟","起锅烧油，加入五花肉，中火油炸直至两面金黄色（3-5 分钟）","起锅烧油，倒入梅菜，加上小米椒、蒜蓉、鸡精、食用盐后翻炒，直至炒干梅干菜水分","五花肉切片（后端 0.5-1 cm）,放在大碗中，散上梅干菜","中火蒸 45 分钟","拿个盘子倒盖在五花肉大碗中，将五花肉倒在盘子中"]]],["制作过程中发现，脆皮五花肉真香 Orz","不喜欢吃甜的可以去掉白砂糖，不影响主流程","倒数第二个步骤，可以根据个人喜好调整时间","炒干梅干菜的作用是为了后续吸油（盲猜）"]],["28b13176f5","奶酪培根通心粉是经典美式家常菜，口感浓郁绵密，奶酪包裹弹牙通心粉，搭配香脆培根，咸香满足。富含蛋白质与钙质，但热量和脂肪较高，建议偶尔享用。制作需要一定耐心，掌握基础白酱和火候对新手略有挑战，整体难度中等。不烘烤时约 30 分钟即可上桌，若选择烘烤需额外预热和烤制，总时长约 1 小时。",[["必备","通心粉","f",0],["必备","奶酪","f",0],["必备","肉类","f",0],["必备","洋葱","f",0],["必备","黄油","s",0],["必备","面粉","f",0],["必备","牛奶","f",0],["必备","大蒜","f",0]],[["参考用量",[["通心粉","100-125g","f"],["奶酪","40-55g，若要烘烤额外准备 25g， 条状","f"],["培根或其他肉类","100-125g","f"],["洋葱","25g-40g 切成碎","f"],["黄油","15g","s"],["面粉","10g","f"],["牛奶","125ml","f"],["大蒜半瓣，切碎","","f"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。"]]],[["制作步骤",["奶酪要磨成碎末","洋葱切成条状","通心粉用微咸的水煮 6 分钟","中火","锅中放入黄油，等待融化","加入洋葱","洋葱软化后加入大蒜","大蒜香味出来后，加入肉类，等待 5 秒","小火","分四次加入牛奶，每次搅拌 5 秒后再加下一次","加入面粉并充分搅拌","加入奶酪并搅拌均匀","将通心粉和奶酪搅拌","如果不打算烘烤，可以直接吃了","烘烤：","预热烤箱至 180°C","将额外的 50g 芝士铺在通心粉之上","等待烤箱预热至 180°C 后，将通心粉放入","烤至表面金黄,约 24 分钟"]]],["本料理及其不健康，有大约 1300 大卡，80g 脂肪，不建议常吃。"]],["3a226a15db","这道红烧肉成菜色泽红亮，肥肉入口即化、瘦肉酥烂不柴，咸中带甜，是典型的南方甜口风味。五花肉提供优质蛋白和丰富的胶原蛋白，香辛料还能去腥暖胃。制作虽需熬糖色与慢炖，但每一步都拆解得清晰易懂，新手跟着操作也能成功，全程约 1.5 小时即可端上桌。",[["必备","注：如果有可能，请尽量把刀磨的锋利一些。","f",0],["必备","工具：锅（砂锅为宜，铝锅其次，高压锅也可以，最好不要铁锅、铜锅）","t",0],["必备","主料：五花肉","f",0],["必备","辅料：油、冰糖、老抽、料酒、香叶、八角、生姜、盐、葱、开水、凉水、蒜、花椒","s",0]],[["参考用量",[["猪五花肉：1000g（约","2 斤）。注：生肉烹饪后缩水脱脂严重，此分量最终出肉量约满足 2-3 人正常饭量。如仅 1 人食用，建议所有食材剂量减半","f"],["油：100-150ml，色拉油、猪油、花生油都可以","","f"],["姜：","6 片","f"],["小葱：约","30g（3-4 根），葱白切段备用","f"],["大蒜：约","25g（5-6 瓣），中间切开备用","f"],["冰糖：50g（约大拇指甲盖大小的碎单晶冰糖","15 块）。如果上一步炒糖色已经使用了 50g，此处的 50g 为炖煮时二次调味使用，可根据对\"南派甜口\"的接受度调整至 30g","s"],["白砂糖：30g","","f"],["老抽：15ml","","f"],["料酒：总量","30ml（其中 20ml 用于前期焯水去腥，10ml 用于后期炖煮提鲜）","f"],["凉水：没过食材的量即可，看锅大小准备","","f"],["开水：没过食材的量即可，看锅大小准备","","f"],["香叶：4 片","","f"],["八角：3 个","","f"],["盐：2-3g","","f"],["花椒：10g","","f"]],["一份正好够 2-3 人吃（1 人食用建议所有剂量减半）。"]]],[["制作步骤",["建议在此之前查看炒糖色教程","猪五花肉先不切小块，切成能放入锅中的大块（约 5–6cm 宽）即可","生姜切片（每片厚度约 3mm ）","开水烧开","凉水自来水即可","小葱小葱白色的部分葱白切成小段（小葱最佳，大葱也可以）","蒜中间切开，不要拍扁，否则难以捞出以至最后收汁时影响味道","请将辅料分为两个\"预备包\"：","A包（去腥用）：2 片姜、2 段葱段。","B包（炖煮用）：剩下的 4 片姜、葱白、蒜瓣、花椒、八角、香叶，统一放入一个小碗中备用。","凉水锅中放入五花肉大块，加入 20ml 料酒 与 A包（2 片姜、2 段葱段），煮 15 分钟去掉血腥，捞出来后洗干净；","将焯过水的五花肉捞出，稍微放凉（不烫手即可），切成边长约 3cm × 3cm × 3cm 的正方体块（焯水后肉质收紧，此时切块比生肉时更容易且成品大小更均匀。3cm 切块最终成品约为 2.5cm，是最适宜入口且容易烧透的尺寸）","另起锅炒糖色，注意：在此菜谱中，请采用其中提到的\"操作 2\"来制作，即在糖液起密集小泡时，迅速将 B包（生姜、葱白、蒜、花椒、八角、香叶）倒入锅中爆香。","爆出香味后（约 5-10 秒内），先不要加开水，而是立刻将焯过水的五花肉倒入锅中大火翻炒，让肉块均匀裹上糖色并煸炒出油脂。待闻到肉香后，再倒入开水至没过全部肉，盖上锅盖，转中小火炖煮 50 分钟-60 分钟（高压锅则为 40 分钟）；","加入 10ml 料酒；","盖上锅盖煮至沸腾后，每隔 25 分钟打开盖子将浮在表面的油和沫捞出；","当水的高度减至肉最高的高度与锅底高度的 3/5 时，转中火，并捞出除肉和水以外的所有辅料，开始收汁；","打开锅盖，待汤汁快没有的时粘稠状出锅（切记不可收干）；"]]],[]],["d0ed2e37aa","这是一道经典的西式煎牛排，焦香外壳包裹着鲜嫩多汁的肉心，搭配黄油、大蒜和香草，风味浓郁。富含优质蛋白质、油脂及铁、锌等矿物质。烹饪流程对新手较为友好，但掌握火候仍需一些练习，全程 15-30 分钟即可完成。",[["必备","平底锅（有条件的推荐铸铁平底锅）","t",0],["必备","锡箔纸（可选）","f",1],["必备","厨房纸（可选）","f",1],["必备","汤匙","f",0],["必备","牛排，参见如何选择不同种类的牛排","f",0],["必备","橄榄油（推荐特级初榨橄榄油）","s",0],["必备","黄油","s",0],["必备","盐（推荐大颗粒海盐）","s",0],["必备","黑胡椒粉（推荐粗颗粒现磨黑胡椒）","s",0],["必备","大蒜","f",0],["必备","香料（可选，推荐迷迭香或者百里香，尽量使用新鲜的植物枝条而不是这些香料磨成的粉）","s",1],["必备","预制牛排酱汁（可选）","f",1],["必备","配菜（ 可选，按喜好准备，这里推荐芦笋，口蘑，小番茄，小土豆，选其中的 1-2 种即可）","f",1]],[["参考用量",[["牛排","450-500g（两片牛排）","f"],["黑胡椒粉","2g","s"],["盐","5g","s"],["大蒜","1 个（约 25-30g，实际用量约为 5-10g）","f"],["橄榄油","10-15ml","s"],["黄油","20-25g","s"],["口蘑","5-10 个","f"],["小土豆","5-10 个（每个约 20g）","f"],["小番茄","5-10 个（每个约 15g）","f"],["百里香","2g（若使用新鲜百里香枝条，取 3-6 根，每根约 10cm 长即可）","f"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["备料",["从冰箱中取出牛排解冻。","如果牛排处于冰冻状态，需提前一晚转移至冷藏室，并在烹饪前半小时放置在常温中。","请勿将牛排置于水中或加热解冻。","将小番茄，小土豆和口蘑洗净，对半切开备用。","将大蒜剥皮，留 5-8 个较大的蒜瓣，用刀背压扁备用。","牛排的预处理","对于肉眼牛排（见如何选择不同种类的牛排），使用厨房剪刀竖直插入到肉眼牛排中心的结缔组织，剪 1-2 刀。这是因为肉眼牛排的“肉眼”（即这块结缔组织）在高温下会剧烈收缩导致牛排变形，使得牛排无法均匀受热。","对于西冷牛排，如果您不喜欢西冷牛排边上的油脂，可以用刀慢慢将其剔除。","随后，使用厨房纸包裹牛排，将牛排上附着的水全部吸干，直至牛排放在案板上拿起后不留下明显水渍即可。"]],["烹饪",["注：本过程适用于制作 2-3cm 厚、5-7 成熟的牛排。如果您喜欢不同的熟度，考虑将前半部分煎制时间在此基础上增加或缩短 20-30%。","将炉灶打开高火（见附录对于火力大小的说明），同时锅中加入橄榄油，热锅 15-30 秒。","腌制牛排。将海盐和黑胡椒均匀的洒在牛排的全部表面并用手涂抹，揉搓，使得盐和胡椒颗粒尽量嵌入到肉中。注意，腌制完成后牛排需要立即下锅，不推荐提前腌制牛排。这是因为外表涂抹的盐会析出牛肉中的水分，影响烹饪的同时丧失风味。","热锅至油温 6-8 成（参见油温判断技巧），将牛排由近及远的缓慢放入锅中。","如果您使用了土豆作为配菜，可以将土豆放入碗中，然后放进微波炉加热 10 分钟，或者放入开水煮 3-5 分钟。","单面煎制 1.5 分钟（这个时间适用于 2-3cm 厚大约的牛排。如果您的牛排更薄，考虑将这个时间缩短为 1 分钟。如果您的牛排更厚，考虑将这个时间增加至 2-2.5 分钟。）","翻面，再煎制 1.5 分钟。","对于西冷牛排和菲力牛排，您需要使用筷子或者锅铲将牛排竖起来，煎它的侧面约 30 秒。","将炉灶切换至中火，随后按顺序快速加入黄油、大蒜、百里香。用锅铲推动黄油在锅中快速涂抹直至完全融化。将大蒜压在牛排下以增加风味。","将平底锅倾斜地放在灶上，使得油全部流到锅的一侧。","将香料和大蒜放置在牛排上，用汤匙舀起锅中的油，不断地淋在牛排上。这个过程持续 30 秒，随后将牛排翻面，再重复这个过程 30 秒。","您可以通过观察油淋在牛排表面时的状态来判断当前的火候。如果油淋在牛排上时冒泡并且油的颜色没有变成深褐色，则油温合适。","如果您的牛排没有擦干净或使用了不推荐的方式解冻，或者使用盐进行了提前腌制，这个时候锅中会出现大量水，导致牛排最后是被“煮熟”的，从而丧失风味。","如果牛排表面出现大量的油泡并且油的颜色变成深褐色，则说明油温过高，您需要将锅移开灶台，稍等片刻再继续淋油。","将牛排盛出放在案板上，用锡箔纸包裹，等待 5-10 分钟。这个过程（称为醒肉）的作用是利用牛排自身的温度继续加热，锁住水分。","将配菜（土豆，番茄，蘑菇）倒入锅中，开中火煎 5 分钟。","取出牛排，用刀切成宽度 1.5cm 宽度的肉条，此时您可以观察到牛肉的熟度。","取出配菜，装盘，淋上锅中剩余的油或者牛排酱汁（可选）"]]],["火候的控制","煎制牛排是控制火候的艺术。限于篇幅，这里简单给出一些定量评估火力的方法和本文中用到的与火候相关的术语。更多内容参见油温判断技巧。","对于电磁炉：","高火：功率 1.8Kw - 2.2kw。","中火：功率 800w - 1.4kw。","小火：功率 200w - 600w。","对于燃气灶：","高火：旋转气阀至最大出气速度的 70%-90%。","中火：旋转气阀至最大出气速度的 40%-60%。","小火：旋转气阀至最大出气速度的 10%-30%。","关于调味","牛排的调味不一定需要遵循本指南的规范。通常来说，大蒜、黑胡椒和黄油是必须的，但如果您不喜欢迷迭香或百里香等唇形科植物等味道，您可以自由尝试其他牛排调味料进行调味。市面上也有售卖的多种烤肉调味盐可供选择。笔者曾发现一种中西结合的做法，即将小米辣切开与蒜片加入橄榄油中煎，并作为调味在最后淋到牛排上，也独具风味。"]],["580de1fe37","这是一道咸香下饭的湖南家常小炒，五花肉的油润、鸡蛋的嫩滑与青椒的清香彼此融合，口感层次丰富。猪肉与鸡蛋提供优质蛋白质，搭配青椒补充维生素 C，营养均衡。中等难度，需要注意煸炒火候和调味顺序，新手稍加练习也能做好。预计备菜 7 分钟，烹饪 10 分钟，总共约 17 分钟就能出锅。",[["必备","猪肉（推荐五花肉）","f",0],["必备","青椒","f",0],["必备","蒜片","f",0],["必备","豆瓣酱","s",0],["必备","酱油","s",0],["必备","小米椒","f",0],["必备","白糖","s",0],["必备","姜片","f",0]],[["参考用量",[["猪肉","250g","f"],["青椒","3 个","f"],["蒜片","2 片","f"],["豆瓣酱","10g","s"],["小米椒","1 个","f"],["白糖","5g","s"],["酱油","15ml","s"],["姜","2 片","f"]],["每次制作前需要确定计划做几份。这里一份够 12 个人吃。"]]],[["制作步骤",["备菜阶段：将猪肉切片，最好把肥瘦分开放。同时要把青椒和小米辣切成段，蒜片用刀背拍成末，姜切成丝。鸡蛋打到小碗中，用筷子打散。","备好菜，就可正式煮菜了。先将油倒入锅中，锅中开小火，油热后将蛋液倒入锅中，将鸡蛋炒散，炒至断生即可，放回小碗中备用。","将锅中继续加一点油，开小火，锅热后将之前切的肥猪肉倒入锅中逼出猪油。","肥肉出现金黄色的时候，加大火力到中火，将瘦肉一起放入锅中翻炒。","瘦肉全部炒至变色的时候加入备好的姜丝、蒜末和豆瓣酱翻炒均匀给猪肉上色。","放入青红椒、炒至断生的鸡蛋后加入酱油和白糖，继续将它们翻炒到青椒微微断生，保持青椒清脆口感。","出锅上菜！"]]],["如果第一次炒鸡蛋的时候放的油太多，炒猪肉的时候可以视情况不加油。","参考资料下厨房"]],["44f0be44f9","这是一道风味独特的家常菜肴，鸭肉鲜香软烂，透着淡淡啤酒清香，热而不浮、香而不腻。鸭肉富含蛋白质，啤酒去腥增香，搭配食用更有滋味。做法对新手友好，从备料到出锅大约需要 1 小时。",[["必备","鸭肉","f",0],["必备","啤酒","f",0],["必备","生抽酱油","s",0],["必备","老抽酱油","s",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","冰糖","s",0],["必备","干辣椒","f",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","鸡精","s",0],["必备","丁香","f",0],["必备","八角","f",0],["必备","香叶","f",0],["必备","豆瓣酱","s",0]],[["参考用量",[["鸭肉半只（约","1kg）","f"],["啤酒","800ml","f"],["生抽酱油","10-15ml","s"],["老抽酱油","5-10ml","s"],["姜","5 片","f"],["蒜头","12 瓣","f"],["冰糖","10g","s"],["干辣椒","5 个","f"],["料酒","30ml","s"],["盐","8g","s"],["鸡精","5g","s"],["丁香","4 颗","f"],["八角","3 个","f"],["香叶","3 片","f"],["豆瓣酱","20g","s"]],["每份："]]],[["制作步骤",["把鸭子切成 3 cm 小块，鸭肉冷水下锅，加姜片、料酒，焯一遍水，盛出沥干水分，备用。","炒锅烧热，放入约 100ml 食用油，大火待油烧开，鸭肉入锅翻炒至上色。","待鸭肉完全变色（肉眼可见泛白），将鸭肉拨到锅的一边，倒入豆瓣酱和糖，小火翻炒出香味和糖色。","加入丁香、八角、香叶、干辣椒、生抽、老抽、蒜，翻炒出香味。","倒入啤酒，没过鸭肉，加入盐、鸡精，然后中火将鸭子烧 30 分钟（牙口不好的话可以再多烧 5 分钟）。","出锅盛盘，上桌食用。"]]],["啤酒的量一定要足够把所有鸭肉没过，啤酒最好选择清香型的。"]],["5c347933a0","这道菜咸鲜可口，融合了黔式腊肠的醇香与娃娃菜的清甜，是西南菜系中少见的不辣风味，南北皆宜。娃娃菜富含维生素和膳食纤维，搭配腊肠的蛋白质与脂肪，营养均衡。制作过程极为简单，无需掌握火候和额外调味，从备料到出锅仅需 15 分钟，非常适合新手和忙碌的日常。",[["必备","黔式腊肠","f",0],["必备","娃娃菜","f",0]],[["参考用量",[["黔式腊肠","200g","f"],["娃娃菜","300g","f"],["水","750ml","f"]],["按照 1 人的份量："]]],[["制作步骤",["锅内放入 750ml 水，开火加热至沸腾","放入腊肠，计时 13 分钟","放入娃娃菜，计时 2 分钟","关火，夹出腊肠及娃娃菜","娃娃菜切段、腊肠切片，装盘"]]],["根据锅的大小，建议以水量没过食材为宜，宁多勿少","如果没有刀具，娃娃菜和腊肠不切也可以"]],["8d1eb95009","这道广西经典家常菜以青椒包裹调好味的肉馅或虾滑，煎至表皮起皱呈虎皮色后焖煮入味，青椒清香与馅料鲜美交融，咸香微辣，十分下饭。猪肉和虾仁提供优质蛋白质，青椒富含维生素 C，营养均衡。制作需要一点耐心酿馅，但整体流程清晰，跟着步骤操作一般 30 分钟就能完成。",[["必备","青椒（6-8 个，选笔直、肉厚的，不要用灯笼菜椒）","f",0],["必备","猪肉（250g，肥瘦比例 3:7 的前夹肉最佳）","f",0],["必备","葱（2 根）","f",0],["必备","生姜（1 小块）","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","食盐","s",0],["必备","食用油","s",0],["必备","淀粉（可选，涂青椒内壁防粘、勾芡收汁）","s",1],["必备","大蒜（可选，3-4 瓣）","f",1],["必备","蚝油（可选）","s",1],["必备","料酒（可选）","s",1],["必备","鸡蛋（可选）","f",1],["必备","白胡椒粉（可选）","s",1],["必备","白糖（可选）","s",1]],[["参考用量",[["青椒","8 个（约 400g，选笔直肉厚的尖椒）","f"],["猪肉馅","250g（肥瘦比例 3:7）","f"],["葱","2 根（约 30g）","f"],["生姜","1 小块（约 10g）","f"],["生抽","30ml（其中 15ml 调馅，15ml 调酱汁）","s"],["老抽","5ml","s"],["食盐","3g","s"],["食用油","30ml","s"],["淀粉","10g（可选，其中 5g 涂青椒内壁、5g 水淀粉勾芡）","s"],["大蒜","4 瓣（可选，约 15g）","f"],["蚝油","10ml（可选）","s"],["料酒","10ml（可选）","s"],["鸡蛋","1 个（可选）","f"],["白胡椒粉","2g（可选）","s"],["白糖","5g（可选）","s"]],["每份："]]],[["准备馅料",["猪肉洗净剁成肉馅（或用绞肉机），姜切末，葱切葱花","肉馅中加入姜末、葱花、生抽 15ml、老抽 5ml、食盐 3g，搅拌均匀","可选加入：料酒 10ml、蚝油 10ml、鸡蛋 1 个、淀粉 5g、白胡椒粉 2g、白糖 5g","朝一个方向搅拌肉馅至粘稠上劲，腌制 10 分钟"]],["处理青椒",["青椒洗净，去蒂，用筷子小心挖去内部的籽和白筋，保持青椒完整不破","可选在青椒内壁撒干淀粉约 5g，摇晃均匀，帮助肉馅粘附不脱落"]],["酿入肉馅",["将腌好的肉馅用筷子或裱花袋塞入青椒中，尽量填满但不要太紧以防撑破","全部酿好后备用"]],["调酱汁",["碗中加入生抽 15ml、老抽 5ml、清水 100ml，搅拌均匀","可选加入淀粉 5g，使汤汁更浓稠"]],["煎制焖煮",["热锅，倒入 30ml 食用油，油温五六成热时放入酿好的青椒（肉面朝下先煎）","中小火慢煎，翻面使青椒各面都煎至表皮起皱呈虎皮色，盛出备用","锅留底油，可选放入蒜末爆香","倒入调好的酱汁，烧开后放入煎好的青椒","转中小火，盖上锅盖焖煮 5-8 分钟，至汤汁浓稠、青椒变软","开盖大火收汁至汤汁油亮包裹青椒，即可出锅装盘"]],["虾滑 fork 版本",["虾滑酿青椒在广西也很常见，属于正统吃法，非邪修","虾仁 250g 去虾线，用刀背拍成虾泥（保留一定颗粒感，口感更好，直接买成品虾滑得了，买那种三角形的裱花一样直接塞进去）","虾滑馅调味：姜末 5g、食盐 2g、淀粉 5g、生抽 10ml","可选加入：料酒 5ml、白胡椒粉 1g、蛋清半个","朝一个方向搅拌至虾滑上劲，腌制 10 分钟","后续酿入、煎制、焖煮步骤与猪肉版本一致","虾滑易熟，焖煮时间可缩短至 4-5 分钟"]]],["青椒选笔直的比弯的好塞馅料，肉厚的尖椒比薄皮的口感更好","馅料朝一个方向搅拌才能上劲，口感更 Q 弹","青椒内壁涂干淀粉是防粘的关键，煎时肉馅不会脱落","煎至虎皮色是风味来源，不要跳过","酱汁可依个人口味调整，喜欢更辣的可加桂林辣椒酱","虾滑和猪肉馅可以混合使用，比例随意，虾肉增加鲜甜，猪肉提供油脂香","汤汁拌饭极佳，不要收太干"]],["56e617951a","青椒土豆炒肉是一道荤素搭配的家常小炒，口感鲜香脆嫩，酱香浓郁，特别下饭。土豆富含碳水化合物和维生素 C，青椒提供丰富的维生素 C 和膳食纤维，搭配猪肉的优质蛋白质，营养均衡。这道菜做法不复杂，对新手比较友好，从备料到出锅大约只需 1 小时。",[["必备","青椒","f",0],["必备","土豆","f",0],["必备","猪肉（五花肉）","f",0],["必备","葱","f",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","盐","s",0],["必备","酱油","s",0],["必备","土豆淀粉","s",0]],[["参考用量",[["青椒","2 个（共约 200g）","f"],["土豆","2 个（共约 300g）","f"],["猪肉","200g","f"],["葱","1 根（约 10g）","f"],["姜","1 块（约 5g）","f"],["蒜","3 瓣（约 12g）","f"],["盐","7g","s"],["酱油","6-10ml","s"],["食用油","10-15ml","s"],["土豆淀粉","5g","s"],["水","15g","f"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","每份："]]],[["制作步骤",["青椒去除根蒂切小块，土豆去皮切 2mm 薄片，猪肉切 4mm 薄片，葱横纵切 3mm 小段，姜蒜去皮拍散剁碎末；土豆淀粉加入约 15g 水搅拌均匀至水淀粉。","起锅烧油，加热至 7 成热放入猪肉片，缓缓翻滚炒至去肉红色，加入约 3ml 酱油，翻炒肉片均匀上色，放入约 2g 盐。","转 5 成油温，加入葱姜蒜炒 5 秒，然后加入土豆片，转 7 成油温均匀翻炒，加入约 5ml 酱油和 2g 盐，炒至土豆断生，表面轻微焦黄。","转 8 成油温加入青椒，大火煸炒出锅气（有白烟冒出），反复均匀翻炒 1 分钟上色，最后在锅周围倒入水淀粉转 4 成火勾芡。","在外观呈粘稠状态后关火，盛盘"]]],[]],["53bb35aa97","清蒸鳜鱼肉质细嫩，鲜甜本味突出，是讲究原汁原味的家常河鲜做法。鳜鱼富含优质蛋白和多种微量元素，易于消化吸收。处理时需小心鱼鳍，但整体步骤不复杂，新手稍加注意也能胜任。从备料到出锅，大约只需半小时。",[["必备","鳜鱼","f",0],["必备","大葱","f",0],["必备","小葱","f",0],["必备","生抽","s",0],["必备","红辣椒","f",0],["必备","姜片","f",0],["必备","食用油","s",0]],[["参考用量",[["鳜鱼","500g","f"],["大葱","1 节","f"],["小葱","2 根","f"],["生抽","30g","s"],["红辣椒","1 颗","f"],["姜片","3 片","f"],["食用油","20ml","s"]],["每份（约 2 人份）："]]],[["制作步骤",["食材处理：","鳜鱼从腹部切开，去除鱼鳃和内脏，打去鱼鳞，用到在表皮上刮去粘液（这一步也可让热心摊主处理）","鳜鱼身上打上花刀，放姜片，有条件的可以放点猪油，装盘在下面垫一个筷子，便于蒸制时受热均匀","大葱划开后去除中间的芯，只保留外面两层","小葱划开备用","红椒去除辣椒籽和里层辣椒肉备用","将准备好的大葱、小葱、辣椒码在一起，切成丝泡在水里备用","炒制过程：","锅里加水，水量大一些，水热后放入鳜鱼，盖上锅盖，大火蒸制 8 - 10 分钟，蒸鱼四字窍门：汽大火足","蒸鱼过程，另起一个过热油，油需要烧到冒烟","蒸制结束后，倒掉蒸鱼的水，去除姜片，放上葱丝，浇上热油","在倒入生抽或蒸鱼豉油即可上桌"]]],["注意事项：","鳜鱼背部鱼鳍容易伤人，处理时候需要注意，最好用剪刀剪掉","蒸制时间需要根据鱼的大小调整，蒸鱼的关键在于水多汽大火足"]],["eb6061dee3","肉饼炖蛋是一道咸鲜滑嫩的传统家常菜，肉饼吸饱了酱汁，鸡蛋卧在其中，口感软嫩又下饭。它富含优质蛋白质和多种氨基酸，能很好地补充体力。做法十分简单，对厨房新手非常友好，从备料到出锅大约只需要 20 分钟。",[["必备","猪肉末","f",0],["必备","鸡蛋","f",0],["必备","料酒","s",0],["必备","生抽","s",0],["必备","白胡椒粉","s",0],["必备","芝麻香油","s",0]],[["参考用量",[["猪肉末","300g","f"],["鸡蛋","2 个","f"],["料酒","10ml","s"],["生抽","20ml","s"],["白胡椒粉","5g","s"],["芝麻香油","10-15ml","s"]],[]]],[["制作步骤",["在碗中加入猪肉末、料酒、生抽、白胡椒粉、鸡蛋和芝麻香油，搅拌均匀。","将调好味的猪肉末铺在盘子里，肉末中间用勺子挖一个洞，往洞中打入 1 个鸡蛋。","锅中加水至 1/4 高度，水烧开后，将盘子放入锅中，盖上锅盖，蒸 15 分钟。"]]],["在取出肉饼炖蛋时，注意盘子很烫，请小心操作。"]],["d7f381869e","这是一道源自东北的经典炖菜，酸爽鲜香、暖心暖胃。酸菜富含乳酸菌和膳食纤维，排骨提供优质蛋白与钙质，血肠则能补充铁元素。制作时需要耐心处理血肠以防煮爆，对厨房新手有一定挑战。从备料到出锅，预计耗时约一小时。",[["必备","血肠","f",0],["必备","酸菜","f",0],["必备","排骨","f",0],["必备","料酒","s",0],["必备","辣椒","f",0],["必备","香叶","f",0],["必备","八角","f",0],["必备","葱结","f",0],["必备","香油","s",0],["必备","菜籽油","s",0],["必备","蒜","f",0]],[["参考用量",[["血肠","200 克","f"],["酸菜","500 克","f"],["排骨","400 克","f"],["料酒","10 克","s"],["蒜瓣","5 个","f"],["姜粉","5 克","f"],["干辣椒","5 个","f"],["香叶","2 片","f"],["八角","1 个","f"],["葱结","1 个","f"],["香油","10 克","s"],["菜籽油","10 克","s"],["盐","5 克","s"],["蘸料：辣椒油","5 克、生抽 10 克、蒜蓉 5 克、香油 2 克","s"]],["这道菜适合 2-3 人一起吃。这道菜每份应该加入的材料有："]]],[["制作步骤",["血肠用牙签多扎一些小孔，然后放水中小火煮十分钟，不要让水烧开，保持 80 度，否则血肠非常容易爆开。","煮好的血肠切块备用。","排骨放料酒焯水，控干水分备用。","锅内放入菜籽油，放蒜瓣，干辣椒，姜粉炒香。","放入排骨翻炒至表面金黄。","酸菜洗净拧干水分，放入锅中，加入香油翻炒，香油可以更好的去除酸味而且让酸菜更香，大火翻炒二分钟。","加入 600 毫升热水。","转入电压力锅，加香叶，八角，葱结，盐。","浓香模式压 40 分钟。","到时间后放气开盖。加入血肠和枸杞，盖上锅盖焖二分钟即可，血肠是熟的，不需再加热。","倒入盆中，按照上表调制蘸料，即可开吃。"]]],[]],["ac7ce299a2","过油肉是山西传统名菜，肉片滑嫩、蒜苔爽脆，咸鲜微酸，带着陈醋的醇香，属于典型的地方家常风味。猪里脊提供优质蛋白，搭配木耳、蒜苔和葱头，营养均衡。这道菜对火候和上浆技巧有一定要求，更适合有一定下厨基础的爱好者尝试。从备料到出锅，大约需要 40 分钟。",[["必备","猪里脊","f",0],["必备","蒜苔","f",0],["必备","盐","s",0],["必备","酱油","s",0],["必备","葱姜蒜","f",0],["必备","鸡蛋","f",0],["必备","淀粉","s",0],["必备","食用油","s",0],["必备","木耳","f",0],["必备","葱头","f",0],["必备","料酒","s",0],["必备","陈醋","s",0],["必备","花椒粉","s",0],["必备","鸡精","s",0]],[["参考用量",[["猪里脊","150 g","f"],["蒜苔","6 根","f"],["食用油","300ml","s"],["葱姜蒜","50g","f"],["生抽","20ml","s"],["食盐","10g","s"],["鸡蛋","1 个","f"],["淀粉","10g","s"],["木耳","20g","f"],["葱头","100g","f"],["其他调料","20g","f"]],["本人饭量较大，这是本人一人量"]]],[["制作步骤",["木耳提前泡发好，如果着急可以用热水泡发。","猪里脊切片放入碗中，加 20ml 生抽、料酒、花椒粉，打入一个鸡蛋，拿自己的小手搅拌均匀，加入淀粉（建议红薯淀粉）拌匀，倒入 300ml 食用油封浆，腌制 15 分钟。","蒜苔切段大约 3cm，葱头切菱形块备用。","起锅烧油油要多一点，油温五成热，下入腌制好的肉片，将肉片打散，捞出控油备用。","将锅中多余油倒出，留 10ml 油炒菜，油温七成热","下入葱姜蒜爆香，先下蒜苔炒至断生，再下入木耳葱头，加入生抽，花椒粉，翻炒几下将之前炸好的肉片下入翻炒","加 10g 的盐，起锅前加 10ml 的醋和鸡精，起锅装盘。"]]],["炸肉片时，表面微焦即可，注意控制火候。","起锅前也可以打个薄薄的水淀粉，口感更佳。"]],["cc31a9ce45","商芝肉是陕西商县的传统风味菜，色泽红润，质地软嫩，肥而不腻，带有商芝独特的清香。猪肉提供优质蛋白和脂肪，蕨类蔬菜商芝则增添了膳食纤维和多种微量元素。这道菜工序繁琐，对刀工和火候均有要求，适合有一定烹饪基础的人挑战。从备料到成菜，全程大约需要 2.5 小时。",[["必备","带皮猪五花肉（去骨）","f",0],["必备","商芝（又名紫萁，属蕨类，嫩叶可食）","f",0],["必备","葱","f",0],["必备","姜","f",0],["必备","八角","f",0],["必备","蜂蜜","f",0],["必备","醋","s",0],["必备","料酒","s",0],["必备","味精","s",0],["必备","酱油","s",0],["必备","摊鸡蛋皮","f",0],["必备","精盐","s",0],["必备","鸡汤","f",0],["必备","芝麻油","s",0],["必备","熟猪油","s",0]],[["参考用量",[["带皮猪五花肉:","500 克","f"],["商芝:","50 克","f"],["葱:","10 克","f"],["姜:","2 克","f"],["八角:","3 个","f"],["蜂蜜:","15 克","f"],["醋:","5 克","f"],["料酒:","15 克","f"],["味精:","1.5 克","f"],["酱油:","10 克","f"],["摊鸡蛋皮:一张约","15 克","f"],["精盐:","1 克","f"],["鸡汤:","200 克","f"],["芝麻油:","10 克","f"],["熟猪油:","2000 克（消耗约 60 克）","f"]],["每份：两人量"]]],[["制作步骤",["将肉刮洗干净，入煮锅煮至六成熟（变色为白），捞出趁热用蜂蜜、醋涂抹肉皮。","炒锅内放入熟猪油，用旺火烧至八成熟（约 200 度，油表有大量青烟，油状平静），将肉块皮朝下投入，炸至呈金红色时，捞入凉肉煮锅（之前煮完的煮锅）中泡软，放在案板上，切成三寸(10 cm)长、两分(0.6 cm)厚的片，仍然皮朝下，整齐装入蒸碗内。","将 5 克大葱切成 2.4 cm 长的段，5 克切成 2.4 cm 长的斜形片。姜去皮洗净，1.5 克切成片，5 克切成末，摊的鸡蛋皮切成 2.4 cm 长的等腰三角形片。","商芝入沸水锅中煮软捞出，去除老茎、杂质，淘洗干净，切成 3 cm 长的段，放入碗中,加酱油（5 克）、精盐（1 克）、熟猪油（10 克）拌匀，盖在肉片上，另将鸡汤（100 克）放入一小碗中，加酱油（5 克）、精盐（0.5 克）、料酒（15 克）搅匀，浇入蒸碗，再放入姜片、葱段、八角上笼用旺火蒸约半小时后，转用小火继续蒸约一小时三十分钟，熟烂后取出，拣去姜、葱、八角，倒、过滤原汁，将肉扣入汤盘。","炒锅内，放入鸡汤（100 克），加入原汁，用旺火烧沸，下入姜末、葱片、味精后搅匀，投入摊鸡蛋皮，淋芝麻油，浇入汤盘即成。"]]],["商芝属于小地方不特别有名的特产，至少本人在其他地方没有见到过，在制作时可换成其他蕨类蔬菜。"]],["b2ca34b768","一道快手家常小炒，肉片滑嫩，土豆片软韧入味，带有蒜苗清香，属于典型的家常菜风格。瘦肉富含优质蛋白质和铁质，土豆提供碳水化合物和膳食纤维，搭配均衡。制作流程简单明了，需注意刀工和火候，适合有一定基础的新手尝试。从备料到出锅，预计 大约 1 小时即可完成。",[["必备","纯瘦肉","f",0],["必备","土豆","f",0],["必备","蒜苗","f",0],["必备","生粉（玉米淀粉或其他淀粉）","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","食用盐","s",0]],[["参考用量",[["纯瘦肉","200g","f"],["土豆","200g","f"],["蒜苗","2 根（约 20 g）","f"],["生粉","5g","f"],["生抽","10g","s"],["老抽","3g","s"],["食用盐","2g","s"]],["1 人食用版本"]]],[["制作步骤",["土豆去皮、对半切开，再切成约 2mm 的薄片，备用","蒜苗洗净，切成约 1cm 的段，备用","瘦肉洗净切成约 2mm 的薄片，放入碗中，加入 5g 生粉、5g 生抽、3g 老抽腌制十分钟，备用","瘦肉腌制时，烧一锅开水，将土豆片放入锅中，焯水，约 5 分钟","热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","放入瘦肉，翻炒至变色，倒入蒜苗一起炒，蒜苗炒约 20 秒","放入土豆，保持翻炒，加入 2g 食用盐、5g 生抽，","炒约 3 分钟，盛盘"]]],["土豆片焯水注意不宜太久，防止土豆片变软","腌制瘦肉要搅拌均匀"]],["96a9dd92c2","水煮牛肉是川菜中的经典麻辣味型，口感滑嫩、汤汁红亮、香辣烫鲜。牛肉富含优质蛋白质和铁，搭配豆芽可补充膳食纤维。这道菜对新手来说不算太难，但需注意火候和泼油安全，整体制作约需四十分钟。",[["必备","牛肉","f",0],["必备","豆芽","f",0],["必备","鸡蛋","f",0],["必备","香菜","f",0],["必备","豆瓣酱","s",0],["必备","料酒","s",0],["必备","淀粉","s",0],["必备","干辣椒粉","s",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","红辣椒","f",0],["必备","蚝油","s",0]],[["参考用量",[["牛肉","300g","f"],["豆芽","100g","f"],["鸡蛋","1 个","f"],["香菜","5 根","f"],["豆瓣酱","10g","s"],["料酒","10ml","s"],["淀粉","15g","s"],["干辣椒粉","5g","s"],["姜","20g","f"],["蒜","3 瓣","f"],["红辣椒","1 根","f"],["蚝油","8g","s"]],["每次制作前需要确定计划做几份。一份正好够 2 个人吃。","这是一份的量："]]],[["制作步骤",["牛肉洗干净切片。","加入 15g 姜丝，1 个鸡蛋，15g 淀粉，8g 蚝油，10ml 料酒搅拌均匀，腌制 15 分钟。","香菜洗干净切好。","锅里倒油，加入豆瓣酱，5g 姜丝，蒜片。","倒入开水，煮成红汤。","豆芽洗干净去掉尾须，放进开水里焯熟。","将豆芽铺入碗底。","将牛肉片一片一片的放进红汤中，煮熟以后捞出。","将牛肉铺在豆芽上，撒上香菜梗。","撒上香菜叶，辣椒粉，辣椒圈。","另起锅烧热油，将热油淋在菜上面，就完成了。"]]],["参考: 水煮牛肉的详细步骤"]],["a2c99279d9","水煮肉片是一道麻辣鲜香、肉片滑嫩、配菜爽脆的经典川菜，极其适合下饭。猪里脊提供优质蛋白质，搭配豆芽等蔬菜，营养均衡。做法稍显繁琐，尤其需要耐心腌制肉片和制作刀口辣椒，新手大约需要 1 至 2 小时完成。",[["必备","猪里脊肉","f",0],["必备","食用盐","s",0],["必备","胡椒粉","s",0],["必备","生抽酱油","s",0],["必备","料酒","s",0],["必备","鸡蛋清","f",0],["必备","土豆淀粉","s",0],["必备","植物油","s",0],["必备","豆芽","f",0],["必备","凤尾","f",0],["必备","芹菜","f",0],["必备","蒜苗","f",0],["必备","大蒜","f",0],["必备","生姜","f",0],["必备","红泡椒","f",0],["必备","青花椒","s",0],["必备","干辣椒","f",0],["必备","红油豆瓣","f",0],["必备","鸡精","s",0],["必备","白砂糖","s",0],["必备","小葱","f",0],["必备","菜籽油","s",0]],[["参考用量",[["里脊肉的用量为","300g","f"],["小葱","2 根","f"],["生姜","10g","f"],["大蒜","20g","f"],["红泡椒","20g（根据受辣程度选择 0-40 g）","f"],["蒜苗","2 根","f"],["芹菜","3 根","f"],["红油瓣酱","5ml","s"],["鸡精","1.5g","s"],["生抽酱油","5g","s"],["食用盐","5g","s"],["胡椒粉","2g","s"],["料酒","3g","s"],["鸡蛋清","1 个","f"],["土豆淀粉","7g","s"],["植物油","280g（根据情况选择，想吃重油就多加 100g）","s"],["菜籽油","200g（根据情况选择，想吃重油就多加 100g）","s"],["绿豆芽","100g","f"],["凤尾","1 根","f"],["白砂糖","1g","s"],["小米辣干辣椒","20g（根据受辣程度选择 0-40g）","f"],["青花椒","5g（根据情况选择，想吃麻就多 5g）","s"]],[]]],[["制作步骤",["里脊肉改刀成小块，再切成 2 毫米薄片（可根据自己的口感改进），放入碗中，加入清水清洗两遍来去除血水和杂质，捞出挤干水分备用。","碗中加入食用盐 1.5g，胡椒粉 1g，生抽酱油 5g，料酒 3g，然后朝着一个方向搅拌 2 分钟，使其入味。","另外准备一个碗，加入一个鸡蛋清，加入 7g 土豆淀粉，一个方向搅拌均匀，倒入肉中","再次一个方向搅拌均匀（肉表面就形成了润滑膜，这样会使肉更加鲜嫩）","最后再加入 30g 植物油轻轻搅拌（防止肉片粘连）。","绿豆芽 100g，凤尾 1 根（改刀成小条），芹菜 3 根切成小段，蒜苗 2 根拍散切成小段。","大蒜 20g 剁碎，生姜小块剁碎，红泡椒 20g 剁碎。","小米辣干辣椒 15g，青花椒 3g，锅内加入油滑锅，油稍许热了将多余的倒出备用留 50g 底油，下入干辣椒、花椒，开小火炒香，切记不要炒糊（颜色要变黑即可），倒出在菜板上剁细。","锅烧热，放入 100g 植物油烧至 6 成热，加入 2g 青花椒、干辣椒爆香，配菜下锅，加入 1g 食用盐，炒至断生，盛入碗中垫底备用。","锅洗干净，加入 150g 植物油烧至 6 成热，加入制作好的姜蒜红泡椒，爆香后加入豆瓣 10g，开小火把豆瓣爆香炒出红油即可。","加入 800 毫升清水（根据实际情况选择），大火烧开，转小火调味，加入食用盐 2.5g，鸡精 1.5g，1g 白砂糖提鲜，1g 胡椒粉，5g 水淀粉（根据实际情况选择）将汤汁收浓稠一点。","汤汁开后，开小火将腌制好的肉片分开依次下锅，然后开中火将肉片烫熟，用锅铲轻轻推动一下避免粘连，待汤汁烧开，肉片熟后捞出放入碗中配菜上，再将原汤倒入（不超过菜品）。","碗中均匀撒上刀口辣椒、蒜蓉和葱花。","锅洗干净，加入 200g 菜籽油，烧至 7 成热，然后一次性均匀泼在碗中肉片上（注意安全），美味完成。"]]],["垫底的蔬菜根据自己口味选择（蘑菇、白菜、油麦菜等）。","刀口辣椒制作嫌麻烦也可以直接用干辣椒段和青花椒代替。","特别注意肉的腌制（搅拌的时候朝着一个方向、血水处理干净），保证肉滑嫩（鸡蛋清、淀粉搅拌均匀）。","水煮牛肉也可以按照这个做法。","参考资料","美食作家王刚R"]],["1009d033da","蒜苔炒肉末是北方家常菜，咸鲜脆嫩，蒜香浓郁。蒜苔富含膳食纤维和维生素，五花肉提供蛋白质，荤素搭配均衡。做法简单，备料轻松，新手也能快速上手。从切配到出锅大约只需 10 分钟。",[["必备","五花肉薄片","f",0],["必备","蒜苔","f",0],["必备","食用盐","s",0],["必备","生抽","s",0],["必备","食用油","s",0],["必备","蒜瓣","f",0]],[["参考用量",[["蒜苔","1 扎（每扎蒜苔约 190g）","f"],["五花肉薄片","4 片（约 20g）","f"],["食用油","10ml","s"],["蒜瓣","2 瓣","f"],["生抽","15ml","s"],["食盐","2g","s"]],["1 人食用版本"]]],[["制作步骤",["蒜苔切成 5cm 小段，备用","五花肉切成 5mm 5cm 丝状，备用","蒜瓣拍碎切成末，备用","热锅，锅内放入 10ml 食用油。等待 10 秒让油温升高","放入蒜末，中火翻炒 10 秒 将蒜末炒出香味","放入五花肉和 5ml 生抽，中火翻炒 30 秒 将肉炒熟并上色","将蒜苔放入锅内并加入 10ml 生抽，翻炒 30 秒","锅内加入 20g 水，中火翻炒 5 分钟 将蒜苔炒至稍稍变软","最后加入 2g 食盐，中火翻炒 30 秒，即可出锅装盘"]]],["加入食盐前可尝一下咸淡，自行决定是否增减盐量","选用五花肉薄片是因为切肉简单且不用腌制即可入味"]],["eddfa2ae85","台式卤肉饭是一道浓香四溢的台湾家常料理，肉条软糯入味，酱汁琥珀般油亮，浇在热米饭上满口脂香。富含优质蛋白、胶原蛋白和碳水，能快速补充能量。做法对新手非常友好，只需备好食材、掌握火候，全程约 1.5 小时即可完成，其中动手操作仅需半小时，剩下的交给小火慢炖。",[["必备","红葱头（火葱）","f",0],["必备","带皮五花肉 （可用猪绞肉代替）","f",0],["必备","鸡蛋（可选）","f",1],["必备","食用油","s",0],["必备","生抽酱油","s",0],["必备","米酒（可用料酒代替）","f",0],["必备","大蒜","f",0],["必备","香叶","f",0],["必备","八角","f",0],["必备","冰糖","s",0],["必备","白胡椒粉","s",0],["必备","五香粉（可选）","s",1],["必备","米饭","f",0]],[["参考用量",[["红葱头","25 g","f"],["带皮五花肉","500g","f"],["鸡蛋","4 个（可任意修改鸡蛋个数）","f"],["食用油","15 ml","s"],["生抽酱油","75 ml","s"],["米酒","10 + 25 ml","f"],["大蒜","25 g","f"],["香叶","2 片","f"],["八角","1 颗","f"],["冰糖","20 g","s"],["白胡椒粉","6 g","s"],["五香粉","6 g","s"],["米饭 （根据个人食量决定）","","f"]],["每次制作前需要确定计划做几份。以下约莫 23 人份。"]]],[["制作步骤",["带皮五花肉切成 $0.7cm（长）\\times 0.7cm（宽） \\times 2.5cm（高）$ 的细长条","红葱头、大蒜切末备用","鸡蛋煮熟剥壳，并用刀划破蛋白（便于入味），备用。","大火热锅，锅内放入 15 ml 食用油，让油滑满锅底即可。","放油的目的是防止五花肉刚下锅时粘锅。等待 5s 使油温稍微升高。","放入五花肉条，翻炒至肉色稍微变白，沿锅边淋入米酒 10ml 。继续翻炒至五花肉不再出油。","将切好的红葱头加入锅中，翻炒 1 分钟爆出油葱香味。","将切好的红葱头加入锅中，翻炒 30 秒。","把猪肉推到旁边，放入冰糖加热到融化冒泡变成焦糖，再把猪肉一起翻拌，让焦糖均匀附着。","加入生抽炒出香气。","呛入米酒 25 ml ，水加到淹过猪肉，加入白胡椒粉、五香粉、八角、香叶、水煮蛋，沸腾后转小火卤 1 小时。","注意: 不同酱油的咸淡不一，卤的时候务必试味道，太甜加酱油，太咸加点糖或水调整。","小火炖煮过程中，每隔 15 分钟 搅拌检查一次，防止粘锅。","如发现过干，则可加入 100ml 清水继续炖煮。","1 小时后，开大火收汁直到酱汁浓稠，呈现有光泽的琥珀色，即完成。","炖煮结束后，乘一碗米饭，将软烂的卤肉浇在米饭上，并加上卤蛋，开始享用。"]]],["对于五花肉切条步骤，定义：五花肉带皮面向上摆在桌上，此时肉皮所在平面为长宽形成的平面，垂直此平面的为高。肉条最终效果是肥瘦相间的细长条。（注意：此处肉条一定要细，即长宽较小。细肉条更易于炖煮软糯）。","五花肉切条小技巧：","若五花肉是未冷冻的，可以放入冰箱冷冻室 30 分钟 再取出切条。","若是冷冻五花肉，可以在常温下放置 30 分钟 后再切条。","切条时可以较小的力度将刀刃与肉快速摩擦，如此更易于切割并保护五花肉肥瘦相间的结构。"]],["652907c158","糖醋里脊酸甜浓郁、外酥里嫩，是广受欢迎的家常风味，在多地域菜系中都很常见。猪里脊提供优质蛋白，但裹粉油炸和糖醋汁使整体热量偏高。制作时需要掌握腌制、复炸和调汁火候，对新手稍有挑战，建议提前备好料并一气呵成。从备料到出锅大约需要 45 分钟到 1 小时。",[["必备","里脊肉","f",0],["必备","醋","s",0],["必备","白糖","s",0],["必备","淀粉","s",0],["必备","鸡蛋","f",0],["必备","生抽","s",0],["必备","料酒","s",0],["必备","蚝油","s",0],["必备","番茄酱","s",0],["必备","白胡椒粉","s",0],["必备","盐","s",0]],[["参考用量",[["里脊肉","500g","f"],["醋","10g","s"],["白糖","30g","s"],["淀粉","50g","s"],["鸡蛋","50g","f"],["生抽","10ml","s"],["料酒","20g","s"],["蚝油","10g","s"],["番茄酱","30ml","s"],["白胡椒粉","5g","s"],["食盐","10g","s"]],["每份："]]],[["制作步骤",["腌肉：将猪里脊肉先切厚片，用刀背拍一拍，把肉拍松一点。切成一个手指头粗的条，加料酒，生抽，蚝油，食盐，白胡椒粉，一个鸡蛋，将肉用手抓匀，腌制 20 分钟以上。","调酱：番茄酱+10g 醋+30g 白糖+150ml 清水，搅拌至糖融化，备用。","裹粉：先把粉全部裹好再来炸，这样在炸的时候就不会手忙脚乱。准备一个大碗，里面放淀粉，把每一根肉条都满满裹上淀粉。","炸制：油温 160 摄氏度下里脊，可以拿一个干筷子放在油里面试一下，周围冒小泡就可以下锅。","炸到表面微黄可以捞出，全程中火。然后等油温升高到 200 摄氏度，把里脊倒进去重新炸一次，只需 40 秒，表皮就会很脆，马上捞出。","裹酱：另外拿一个锅，锅里放底油，把调好的酱汁倒进去，煮到冒泡，把炸好的里脊放进去，翻炒，让每一根都裹上酱汁。","下炸好的里脊肉翻炒，关火盛出。"]]],["里脊要多炸几遍，注意火候，否则达不到外焦里嫩的效果！","下厨房","百度百科"]],["394129e4f9","糖醋排骨是一道酸甜可口、外酥里嫩的传统名菜，广受欢迎。排骨富含优质蛋白和钙质，有较好的滋补效果。这道菜涉及焯水、油炸、炒糖色和收汁等多个步骤，对火候和调味有一定要求，不算特别适合新手，但按照优化后的流程操作成功率较高。预计制作时长为 大约 45 分钟。",[["必备","排骨","f",0],["必备","白砂糖","s",0],["必备","食用油","s",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","老抽","s",0],["必备","鸡精","s",0],["必备","姜片","f",0],["必备","芝麻","f",0],["必备","番茄酱","s",0],["必备","香醋","s",0],["必备","五香粉","s",0]],[["参考用量",[["排骨","300 g","f"],["白砂糖","30 g","s"],["食用油","300–350 ml （油量需根据锅具大小调整，如用于深炸则以足以覆盖排骨 2/3 为准）","s"],["生抽","5 ml","s"],["蚝油","5 ml","s"],["老抽","5 ml","s"],["鸡精","2 g","s"],["姜片","2 片","f"],["芝麻","2 g","f"],["番茄酱","10 g","s"],["香醋","5 ml","s"],["五香粉","0.5 g","s"]],["每份："]]],[["制作步骤",["排骨与姜片放入冷水中，大火加热至水沸腾、出现大量泡沫后转中火，待水持续沸腾时再转小火焯水 2–3 分钟，捞出备用。","用开水反复清洗排骨 2–3 遍，确保彻底去除血沫。","在锅中倒入足够量的食用油进行深炸（油量依据锅具大小而定，建议约 300 ml 供一般家庭使用），待油温升至约 170°C 后，下排骨炸制 3–5 分钟，直至表面略呈金黄色，捞出控油。","另取干净锅，置于小火上加热 50 ml 热水，加入白砂糖 30 g，轻轻搅拌直至糖完全溶解，并略呈淡黄色。此步骤的重点在于观察糖溶解情况，无需过分依赖颜色变化。","将炸好的排骨倒入炒制糖水的锅中，迅速翻炒 30 秒后，依次加入香醋 5 ml、生抽 5 ml、蚝油 5 ml、鸡精 2 g、番茄酱 10 g、五香粉 0.5 g，再次翻炒 30 秒，使调料均匀裹覆排骨，然后加入开水至刚好没过排骨。","用大火将锅中液体煮沸后，加入老抽 5 ml 进行上色，并快速收汁；若排骨块较大，可转小火焖煮 5–10 分钟以便更好地入味，切勿采用中火长时间炖煮 20 分钟，以免损伤口感。","起锅装盘，撒上芝麻 2 g，即可享用。"]]],["炸排骨时可根据实际情况轻撒少量干淀粉于排骨表面，以提升酥脆口感。","焯水时注意火力变化：冷水下锅后先用大火至水沸腾、泡沫丰富，再转中火，最后转小火焯水；焯水后应使用开水清洗，避免因温差过大导致肉质变柴。","步骤四的关键在于确保白糖完全溶解，无须过分依赖颜色变化判断。","收汁时应快速翻炒，使排骨均匀裹上调料，避免长时间煮炖造成口感损失。"]],["12b486833c","田螺酿是阳朔“十八酿”之首，螺肉韧而紧致、猪肉嫩滑，紫苏薄荷清香扑鼻，曾登上《舌尖上的中国 2》。富含蛋白质和多种微量元素，螺肉与猪肉搭配营养互补。这道菜步骤稍多，对新手有一定挑战，需提前半天让田螺吐沙，正式制作约 40 分钟，适合节假日全家一起动手。",[["必备","大田螺（乒乓球大小，约 20-25 个，上午买回放一下午吐沙）","f",0],["必备","猪肉（250g，肥瘦比例 3:7 的前夹肉最佳）","f",0],["必备","新鲜薄荷叶（一小把，点睛之笔）","f",0],["必备","紫苏叶（一小把，与田螺是绝配）","f",0],["必备","生姜（1 小块）","f",0],["必备","葱（2 根）","f",0],["必备","桂林三花酒","f",0],["必备","生抽","s",0],["必备","食盐","s",0],["必备","食用油","s",0],["必备","酸笋（可选，50g）","f",1],["必备","大蒜（可选，4-5 瓣）","f",1],["必备","干辣椒（可选，3-4 个）","f",1],["必备","蚝油（可选）","s",1],["必备","淀粉（可选）","s",1],["必备","白胡椒粉（可选）","s",1]],[["参考用量",[["大田螺","20 个（约 1000g）","f"],["猪肉","250g","f"],["新鲜薄荷叶","10g","f"],["紫苏叶","10g","f"],["生姜","1 小块（约 15g）","f"],["葱","2 根（约 30g）","f"],["桂林三花酒","15ml","f"],["生抽","30ml（其中 15ml 调馅、15ml 调味汤汁）","s"],["食盐","5g","s"],["食用油","30ml","s"],["酸笋","50g（可选）","f"],["大蒜","5 瓣（可选，约 20g）","f"],["干辣椒","4 个（可选）","f"],["蚝油","10ml（可选）","s"],["淀粉","10g（可选）","s"],["白胡椒粉","2g（可选）","s"]],["每份（2-3 人）："]]],[["吐沙（提前半天）",["上午买回田螺，放入清水盆中，静置一下午吐沙","可在水中滴几滴香油（或者芥末）加速吐沙"]],["处理田螺",["用刷子将田螺外壳刷洗干净（这一步可以时间久一些）","用老虎钳或菜刀剪去田螺尾部（约剪掉 1/3 到一半）","大锅烧水，水开后放入田螺焯烫 1-2 分钟（时间不可太久，螺肉会老）","捞出后用牙签挑出螺肉，去掉螺盖和黑色泥肠","螺壳用水冲洗干净，甩干水分备用"]],["制作馅料",["螺肉用盐抓洗干净，剁成碎粒（不要剁成泥，保留颗粒感才有嚼头）","猪肉剁成肉末","薄荷叶、紫苏叶切碎，姜切末，葱切葱花","将螺肉碎、猪肉末、薄荷碎、紫苏碎、姜末、葱花放入碗中","加入三花酒 15ml、生抽 15ml、食盐 3g","可选加入：蚝油 10ml、白胡椒粉 2g、淀粉 10g","朝一个方向搅拌至馅料粘稠上劲","图省事上面的所有东西直接放入打肉机直接打。"]],["酿制",["将馅料用筷子塞入田螺壳中，尽量塞满塞紧，但不要撑破螺壳","依次酿完所有田螺"]],["焖煮",["热锅，倒入 30ml 食用油，可选放入酸笋和干辣椒炒出香味","倒入清水或高汤约 300ml，加生抽 15ml、食盐 2g，大火烧开","将酿好的田螺放入锅中，盖上锅盖，中小火焖煮 10 分钟","焖煮过程中不要频繁翻动，等肉馅六七成熟定型后再轻轻翻动","开盖，放入剩余的新鲜薄荷叶和紫苏叶，再焖 2-3 分钟","大火收汁至汤汁浓稠，即可出锅"]]],["食用方法：先吮吸壳内汤汁，再用牙签挑出或用嘴猛吸出肉馅——\"嗦螺贴唇猛吸气\"","螺肉和猪肉最佳比例为 1:1","薄荷是这道菜的精华，紫苏配田螺是绝配，两者至少要有其一","没有三花酒可用料酒代替，但风味会打折扣","焯水时间一定要短，久了螺肉变老发硬","搭配冰镇漓泉啤酒是阳朔当地的标准吃法","参考资料：阳朔田螺酿百度百科"]],["7d553adc2f","这道甜辣烤全翅利用空气炸锅烹制，外皮微焦、内里多汁，甜中带辣的风味很受欢迎。鸡肉富含优质蛋白质，用空气炸代替油炸大幅减少了油脂，吃起来负担更轻。制作流程清晰明了，只需提前腌制并中途翻面一次，对新手也比较友好。从处理食材到出锅大约需要 3 个小时，大部分是静置腌制的时间，实际操作并不繁琐。",[["必备","空气炸锅","t",0],["必备","鸡全翅","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","蒜粉","f",0],["必备","胡椒粉","s",0],["必备","糖","s",0],["必备","甜椒粉","f",0],["必备","辣椒粉","s",0],["必备","蚝油","s",0],["必备","水","f",0],["必备","油","s",0],["必备","锡纸盘","f",0],["必备","保鲜膜","t",0]],[["参考用量",[["鸡全翅","4 个","f"],["生抽","45ml","s"],["老抽","15ml","s"],["蒜粉","10g","f"],["胡椒粉","5g","s"],["糖","10g","s"],["甜椒粉","10g","f"],["辣椒粉","5g","s"],["蚝油","15ml","s"],["水","20ml","f"],["油","10ml","s"]],["一份为一人餐，多人餐请等比例增加。","一份："]]],[["制作步骤",["将 4 个新鲜鸡全翅取出，在翅中两根骨头之间用刀划开表皮，正反面各一刀","将 4 个鸡全翅放入碗中，加入生抽 45ml ， 老抽 15ml ， 蒜粉 10g ， 胡椒粉 5g ， 糖 10g ， 甜椒粉 10g ，辣椒粉 5g ， 蚝油 15ml ， 水 20ml 以及油 10ml","用勺子将酱汁均匀的抹在鸡全翅上，尤其是翅中的刀口处，大约花费 3 分钟","用保鲜膜盖住防油腌制中鸡全翅的碗，放入冰箱冷藏格静置 120 分钟","取出鸡全翅，锡纸盘中放入鸡全翅 4 个，将碗中残余酱料均匀倒在鸡全翅上","锡纸盘放入空气炸锅的烤篮上，用 200 摄氏度烤 25 分钟","打开空气炸锅，小心取出锡纸盘，将鸡全翅翻面","继续 200 摄氏度烤 25 分钟","取出即可食用"]]],["本例中鸡全翅口感为微辣，需增加辣度请增加辣椒粉用量，但不宜超过 30g","鸡全翅指包含翅尖，翅中和翅根的鸡翅","本品效果微焦，如不喜欢焦褐色外观可 不向锡纸盘中倒入残余酱汁并 每面只烤制 20 分钟","实际烤制效果请根据自己空气炸锅的功率判断","甜椒粉起增加色泽和风味作用，本身不能作为辣味剂","腌制时间可自由掌控，建议在 60 分钟到 180 分钟之间为宜","刚出锅的锡纸盘比较烫，请用夹子夹取或使用湿抹布之类的隔热材料拿取"]],["8c3128e092","排骨软烂脱骨，土豆绵软入味，酱香浓郁微甜微辣，是一道典型的北方家常炖菜。富含蛋白质、钙质和碳水化合物，营养均衡。制作略有难度，需掌握炒糖色与火候，但步骤清晰，新手也能尝试，全程大约 1.5 小时。",[["必备","肋排","f",0],["必备","土豆","f",0],["必备","姜","f",0],["必备","小葱","f",0],["必备","料酒","s",0],["必备","白糖","s",0],["必备","干辣椒","f",0],["必备","八角","f",0],["必备","花椒","s",0],["必备","桂皮","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","蚝油","s",0],["必备","黄豆酱","s",0],["必备","盐","s",0],["必备","食用油","s",0]],[["参考用量",[["肋排","750g","f"],["土豆","300g","f"],["姜","30g （分为两份：15g 焯水用，15g 炒制用）","f"],["小葱","25g （分为两份：15g 打成葱结，10g 切葱花）","f"],["料酒","25ml （分为两份：15ml 焯水用，10ml 炒制用）","s"],["白糖","10g","s"],["干辣椒","5g","f"],["八角","1g （约 1-2 颗）","f"],["花椒","1g （约 10 粒）","s"],["桂皮","1g （一小块）","f"],["生抽","10ml","s"],["老抽","5ml","s"],["蚝油","5ml","s"],["黄豆酱","5g","s"],["盐","3g （最后收汁调味用）","s"],["开水","700ml","f"],["食用油","20ml","s"]],["注意：以下参数为标准 2-3 人份的精确配置。"]]],[["预处理：食材切配与防氧化",["处理土豆： 将 300g 土豆去皮，切成不规则的滚刀块 。切好后立刻泡入一盆清水中，隔绝氧气防止表面氧化发黑，备用。","处理葱姜： 将 30g 姜全部切成薄片（分成两份 15g）。将 25g 小葱处理好：15g 挽成一个葱结，剩余 10g 切成细小葱花备用。"]],["预处理：调料封装与异步任务",["封装酱汁碗（一键调用）： 拿一个小碗，依次加入 10ml 生抽、5ml 老抽、5ml 蚝油、5ml 黄豆酱，彻底搅拌均匀，放在灶台触手可及处备用。","封装香料碟（一键调用）： 拿一个小碟，放入 5g 干辣椒、1g 八角（约 1-2 颗）、1g 花椒（约 10 粒）、1g 桂皮（一小块），以及刚才切好的 15g 姜片，备用。","开启异步水程： 按下电热水壶开关，开始烧制 700ml 开水。（确保炒制完成时，开水刚好就绪）。"]],["初步加工：排骨焯水与脱水",["冷水焯水： 将 750g 肋排冷水下锅，加入 15g 葱结、15g 姜片、15ml 料酒。大火煮沸后，继续保持沸腾焯水 2 分钟，逼出内部血沫。","热洗冷防： 捞出排骨，必须用热水将排骨表面残留的浮沫清洗干净（遇冷水肉质会剧烈收缩变硬）。","绝对脱水（防爆防溅）： 洗净的排骨必须用厨房纸彻底吸干表面水分，装盘放在炒锅旁边备用（防止后续下入高温糖色时发生剧烈炸锅）。"]],["核心炒制：糖色与爆香（高并发阶段）",["炒制糖色： 热锅凉油，加入 20ml 食用油。将 10g 白糖倒入锅中，中小火不停搅拌。翻炒至白糖完全融化冒泡，并呈现红棕色的焦糖色 。","上色煎制： 迅速加入彻底脱水的 750g 排骨，转中大火翻炒。煎制约 2-3 分钟，至排骨两面微微金黄，且均匀裹满焦糖色。","一键爆香： 在锅中拨出一小块空地，直接倒入【香料碟】。利用锅底的热油爆香约 10 秒，激发出香料的脂溶性香气。","一键调味： 顺着热锅边缘淋入剩余的 10ml 料酒激发出锅气。紧接着直接倒入【酱汁碗】，翻炒约 30 秒，让酱料完全包裹排骨并炒出浓郁酱香。"]],["炖煮收汁：挂霜与出锅",["加水长炖： 此时电热水壶已沸腾，直接加入 700ml 滚烫的开水（水量需没过排骨），大火烧开。随后盖上锅盖，转小火持续焖煮 40 分钟。","加入土豆： 40 分钟后打开锅盖，将泡在水里的 300g 土豆捞出沥干，下入锅中。重新盖上锅盖，继续小火焖煮 15-20 分钟，直到用筷子能轻松扎透土豆块。","调味收汁： 打开锅盖，加入 3g 盐（此时可尝一下汤汁，根据个人口味酌情微调）。转大火开始翻炒收汁，大约需要 3-5 分钟。直到汤汁变得浓稠，均匀地挂在排骨和土豆上即可关火。","点缀出锅： 盛盘出锅，在表面均匀撒上预处理好的 10g 葱花作为 UI 点缀即可。"]]],[]],["638d392536","酸辣开胃、口感 Q 弹，是一道家常凉拌小吃。鸡爪富含胶原蛋白，对皮肤有益。去骨步骤繁琐费力，制作难度较高，不太适合新手尝试。全程耗时约 8 小时 15 分钟。",[["必备","鸡爪","f",0],["必备","姜","f",0],["必备","料酒","s",0],["必备","大葱","f",0],["必备","大蒜","f",0],["必备","小米辣","f",0],["必备","洋葱","f",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","黑醋（推荐陈醋）","s",0],["必备","白糖","s",0],["必备","盐","s",0],["必备","花椒油","s",0],["必备","香菜","f",0],["必备","柠檬","f",0]],[["参考用量",[["鸡爪","1kg","f"],["姜","4 片","f"],["料酒","65g","s"],["大葱","3 段（5cm 一段）","f"],["大蒜","10 瓣","f"],["小米辣","4 个少辣，6 个中辣，12 个大辣（推荐大辣）","f"],["洋葱 （半个）","","f"],["生抽 75g","15g 5","f"],["蚝油 30g","15g 2","f"],["黑醋（推荐陈醋）","50g","s"],["白糖","10g","s"],["盐","3g","s"],["花椒油","10ml","s"],["香菜","3 颗","f"],["柠檬","2 颗（以 1 颗为单位来调整酸度）","f"]],["一份正好够 2-3 个人吃。"]]],[["鸡爪处理",["用剪刀 / 刀 把鸡爪上的指甲的部分全部剪掉 包括指甲下面的肉和骨头，让它一点指甲都不剩","用水把他们洗干净，放一边","把鸡爪放入大锅中，准备去腥味","大葱，料酒，姜 全放进去","加水没过鸡爪","大火煮开 中途可以把浮末捞起来","水开100度，沸腾后等 10 分钟","关火，捞出来，把水沥干，洗干净，放入盆里"]],["去骨",["这一步可以省略，此步骤大约花费 2 小时","放入冰箱，冷冻层 20 分钟","把全部放入不是冷冻层的冰箱，然后分批10个一批拿出来去骨","从手指（鸡爪的）最前端开始，每只手指都要用刀划开划到它的手背部分","再从手背部用刀分划开至整个手臂","把每只手指关节处都掰一掰按手指出声音时那种","按着它的手指最前端，往里推，每只手指都一样，先推到中间手掌手背部分","每只手指皮脱离后，从手掌开始往手臂部分推直到整个脱下来了","放入碗中，备用"]],["调配腌料",["小米辣 切均匀小颗","大蒜，洋葱，香菜切碎","柠檬对半切开，把柠檬汁挤入鸡爪的容器里","把全部调料倒入装鸡爪的容器，小米辣，大蒜，洋葱和香菜也放进去","抓拌均匀","放入冰箱一个晚上（6 个小时）","调配好后全部放入准备好的鸡爪"]]],["操作时，需要注意观察沸腾的水位线，如发现低于 3/4 的食材应加热水至没过食材。","鸡爪去骨教程 ：bili89324373958"]],["296ff42c12","西红柿牛腩汤汁浓厚酸甜可口，牛肉软绵醇香，是道开胃下饭的家常菜。富含蛋白质、维生素和番茄红素，营养均衡。对新手有一定挑战，需要掌握炖肉火候和番茄炒汁的技巧。一般初学者大约需要 90 分钟完成。",[["必备","西红柿","f",0],["必备","牛腩","f",0],["必备","燃气灶（西红柿去皮用）","f",0],["必备","高压锅/砂锅/普通铝锅（铁锅）","t",0],["必备","2cm 两段葱段、两片姜片，葱花、姜各 10g","f",0],["必备","生抽、白胡椒粉，白糖，料/黄酒，八角三小片","f",0],["必备","牛腩（挑选肥瘦相间的口感比较好）","f",0]],[["参考用量",[["西红柿","3-4 个（每个约 200g）","f"],["牛腩","500g","f"],["食用油","20-30ml","s"]],["每份："]]],[["制作步骤",["牛腩切条、切块成长宽高均 2cm ，冷水下锅，开锅煮制 2 分钟去除血水，捞出冲洗干净","另起锅 2L 水烧开，加入 2cm 两段葱段、两片姜片、八角、料/黄酒 5-10ml，放入焯好的牛肉，盖盖炖制（砂锅 1 小时，高压锅炖肉模式 45 分钟），筷子能轻松插透就证明炖好了","西红柿去皮：西红柿头部滑十字至腰线，筷子/刀叉从果蒂捅入，煤气灶小火，一边转动一边烤，及时拿下来查看，起皮后撕下来，切块。越小越好","撕皮小心烫，去皮后的西红柿特别滑，慢切注意安全","起锅烧油，油温 7 成热，葱、姜各 10g，番茄下锅，炒透炒出番茄红色，加入煮好的牛腩和原汤，原汤刚刚没过牛肉即可","根据个人口味放入盐、糖、生抽调味盖盖","开锅后大火继续炒制 3-5 分钟","待番茄汁呈中等粘稠程度后关火，散入葱花，盛盘"]]],["用火注意安全、用火注意安全、用火注意安全","用砂锅/铝锅炖肉时，水开后转中小火/小火，使用高压锅见学习使用压力锅","教程中的番茄去皮方式是目前为止本人实践最快的方式","绝对不用番茄酱和少加佐料，尽可能还原食材的原味"]],["79dd3866d5","一道家常炖菜，酸甜开胃，汤汁浓郁，牛肉软烂，土豆绵密。牛肉提供优质蛋白，西红柿富含番茄红素，搭配土豆和洋葱，营养均衡。操作简单，无需复杂技巧，新手也能轻松上手。从备菜到出锅大约需要 1 至 1.5 小时。",[["必备","牛肉","f",0],["必备","小料","f",0],["必备","葱","f",0],["必备","姜","f",0],["必备","料酒","s",0],["必备","花椒","s",0],["必备","八角","f",0],["必备","香叶","f",0],["必备","白糖 or 冰糖","s",0],["必备","酱油（可选）","s",1],["必备","老抽","s",0],["必备","黑胡椒粉（或白胡椒粉）","s",0],["必备","土豆","f",0],["必备","西红柿","f",0],["必备","洋葱","f",0]],[["参考用量",[["牛肉","500-700g","f"]],[]],["小料",[["葱一根，姜四片，料酒","","s"],["花椒","3g","s"],["八角一个（半）","","f"],["香叶两片","","f"],["油","15ml （若用牛腩可根据喜好减少为 10ml）","s"]],[]],["调味品",[["白糖 or 冰糖","","s"],["酱油（千禾酿造生抽无添加），老抽","","s"],["黑胡椒粉（白的也行）2g","","f"],["土豆两三个（看喜好，锅能盛了为准）","","f"],["西红柿拳头大小中等个头两三个","","f"],["比拳头大一点的洋葱一个","","f"]],[]]],[["制作步骤",["备菜:","土豆去皮、切成 5cm 大块，备用","西红柿切十字花刀，开水烫后去皮，把中间的芯去掉，切 3cm 小块备用","葱切 4g 的葱花出来，剩下的掰成 5-8cm 大段","牛肉泡凉水半小时去血水，或凉水下锅煮至表面变白捞出，期间撇去浮末","洋葱切 0.5-1cm 小粒","制作","全程中火","凉水没过牛肉，放入高压锅，放入葱段，姜片，放入 20g 料酒，上汽压 20 分钟","取出牛肉后，切 5cm 大块，挑出姜，汤盛到一个大碗里一会炖煮用","倒油，油四到五成热以后下花椒八角香叶，出香味之后糊之前挑出不用","下入牛肉，葱姜，炒香，炒多久都无所谓，看着有点要糊可以舀 10ml 汤，此下同理","炒香后加入生抽 15ml，料酒 15ml，胡椒粉，5-10g 番茄膏番茄酱或一个番茄罐头，加入洋葱炒至透明","（可选）可以加一点点盐使洋葱出水不容易糊，不要加太多，后面再调味","加入西红柿炒至西红柿化开软烂，倒入剩下的汤","炖煮","中火开锅后，全程小火","出锅前 30-40 分钟 加土豆并调味","依据个人口味边尝边加糖盐，合适为止","筷子戳牛肉软烂后出锅！"]]],["炖煮时保证汤加入的时候是温热的","炖煮时不要扣盖否则土豆会烂","炖煮时时不时翻动避免糊底","砂锅炖煮会更好吃，可以在炒锅里炒完倒到煮锅里炖，如果用砂锅开锅之前不要用大火避免裂开","酱油总量不要太多，汤汁浓缩的时候会变咸，稀的时候稍微淡点没事，炖煮时候觉得不够也可以再加酱油","不要用鸡精味精，会抢夺牛肉的鲜味"]],["9265b91883","鸭肉与啤酒同炖，汤汁浓郁，肉质鲜香软烂，还带有一股淡淡的啤酒清香，是一道风味独特的家常菜。鸭肉本身滋补，富含蛋白质、B 族维生素和多种矿物质，搭配啤酒炖煮后更易入味。这道菜步骤虽稍多，但操作并不复杂，一般初学者只需 大约 1 小时即可完成。",[["必备","鸭肉","f",0],["必备","啤酒","f",0],["必备","32 厘米以上的炒锅一个(锅太小难炒","f",0],["必备","青椒","f",0],["必备","红椒","f",0],["必备","大蒜","f",0],["必备","生姜","f",0],["必备","小米椒","f",0],["必备","蒜苗","f",0],["必备","大葱","f",0],["必备","草果","f",0],["必备","桂皮","f",0],["必备","八角","f",0],["必备","香叶","f",0],["必备","干辣椒","f",0]],[["参考用量",[["鸭肉（半只,1 kg,让市场老板剁成小块）","","f"],["啤酒","1000 ml （可以买 500 ml 的罐装啤酒两瓶）","f"],["青椒","2 条，红椒 1 条 （ 长度 10 厘米到 15 厘米 之间都可以）（切段 或者切片都可以， 2 厘米一段）","f"]],[]],["辅料",[["大蒜","4 颗 ,拍散备用","f"],["生姜","3 厘米长，拍散备用","f"],["小米辣","3 颗，切两段即可(不吃辣的可以不用","f"],["蒜苗","2 根 切段备用","f"],["大葱","2 根 1 根切段,1 根备用","f"]],[]],["香料",[["草果","两颗，拍散去仔备用","f"],["桂皮","4 厘米一小片","f"],["八角","3 颗","f"],["香叶","3 片","f"],["干辣椒","6 条 (不吃辣可以不用","f"]],[]]],[["鸭肉焯水以去腥去血水",["鸭肉清洗一遍放进锅中","加清水淹没鸭肉","加 20 ml 料酒","加备用的 1 根 大葱","加生姜 ,拍散的 2 厘米","开火烧滚","捞出浮沫","鸭肉捞出，清水洗干净备用"]],["开始煮",["锅清洗干净烧热，加 60ml 的花生油","油温到 60 度的时候，加一把花椒（ 30 颗）","加鸭肉翻炒 4 分钟","2 分钟后加入所有的香料","3 分钟的时候加入所有的料头（生姜，大蒜，小米辣）","加入 1000 ml 的啤酒","烧鸭肉 30 分钟","10 分钟的时候加 盐 （3 克） 生抽( 10 ml ) 老抽( 5 ml)","20 分钟 加入所有的辅料 （青椒和红椒段）","29 分钟加入 蒜苗段 和 大葱段","翻炒 1 分钟","出锅"]]],["操作时，需要注意观察沸腾的水位线，如发现低于 2/3 的食材应加热水或者加啤酒。","厨师长：用土灶烧“乡村啤酒鸭”，味道安逸得不摆了"]],["e09437f35f","香干芹菜炒肉是一道家常小炒，豆干柔韧、芹菜爽脆、猪肉嫩滑，咸鲜微辣。芹菜富含膳食纤维，豆干和猪肉提供优质植物蛋白与动物蛋白。做法简单，对新手友好，从备料到出锅大约只需 30 分钟。",[["必备","豆干","f",0],["必备","香芹/芹菜","f",0],["必备","猪肉","f",0],["必备","大蒜","f",0],["必备","辣椒：青椒或者红椒都可以","f",0],["必备","花椒：可选","f",1],["必备","盐","s",0],["必备","鸡精：可选","f",1],["必备","老抽","s",0],["必备","蚝油","s",0],["必备","食用油","s",0]],[["参考用量",[["豆干：150g","","f"],["香芹：4 根","","f"],["猪肉：200g","","f"],["蒜头：2 瓣","","f"],["辣椒：4 个","","f"],["花椒：6 粒（不喜欢可以不放，或者放花椒水）","","f"],["盐：5g","","f"],["鸡精：3g","","f"],["老抽：8ml","","f"],["蚝油：5ml","","f"],["食用油：10-15ml","","f"]],["注意，此数值大约是 2 个人的量。","每份："]]],[["制作步骤",["芹菜去叶切段、切成不超过 4cm 的条状，备用","香干切条，宽约小拇指，备用","蒜头切片或者剁成蒜泥都行，备用","辣椒切圈或者斜切成条都行，备用","热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","放入花椒、大蒜爆香（可以吃姜的也可以额外放入一些姜片/姜丝）","加入猪肉炒至变色，再加入 8ml 老抽上色翻炒均匀（有豆瓣酱的，可以放入 3ml 豆瓣酱一起翻炒）","加入香干翻炒均匀（大约 2 分钟）","加入辣椒翻炒均匀（大约 1-2 分钟）","加入芹菜，放入 5g 盐翻炒 1 分钟","加入 3g 鸡精、5ml 蚝油翻炒均匀，即可出锅"]]],["如果没有买到香芹，或者用的芹菜比较粗，可以考虑焯水，放入滚水中 1 分钟捞出，冷水冲洗（保持爽脆）","如果买到的豆干比较硬、紧实，也可以切条后再焯水","香干芹菜炒肉教程"]],["8656e6816f","香干肉丝是一道咸香下饭的家常小炒，肉丝嫩滑，香干柔韧，青椒爽脆。富含动物性与植物性双重蛋白质，搭配青椒补充维生素。难度适中，新手稍加练习即可掌握，预计制作时长约 30 分钟。",[["必备","猪里脊（可以买超市切好且称重好的肉丝）","f",0],["必备","香干","f",0],["必备","盐","s",0],["必备","生抽","s",0],["必备","淀粉","s",0],["必备","大蒜","f",0],["必备","青椒","f",0],["必备","鸡精","s",0]],[["参考用量",[["香干","份数 75g","f"],["青椒的数量","份数 5 个","f"],["肉量","份数 100g","f"],["盐量","份数 3g","f"],["生抽","份数 5ml","s"],["淀粉","份数 5g","s"],["大蒜","份数 5g（大约 3 个蒜瓣）","f"],["鸡精","2g","s"]],["每次制作前需要确定计划做几份。一份正好够 1 个人食用","总量：","使用上述条件，计算出计划使用的原材料比例。"]]],[["准备工作",["肉丝（没有肉丝，自己切）用生抽(3ml)，生粉混合均匀待用。","将青椒洗净，再用滚刀手法切好备用。","大蒜横切成片，香干切丝。","淀粉与水(10ml)混合，搅拌均匀。"]],["起锅",["干净锅 15ml 油，不用等油热就倒入肉丝慢慢划散，肉丝熟了，立马捞出，留油到锅里。","将蒜片和香干放入锅中，加入 2ml 生抽，翻炒均匀。","2-3 分钟，看火大小，将青椒丝放入锅中混合，翻炒。","1 分钟后，放入肉丝混合。","倒入淀粉与水的混合物勾芡，加入盐 3g，鸡精 2g，翻炒 2-3 分钟出锅。","成品。","注意，不同的锅具或者灶台，会影响翻炒的时间，建议，不确定是否熟了，可以试吃下。"]]],["辣椒选择青椒，螺丝椒为最优解，喜欢辣的可以加入小米椒切细碎，同青椒一起加入！"]],["9860fd3a56","香菇滑鸡是一道以鸡腿肉和香菇为主料的家常菜，鸡腿肉经过煸炒和焖煮后口感滑嫩，搭配香菇独特的菌香，汤汁浓郁鲜美，属于老少皆宜的粤式风味。鸡肉富含优质蛋白质和多种氨基酸，香菇含有香菇多糖和膳食纤维，有助于增强免疫力和促进消化。这道菜需要一些刀工和火候控制，对新手有一定挑战，整体制作约需 1 小时。",[["必备","大鸡腿","f",0],["必备","干香菇","f",0],["必备","姜","f",0],["必备","葱","f",0],["必备","蒜","f",0]],[["参考用量",[["大鸡腿","2 个","f"],["干香菇","5 粒","f"],["姜","2 片","f"],["葱","2 颗","f"],["蒜","2 瓣","f"],["温水(30-40 ℃)","150ml","f"],["料酒","15ml","s"],["生抽","30ml","s"],["盐","1.5g","s"],["老抽","15ml","s"],["糖","15ml","s"],["香油","5ml","s"]],["每份："]]],[["制作步骤",["温水泡发干香菇","姜切小块，葱切段，蒜对半切小粒","鸡腿去骨（不去骨也可，只是略影响程序员吃饭的效率而已），切成小块","泡发的香菇一分为四，香菇水留着备用","鸡腿肉焯水 1 分钟，去除血沫和杂质","鸡腿肉中加料酒 15ml、生抽 15ml、盐 1.5g、老抽 15ml，抓匀","油温 3 成，下入鸡腿肉煸炒，等鸡腿肉金黄后盛出备用","锅留底油，下入葱、姜、蒜炒香，香菇入锅，大火翻匀","等待 20 秒会有香菇香味从锅中飘出，此时下入煸炒过的鸡腿肉，下入香菇水（全部，本程序员认为的灵魂操作）、糖 15ml、生抽 30ml","转中火不盖盖，咕嘟 2 分钟收浓汤汁，淋入香油 5ml，撒上葱花后即可关火、装盘"]]],["鸡腿去骨操作较复杂，本人经验可供参考：","鸡腿于案板摆正，骨头正对程序员，从头部划一刀至最底部，刀口要深，确保有碰到骨头","用手扒拉肉到两边","用刀尖隔开骨头上沾着的肉","鸡腿翻面，刀紧贴骨头插入，挑断骨头与肉的连接点","用刀尖切断最后的粘连即可"]],["f9ecdd44f4","香煎五花肉是一道家常风味的快手荤菜，五花肉片煎得焦香微脆、肥而不腻，搭配脆爽的生菜叶和咸鲜豆瓣酱，入口酱香浓郁又解腻。猪肉富含优质蛋白质和脂肪，能快速补充能量，生菜则提供膳食纤维和维生素，营养更均衡。这道菜适合有一定下厨基础的朋友，新手只要注意火候和防溅油也能轻松上手，从备料到出锅大约半小时即可享用。",[["必备","五花肉条（推荐长宽高为 20cm\\6cm\\5cm）","f",0],["必备","生菜","f",0],["必备","酱油，盐，味精，料酒，姜蒜，油，豆瓣酱","s",0]],[["参考用量",[["五花肉条（推荐长宽高为","20cm\\6cm\\5cm）","f"],["生菜一朵","","f"],["食用油","5ml","s"]],["每次制作前需要确定计划做几份。一份正好够 1 个人吃。","每份："]]],[["制作步骤",["将五花肉条沿长边切片，每片厚 1mm-1.5mm，备用","将切好的五花肉放置碗中，依次加入 8g 酱油，1g 盐，1g 味精，10g 料酒，两片姜，两朵拍扁的大蒜腌制 10 分钟","将生菜叶直接用手扒下来，洗干净，备用","热锅，倒入 5ml 食用油。油轻微冒烟后下入五花肉。单面煎制焦黄色后翻面，另一边同理。","五花肉出锅后，装盘。","将豆瓣酱抹到菜叶上，卷着五花肉即可食用"]]],["操作时，小心被溅出的油烫到"]],["55a92f5a98","香辣浓郁、口感 Q 弹，是一道常见的家常下饭菜。鸡爪富含胶原蛋白，有助滋润皮肤、强健筋骨。制作需要先去趾甲，若用整只鸡爪还需去骨，对新手略有挑战，但耐心按步骤操作也能成功。从焯水到小火慢煮再翻炒入味，全程约需 45 分钟。",[["必备","鸡爪","f",0],["必备","葱","f",0],["必备","姜","f",0],["必备","料酒","s",0],["必备","香叶","f",0],["必备","八角","f",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","蒜","f",0],["必备","小米椒","f",0],["必备","辣椒面（可选）","f",1],["必备","蚝油","s",0],["必备","五香粉","s",0],["必备","盐","s",0],["必备","鸡精","s",0]],[["参考用量",[["一斤鸡爪","","f"],["香叶","3 片","f"],["八角三个","","f"],["小米椒","6 个","f"],["姜末","10g","f"],["蒜末","10g","f"],["小葱","2 根","f"],["蚝油","3g","s"]],[]]],[["制作步骤",["给鸡爪剪去指甲。如果买的鸡爪只有脚掌部分，对半切开即可。 如果是整只鸡爪，需要去骨。清水洗干净。","鸡爪冷水下锅，葱姜料酒焯水，水开，撇去浮沫。","加入香叶、八角、生抽、老抽，盖盖小火慢煮三十分钟。","捞出鸡爪，留一碗鸡汤备用。","起锅烧油，用小火炒香姜末、蒜末、小米椒，能吃辣再放点辣椒面。加入生抽、老抽、蚝油、五香粉、盐，炒出酱香味。","放入鸡爪，放一点盐调味，翻炒一两分钟，再倒入鸡汤，边炒边搅动。","放入鸡精提鲜，撒入葱段搅拌均匀即可出锅。","注：如果需要加入配菜，请在放入鸡爪之前，底料炒香之后执行。"]]],[]],["7bd7afbaff","湖南两祁地区传统特色菜，鸭肉煸炒后裹上混合米粉蒸制，口感软糯，咸香入味，回味悠长。鸭肉富含优质蛋白质和 B 族维生素，搭配米粉提供能量，营养均衡。制作需先煸炒再高压蒸制，稍有难度，适合有一定烹饪基础的朋友。从备料到出锅大约需要 1 小时，若选用老鸭需延长蒸制时间。",[["必备","鸭子（必须新鲜现杀的）","f",0],["必备","糯米粉","f",0],["必备","粘米粉","f",0],["必备","蒸肉粉","f",0],["必备","细辣椒粉（吃辣则加）","s",0],["必备","白胡椒粉","s",0],["必备","五花肉（可加可不加）","f",0],["必备","姜蒜","f",0],["必备","盐","s",0],["必备","食用油","s",0],["必备","开水","f",0]],[["参考用量",[["鸭子：1000g","","f"],["糯米粉：100g","","f"],["粘米粉:","300g","f"],["蒸肉粉:","50g","f"],["细辣椒粉:","50g","f"],["白胡椒粉：5g","","f"],["五花肉：50g","","f"],["姜蒜：20g","","f"],["盐：10g","","f"],["食用油：10g","","f"],["开水：100g","","f"]],["正常 3-4 人吃"]]],[["制作步骤",["将糯米粉、粘米粉、蒸肉粉、细辣椒粉、5 克盐、白胡椒粉倒一起搅匀","鸭子让热心摊主剁成蒸煮块，姜切片，蒜子剥皮，五花肉切片即可","热锅凉油煸炒五花肉出油，再加食用油烧热，下入鸭子煸炒","鸭子煸炒到表皮焦变色，下入姜蒜和盐继续煸炒香味","关小火倒入米粉翻炒，鸭肉均匀裹满米粉子，加入开水，少量多次的加，边加边翻炒","翻炒鸭肉和米粉有湿感，铲出入碗中，高压锅放水蒸 20-25 分钟","出锅前撒点葱花即可享用了"]]],["这是一道家乡菜。","鸭子品种不限，这里买的是水鸭，价格 24。","蒸 20 分钟，是老鸭的话，蒸一个小时以上。","第一步中粘米粉是主要的粉子，糯米粉是加软糯口感，蒸肉粉是加五香味道，辣椒粉和胡椒粉是加复合香味。","下面贴出重要步骤以供参考："]],["36c7ccdb27","这道湘味小炒以大火爆炒逼出牛肉的嫩滑与椒香，口感鲜辣劲爽、芹菜脆嫩，极具湖南风味。牛里脊提供优质蛋白和易吸收的铁质，搭配芹菜增添膳食纤维，营养均衡。备料与烹饪步骤简单明了，全程旺火快炒，对新手十分友好，从切配到出锅大约一小时即可完成。",[["必备","牛里脊","f",0],["必备","芹菜","f",0],["必备","小米椒","f",0],["必备","野山椒","f",0],["必备","香菜","f",0]],[["参考用量",[["牛里脊","400g","f"],["芹菜","200g","f"],["小米椒","30g","f"],["野山椒","30g","f"],["香菜","30g","f"],["食用油","15ml","s"],["酱油","6ml","s"]],["每份："]]],[["制作步骤",["牛里脊切成不超过 3cm 宽，3mm 厚的薄片，倒入 6ml 酱油，用手抓匀备用","芹菜切成不超过 5cm 的小段，备用","小米椒切成丝状，备用","野山椒切成颗粒，备用","香菜切成成不超过 3cm 的小段，备用","热锅，锅内放入 15ml 食用油，大火等待 30 秒让油温升高","放入小米椒和野山椒爆香","放入牛里脊和芹菜，然后大火翻炒 1 分钟","关火，撒上香菜，盛盘"]]],["操作时，全程需要开大火"]],["ad866880c0","这道鸡肝小炒蒜香浓郁，口感嫩滑带点孜然的焦香，是一道家常风味小炒。鸡肝富含铁、维生素 A 和优质蛋白，有助补血明目。制作时需掌握焯水去腥的技巧，对新手略有挑战，从备料到出锅大约需要四十分钟。",[["必备","生鸡肝","f",0],["必备","蒜苗（蒜苗指的是：大蒜幼苗发育到一定时期的青苗。有些地方叫做青蒜，特别说明一下。）","f",0],["必备","大葱、姜、料酒","s",0],["必备","食用盐、鸡精（味精）、五香粉（十三香）、胡椒粉","s",0],["必备","烧烤料或孜然粉（可选）","s",1],["必备","芝麻（可选）","f",1],["必备","食用油","s",0]],[["参考用量",[["生鸡肝","5 个（约 800g）","f"],["蒜苗（约","200g，喜欢吃的可以多放）","f"],["大葱","150g（分成两份，一份切段 100g，一份切片 50g）","f"],["姜","120g（分成两份，一份切片 70g，一份切丁 50g）","f"],["料酒","30ml","s"],["食用盐","5g","s"],["鸡精","5g（也可以是味精）","s"],["五香粉","5g（十三香）","s"],["胡椒粉","5g","s"],["烧烤料或孜然粉","10g（可选）","s"],["芝麻","5g （可选）","f"],["食用油","30ml","s"]],["每次制作前需要确定计划做几份。","一份正好够 2 个人吃。","每份："]]],[["制作步骤",["鸡肝清洗，备用","蒜苗清洗，切段，备用","大葱清洗，取 100g 切段，取 50g 切片，备用","姜清晰，取 70g 切片， 取 50g 切丁，备用","第一步：焯水","清洗后的鸡肝放入锅内，加入凉水淹没鸡肝，并放入 100g 切段的大葱、70g 切片的姜和 30ml 料酒","开大火，待水沸腾调至中火并撇去浮沫后等待5-10分钟","关火，捞出过凉水并清洗干净","清洗干净后切片，备用","第二步：炒制","开中火。锅内加入 30ml 食用油，等待 10 秒使油升温","加入 50g 切片的大葱和 50g 切丁的姜，翻炒爆香","爆香后加入切片的鸡肝，翻炒至微微发黄","加入蒜苗，翻炒 30 秒，断生后调至为小火","加入调味料","食用盐 5g","鸡精（味精） 5g","五香粉（十三香） 5g","胡椒粉 5g","烧烤料或 10g （可选）","调至为大火，快速翻炒 30 秒防止糊锅，关火","盛出盘内，可以撒入 5g 芝麻作为装饰，如果不喜欢或者没有则可以不用添加。"]]],["焯水时，需要注意观察沸腾的水位线，不要让水溢出避免发生危险。","焯完水的鸡肝建议用凉水冲洗，更推荐冰水，可以让口感更好。"]],["c12ff022a6","小炒肉是一道香辣下饭的经典湘式家常菜，五花肉片焦香不腻，搭配鲜辣椒与豆豉、豆瓣酱炒出浓郁酱香。富含优质蛋白质和脂肪，辣椒能提供丰富的维生素 C，有助开胃暖身。制作难度中等，适合有一定基础的新手尝试，需注意肉片腌制和火候把控。从备料到出锅大约需要 1 小时，其中腌制 30 分钟，炒制过程约 15 分钟。",[["必备","五花肉","f",0],["必备","朝天椒","f",0],["必备","小米椒","f",0],["必备","豆豉","f",0],["必备","豆瓣酱","s",0],["必备","老抽","s",0],["必备","淀粉","s",0],["必备","盐","s",0],["必备","葱","f",0],["必备","蒜","f",0]],[["参考用量",[["五花肉","500g","f"],["朝天椒","4 条","f"],["小米椒","4 颗","f"],["豆豉","10g，根据个人口味加减 ±5g","f"],["豆瓣酱","10g，根据个人口味加减 ±5g","s"],["老抽","10ml","s"],["淀粉","10g","s"],["盐","1-2g","s"],["葱","0.5-1 根","f"],["蒜","2 瓣","f"],["食用油","15ml","s"]],["每份："]]],[["制作步骤",["五花肉切片","把肉放入器皿内，加入淀粉、老抽、盐搅拌腌制半小时","葱切段","小米椒、朝天椒斜刀切好","热锅、倒油","油热后加入五花肉煸炒。炒至变色后盛出来","向锅中加蒜，煸出香味，加入豆豉，翻炒均匀","加入豆瓣酱翻炒均匀","加入炒好的五花肉继续的翻炒均匀","加入小米椒、朝天椒、葱段翻炒 40 秒","出锅。"]]],[]],["b3ccc8b046","小米辣炒肉香辣过瘾，是一道典型的西南风味下饭菜，猪肉的鲜嫩搭配小米辣的爽辣，令人食欲大开。猪肉富含蛋白质和脂肪，辣椒提供丰富的维生素 C，能够促进食欲。虽然需要掌握爆香和翻炒的火候，但步骤清晰，新手也能轻松上手，预计制作时长约 25 分钟。注意，这道菜辣味突出，不建议清淡饮食者尝试。",[["必备","小米辣","f",0],["必备","花生油","s",0],["必备","五花肉/瘦肉","f",0],["必备","盐","s",0],["必备","生抽","s",0],["必备","蚝油","s",0],["必备","大蒜","f",0],["必备","姜","f",0],["必备","豆瓣酱","s",0],["必备","鸡精","s",0],["必备","白糖","s",0]],[["参考用量",[["小米椒","20 个，根据个人口味加减","f"],["花生油","20ml","s"],["五花肉/瘦肉","200g","f"],["盐","1-2g","s"],["生抽","10ml","s"],["蚝油","10ml","s"],["姜蒜","50g","f"],["豆瓣酱","10g，根据个人口味加减","s"],["鸡精","10g","s"],["白糖","5g","s"]],["每份："]]],[["制作步骤",["将小米辣洗净，斜刀切大一点","肉的话，想切丝切丝，想切片切片，倒入调料（生抽、蚝油、盐）腌制 5 分钟","热锅倒油，先把肉炒好盛起","姜蒜爆香，倒入豆瓣酱翻炒，到入切好的小米辣，再倒入瘦肉，翻炒一下，放点生抽、鸡精、盐、糖翻炒"]]],["调料可以根据自己的喜好放，也可以加老抽，老抽更香！"]],["70b60517a3","小酥肉外酥里嫩，咸香中带着花椒的微麻，是川渝地区家家户户都会做的家常炸物。猪肉富含蛋白质和脂肪，油炸后热量较高，适合偶尔解馋。这道菜步骤稍多，需掌握初炸定型与复炸上色的火候，对新手略有挑战，预计从头到尾约 1 小时 30 分钟完成。",[["必备","去皮猪肉（根据喜好选择肥瘦）","f",0],["必备","植物油","s",0],["必备","老姜","f",0],["必备","小葱","f",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","十三香","s",0],["必备","胡椒粉","s",0],["必备","味精","s",0],["必备","鸡精","s",0],["必备","花椒碎","f",0],["必备","花椒粒","f",0],["必备","生抽","s",0],["必备","鸡蛋","f",0],["必备","面粉","f",0],["必备","红薯淀粉","s",0]],[["主料",[["猪肉","500 克","f"]],[]],["辅料",[["鸡蛋","2 个","f"],["面粉","30 克","f"],["红薯淀粉","120 克","s"]],[]],["葱姜水",[["老姜","20 克","f"],["小葱","15 克","f"],["料酒","15 克","s"],["清水","80 克","f"]],[]],["腌制调料",[["盐","4 克","s"],["十三香","2 克","s"],["胡椒粉","3 克","s"],["味精","5 克","s"],["鸡精","5 克","s"],["花椒碎","3 克","f"],["花椒粒","3 克","f"],["生抽","8 克","s"]],[]]],[["葱姜水制作",["老姜切丝，小葱不用切。","根据计算公式倒入料酒、清水。","用手捏揉 5 分钟，使姜葱的味道充分溶解在水中。"]],["猪肉处理",["将猪肉去皮洗净","切成长度 810 厘米，厚度 1.5 厘米的肉条。","根据上面的计算公式加入盐，十三香、胡椒粉、味精、鸡精、花椒碎、花椒粒、生抽。","倒入前面制作好的葱姜水","抓匀并且充分揉制 10 分钟，直至肉吸收所有水分并且变得粘手。","封上保鲜膜放冷藏室静置 30 分钟。"]],["猪肉裹粉",["将面粉、红薯粉倒入腌制好的肉中，加入鸡蛋清。","充分揉制 15 分钟。"]],["初炸定形状",["锅中倒入植物油，根据锅大小控制油量，油面高度 3 厘米以上。","大火将温加热至 150° 后，转小火保持温度。","将裹好粉的肉条用筷子夹入油锅中，捋成自己喜欢的形状，炸 35 分钟定型。目测颜色微黄，用锅铲翻动感受倒略微有些硬了就可以。具体时间受肉块大小、油温、裹粉程度影响。","捞出沥油。","tips: 如果对时间没把握可以稍微多炸一下，否则肉会带一点生味。 没有经验可以一条一条的下锅，防止粘连。"]],["复炸出成品",["将油温升至 180° 放入初炸好的肉条，炸至金黄色即可捞出。"]]],["裹粉一定要把红薯粉揉散，不要有干的颗粒裹在里面，否则会炸！！！","如果肉太多吃不完，可以只炸一遍然后放冰箱。后面再吃的时候拿出来复炸，口感基本没影响。"]],["02886c005a","新疆大盘鸡是一道风味浓郁、色彩鲜艳的新疆家常菜，鸡肉鲜嫩不柴，土豆软糯吸汁，麻辣中带着微甜回甘。富含优质蛋白质和碳水化合物，搭配彩椒还能补充维生素 C。制作过程需要炒糖色和掌握收汁火候，对新手有一定挑战，但跟随步骤细心操作并不难，整体大约 1 小时可以完成。",[["必备","花椒，香叶，香果，干线椒，大蒜，大葱","f",0],["必备","油，盐，生抽，蚝油，料酒（可拿啤酒），白糖","s",0],["必备","鸡肉（鸡腿肉最好），土豆，菜椒和甜椒（可以不用，加上配色好看）","f",0]],[["参考用量",[["两个火枪腿的鸡肉（这大约是","1kg ）","f"],["土豆","2 个适中大小：750g","f"],["大葱","100g","f"],["菜椒甜椒各一个，各","50g","f"],["白糖","20g","s"],["干线椒","5 个","f"],["大蒜","4 瓣","f"],["油","50g","s"]],["2 人食用"]]],[["制作步骤",["肉先剁好，块状，用清水+盐浸泡 5 分钟，去除血水，去腥，然后空干水","葱蒜辣椒土豆等洗干净，土豆削皮","葱白切长段，长度 4cm 一段，菜椒和线椒切块状","土豆切成滚刀土豆，即切一刀动滚动一下，一块土豆大概有 4cm4cm 大小即可","炒糖色：先将油加入锅中，然后将白砂糖放入，用锅铲来回搅拌，将糖炒化，然后炒出焦黄色，此时将空干水的鸡肉倒入锅中翻炒，进行上色","放入花椒，香叶，香果，干线椒等进行翻炒","放入 5g 盐，生抽 7ml，蚝油 10g ，料酒 100g，倒入 1 升清水，料酒可以用啤酒代替","调至中火，将水烧开，调制中小火慢炖入味","当水收至鸡肉即将露出时，将土豆放在锅表面：注意不要翻动土豆，就盖在表面，不然翻到下面容易粘锅，继续盖锅盖炖，炖一会后将大葱，菜椒和甜椒放入，继续炖。","炖到汁收的差不多时可以进行翻面，将土豆与汤汁相吸，最后关火盛出。","另：此做法可以吃面，买粗面剂子，将粗面剂子压扁，然后用手拉成宽面，一定要是宽面，下好后可以放入到大盘鸡中，与汤汁搅拌味道极佳！"]]],[]],["849f53a4df",".jpg) .jpg) 血浆鸭是一道湖南武冈传统名菜，鸭肉香酥脆嫩，浸透醋血后连姜和辣椒都变得甜净不辣。鸭肉与鸭血提供优质蛋白和铁质，适合补血养身。制作步骤较多，需要留意火候和翻炒，但跟着步骤操作，初学者也能在 大约 2 小时完成。",[["必备","鲜仔鸭肉","f",0],["必备","鲜鸭血（宰杀鸭子时加醋接鸭血，用筷子顺时针搅拌防凝固）","f",0],["必备","姜","f",0],["必备","蒜仔","f",0],["必备","葱","f",0],["必备","辣椒","f",0],["必备","酒（或者白酒、啤酒、米酒皆可）","f",0],["必备","生抽","s",0],["必备","料酒","s",0],["必备","盐","s",0],["必备","鸡精","s",0]],[["参考用量",[["鲜仔鸭肉","2000g","f"],["鲜鸭血","250ml","f"],["姜","6 片 （根据个人吃辣喜好程度可多放 1-3 片姜）","f"],["蒜仔","6 瓣","f"],["香葱","2 根，切好备用","f"],["辣椒","1000g（根据个人吃辣喜好程度可选青椒，线椒，美人椒等，喜欢吃辣可增加 5-8 个小米辣或朝天椒，切好备用）","f"]],["每份（建议 2-4 人份）："]],["酒（任选其一）：",[["高度白酒","50ml + 水 150ml","f"],["啤酒","200ml","f"],["米酒","200ml","f"],["生抽","10ml","s"],["料酒","30ml","s"],["盐","8g","s"],["鸡精","5g","s"]],[]]],[["制作步骤",["鲜仔鸭肉切成约 3cm 小块，加料酒、姜片，去除血水。","炒锅烧热，放入约 100ml 食用油，大火待油烧开，放入腌制好的鲜鸭肉，不断翻炒。","待鸭肉完全变色（肉眼可见泛白），放入酒，再加入 200ml 开水，刚好淹没鸭肉即可，盖上锅盖中火煮 15 分钟。","水开之后，打开锅盖放入姜蒜，翻炒一遍，盖上锅盖持续加热 10 分钟。","打开锅盖放入辣椒，不断翻炒，待至肉眼可见辣椒炒软，放入鲜鸭血，此时需要不断翻炒，确保每块鸭肉和每片辣椒都有鸭血的浸润（此乃血浆鸭的精髓）。","翻炒至肉眼可见鸭血均为黑色，加入盐，鸡精，香葱，（喜欢食用山胡椒油的朋友也可以在此时放入 3-6 滴山胡椒油）再次翻炒一到二次即可。","出锅盛盘，上桌食用。"]]],["操作时，需要注意观察水位线，调整炉火大小，以防水烧干粘锅。","放入鲜鸭血时，需要不断翻炒搅拌，防止鸭血抱团凝固成块。"]],["4e72080f3b","羊排焖面是一道肉香浓郁、面条筋道的北方家常硬菜，羊排软烂，宽面吸足汤汁，每一口都满足。这道菜有肉有面有菜，一顿饭就能补齐人体所需的蛋白质、碳水和脂肪，营养全面。制作时需要先炖羊排再和面焖面，步骤稍多，更适合有一定下厨经验的朋友尝试，预计全程大约花费一个半小时。",[["必备","带皮羊排肉","f",0],["必备","青椒","f",0],["必备","甜椒","f",0],["必备","青椒","f",0],["必备","大葱","f",0],["必备","花椒","s",0],["必备","干辣椒","f",0],["必备","生姜","f",0],["必备","白砂糖","s",0],["必备","老抽","s",0]],[["参考用量",[["带皮羊排","500g","f"],["青椒，甜椒 各","2 个","f"]],["1 人份 2 顿 = 2 人份"]]],[["制作步骤",["羊肉冷水下锅焯水，水开了之后把血沫撇掉，捞出羊肉。","切好生姜（ 4 片)，放入干辣椒与花椒在碗里备用。","在炒锅加入油。（多一点也没关系）","油热之后，放入白砂糖，给羊肉炒出焦糖色。","羊肉水份炒干之后，放入盐、老抽，以及备好的调味料。","加入清水没过羊肉，大火煮沸之后，让其继续煮 10 分钟，之后小火炖煮 30 分钟。","在此期间，可以和面。和面的量以及操作方法在附加内容里讲解 （注 1）。","放入青椒，甜椒，大葱，以及面皮进行翻炒。","翻炒均匀之后，即可出锅。","注 1：可以用超市的面条代替，但是尽量选择宽面。"]]],["(和面小指南 之 材料）","中筋面粉 300 g","盐 3 g","水 180 ml","(和面小指南 之 操作）","先把材料混合均匀，加水边和边搅拌，然后把面团和到光滑","醒面（ 10 分钟）","再次和面到光滑","醒面（ 5 分钟）","把面团揉成条，切成 6 到 8 个小剂子","抹上油，等待 5 分钟","把面团剂子擀成面皮","放入锅中焖煮 4 分钟（一片一片操作）"]],["bf65ef4516","这是一道家常风味小炒，咸中带甜，酱香浓郁，洋葱炒软后滋味温和，搭配嫩滑猪肉片非常下饭。猪肉提供优质蛋白质和 B 族维生素，洋葱含膳食纤维和多种抗氧化物，开胃助消化。操作简单，新手也能轻松上手，预计制作时长仅需 15 分钟。",[["必备","洋葱","f",0],["必备","猪肉片","f",0],["必备","蕃茄酱","s",0],["必备","麻油","s",0]],[["参考用量",[["洋葱","一颗 （是主角，喜欢吃洋葱可以多半颗～一颗）","f"],["猪肉 (250g)","","f"],["蒜头 （3 瓣）","","f"],["食用油 (15ml)","","s"],["黑胡椒 (1.25g)","","s"],["酱油 (30ml)","","s"],["糖 (15g)","","s"],["麻油 (5ml)","","s"],["番茄酱 (15ml)","","s"],["料酒 (15ml)","","s"]],["每份：","食材","调味料","备注：可以考虑购买茶匙，大匙来精准确定用料的量。"]]],[["制作步骤",["洋葱切片，猪肉，蒜头拍碎，以及混合上述调味料备用","炒锅内倒入 1 大匙食用油（等待 10 秒让油温升高），倒入猪肉","炒至变色后下蒜头炒香盛起备用","原锅下洋葱翻炒 34 分钟后加入调味料炒匀","下刚盛起备用的猪肉翻炒至猪肉熟后","待猪肉熟后再翻炒 1、2 分钟即可起锅"]]],["猪肉可选猪肩肉片或是切好的肉丝看个人喜好","参考资料","爱料理"]],["5ec95efc35","意式烤鸡是一道带有地中海风味的家常烤箱菜。鸡腿肉经过蒜香橄榄油腌制，烤后外皮微焦、内里鲜嫩多汁，搭配柠檬汁和欧芹，口感清爽不腻。鸡肉富含优质蛋白质，橄榄油提供不饱和脂肪酸，营养均衡。制作难度适中，需要提前预热烤箱，新手跟着步骤也能顺利完成，从腌制到出炉总计约五十分钟。",[["必备","鸡腿肉","f",0],["必备","盐","s",0],["必备","黑胡椒","s",0],["必备","橄榄油","s",0],["必备","蒜","f",0],["必备","柠檬汁","f",0],["必备","欧芹","f",0]],[["参考用量",[["鸡腿肉用量通常来说为","1-2 个/人","f"],["盐用量为","2 g/人","f"],["黑胡椒用量为","0.5 g/人","f"],["橄榄油用量为","5 ml/人","f"],["蒜用量为","1 瓣/人","f"],["柠檬汁用量为","5ml/人","f"],["欧芹用量为","1 根/人","f"]],["使用上述条件，计算出计划使用的原材料比例。"]]],[["鸡肉的预处理",["鸡腿肉涂上盐、黑胡椒、橄榄油和蒜末","放入预热至 180 度的烤箱中，烤 30-40 分钟或至熟"]],["佐料的准备",["欧芹切成碎末备用","柠檬挤出汁备用"]],["烤制",["烤好的鸡肉取出，淋上柠檬汁","撒上欧芹碎即可"]]],["烤制时可以将鸡肉淋上蜂蜜或其他烤肉酱提升口感","烤箱预热至 180 度，烤制时间根据鸡肉的大小和厚度而定，需确保鸡肉熟透","鸡肉必须全熟才能吃，吃未全熟的鸡肉可能会导致食物中毒和感染细菌，如沙门氏菌和福氏杆菌等。"]],["0979bc8518","鱼香茄子是一道经典的川味家常菜，酸甜微辣，茄子软糯吸汁，非常下饭。茄子富含膳食纤维和多种维生素，搭配肉末能补充蛋白质。制作难度中等，需要掌握炸茄子和调味技巧，新手稍加练习也能成功。从备料到出锅大约需要 30 分钟。",[["必备","茄子","f",0],["必备","肉末","f",0],["必备","盐","s",0],["必备","糖","s",0],["必备","味精","s",0],["必备","生抽","s",0],["必备","老抽","s",0],["必备","醋","s",0],["必备","水淀粉","s",0],["必备","豆瓣酱","s",0]],[["参考用量",[["茄子","2 根","f"],["肉末","20g","f"],["盐","3-5g","s"],["糖","5-10g","s"],["味精","5g","s"],["生抽","10ml","s"],["老抽","5ml","s"],["醋","10ml","s"],["水淀粉","100ml","s"],["豆瓣酱","20-30g","s"],["小葱、姜、蒜、小米辣 （根据自己口味）","","f"]],["每次制作前需要确定计划做几份。一份正好够一个人吃。"]]],[["制作步骤",["将茄子切成条。","将肉切成肉沫，葱姜蒜切碎、小米椒切丁。","调鱼香汁：碗中放入盐、味精、糖、生抽、老抽、醋、水淀粉搅拌均匀。","锅中倒入 300ml 油，开小火（小火容易掌控），等油温七成热（小火大约 40 秒，有烟冒出）放入茄子炸两分钟，当茄子边缘微黄就捞出。多出的油可以盛出以后炒菜用。","锅中留 15-30ml 油，倒入肉沫炒至颜色变白就盛出来。","锅中倒入 15-30ml 油，放入豆瓣酱、葱白、姜、蒜炒香，然后倒入肉沫翻炒均匀。","加入 80-150ml 清水（水面预计茄子八成高度为准），倒入茄子、倒入料汁，爆炒入味收汁。最后放入葱翻炒均匀，就可以起锅了。"]]],["茄子看个人喜好，可以去皮，肉沫也可以多放一点。","参考: 鱼香茄子详细步骤"]],["38b5a18dce","鱼香肉丝是一道经典川菜，口味酸甜微辣，肉丝滑嫩，配以胡萝卜、青椒和木耳，口感丰富。富含蛋白质和多种维生素，荤素搭配，营养均衡。制作有一定难度，需要调好鱼香汁并掌握翻炒火候，新手建议严格按步骤操作。预计制作时长约 40 分钟（不含木耳泡发时间）。",[["必备","里脊肉 200g","f",0],["必备","胡萝卜 100g","f",0],["必备","青椒 100g","f",0],["必备","木耳（干） 5g","f",0],["必备","生抽 10ml","f",0],["必备","料酒 5ml","f",0],["必备","蛋清 1 个","f",0],["必备","淀粉 10g","f",0],["必备","醋 15ml","f",0],["必备","白糖 10g","f",0],["必备","盐 5g","f",0],["必备","姜 20g","f",0],["必备","葱 20g","f",0],["必备","蒜 2 瓣","f",0],["必备","豆瓣酱 15g","f",0]],[["参考用量",[],["注意，这道菜仅有足够 1-2 人食用的版本。"]]],[["制作腌料和香碗汁",["制作腌料：将下列原料混合：","生抽 5ml","料酒 5ml","淀粉 5g","水 20ml","蛋清 1 个","制作香汁：将下列原料混合：","生抽 5ml","醋 15ml","白糖 10 克","盐 1 克","淀粉 5g","水 20ml"]],["处理原料",["用腌料腌制里脊肉 15-30 分钟。注意将肉抓匀。","干木耳泡 4 个小时，洗净，切成小块。","青椒洗净，去蒂，切成丝。","胡萝卜洗净，切成丝，将胡萝卜丝焯水。","姜、蒜切沫。","葱切成 5mm 的小段。"]],["炒熟各种材料",["将锅烧热，加入 15ml 油。","向锅内倒入准备好的腌肉，快速滑散至变白，盛出备用。","将锅烧热，加入 5ml 油。","倒入全部葱、姜、蒜、豆瓣酱。","倒入全部胡萝卜，翻炒 20s 后，放入青椒和木耳，翻炒 2 分钟。","倒入炒过的肉。快速翻炒均匀。注意不要炒超过 20 秒。","倒入香汁。快速翻炒均匀。注意不要炒超过 15 秒。","关火，盛盘。"]]],[]],["55ce7b8cad","这是一道源自广东的传统煲仔菜，羊肉与腐竹在柱侯酱和腐乳的调和下，酱香浓郁，口感肥美而不腻口，暖身暖心，尤其适合寒冬食用。羊肉富含蛋白质和铁质，能温补气血，腐竹则提供优质植物蛋白，搭配起来营养均衡。虽然备料和炖煮步骤较多，但全程火候控制并不复杂，新手只需按部就班也能成功。预计从准备到出锅约需两个半小时。",[["必备","羊腩","f",0],["必备","腐竹","f",0],["必备","柱侯酱","s",0],["必备","腐乳","f",0],["必备","南乳","f",0],["必备","老抽","s",0],["必备","料酒","s",0],["必备","蚝油","s",0],["必备","清水","f",0],["必备","冰糖","s",0],["必备","葱段","f",0],["必备","姜片","f",0],["必备","香菇","f",0],["必备","洋葱或红葱头","f",0],["必备","蒜瓣","f",0],["必备","香叶","f",0],["必备","八角","f",0],["必备","桂皮","f",0],["必备","其余配菜例如马蹄、土豆或者萝卜可依据个人喜好自行添加","f",0]],[["参考用量",[["羊腩","500g","f"],["炸腐竹","30g-50g","f"],["柱侯酱","30g","s"],["腐乳","40g","f"],["南乳","35g","f"],["老抽","5ml","s"],["辣椒油","5ml","s"],["清水","500ml","f"],["冰糖","20g","s"],["砂糖","10g","s"],["小葱","5 根","f"],["姜片","6-8 片","f"],["香菇","7-8 个","f"],["洋葱","1 个或红葱头 4 - 5 个","f"],["蒜瓣","7-8 瓣","f"],["香叶","1 片","f"],["八角","4-5 个","f"],["桂皮","10g","f"]],["每份："]]],[["制作步骤",["准备工作: 香菇提前浸泡 2 - 3 小时至变软。腐竹提前浸泡 30 分钟至变软","准备酱汁 1: 南乳、柱侯酱、20g 腐乳、老抽放入同个小碗中搅拌均匀","准备酱汁 2: 20g 腐乳、砂糖、辣椒油放入同个小碗搅拌均匀","泡好的香菇去除根部","泡好的腐竹切成 5cm 的小段，挤干水分","洋葱去皮切丝。也可以用去皮红葱头进行替代，口味更佳。","小葱切成大约 5cm 的葱段","羊腩冷水下锅，放入 2 - 3 片姜片，倒入凉水，大火煮至水滚后关火","捞出羊腩，放入准备好的冷水盆中放凉，使其更有嚼劲","锅烧热后放入冷油，放入 4 - 5 片姜片、洋葱/红葱头、葱白段、7 - 8 瓣蒜瓣进行爆香","放入冷却好的羊腩，用筷子搅拌大约 2 - 5 分钟直至出现金黄色","放入调好的酱汁 1 ，翻炒大约 2 分钟至颜色均匀","倒入清水至刚好没过食材","放入香菇、冰糖、香叶、八角、桂皮","加盖转小火炖 90 分钟","开盖加入腐竹，加盖转中火煮 20 分钟","开盖加入酱汁 2 搅拌均匀","关火，出锅前加入葱绿段或香菜"]]],["此菜属于粤菜，正宗做法多会添加马蹄。考虑到萝卜青菜各有所爱，也可根据个人口味替换成土豆、萝卜等其他食材","参考资料：[枝竹羊腩煲 Lamb Stew with Bean Curd Sheet [by 點Cook Guide]](https://www.youtube.com/watch?v=ThVDpVoToDQ)"]],["d82acdc568","猪皮冻是北方年夜饭常见的传统凉菜，晶莹剔透，口感滑嫩 Q 弹，特别适合下酒。猪皮富含胶原蛋白，有美容养颜的作用。这道菜难度稍高，需要耐心处理猪皮去腥和长时间熬煮，预计制作时长约 24 小时。",[["必备","猪皮","f",0],["必备","大料、花椒、白芷、桂皮、丁香、香叶、小茴香","f",0]],[["参考用量",[["主料:猪皮","1kg、水 4kg","f"],["调料：盐","13g、味精 10g、鸡精 15g、生抽 50ml、老抽 20ml、葱 10g、葱 10g、姜片 20g","s"],["香料包：八角","10g、花椒 5g","f"]],["每份："]]],[["制作步骤",["将猪皮，剁成不超过 10cm 小块，用清水浸泡 12 小时，然后冷水下锅，加入姜 10g、料酒 50ml 后，汆烫 5-10 分钟，捞出放入冷水中","将焯过水的猪皮，放到案板上，将里面的白肉部分全部剔除，然后再切成成不超过 3mm 的长条，放入盆中","加入白醋 20g，盐 5g，用力搓洗 3 分钟，再用清水洗净，这时的猪皮已经基本没什么腥味","锅内加入 4kg 水，放入猪皮，葱 10g，姜片 10g，八角 10g，花椒 5g，大火烧开后，小火煲煮 90 分钟至猪皮软烂","再加入盐 8g、味精 10g、鸡精 15g、生抽 50ml、老抽 20ml 调味后，倒入盘中，将葱姜，八角拣出，晾凉至果冻状","放冰箱冷藏即可，食用时，切成小块或者厚片"]]],["操作时，需要注意，做猪皮冻，直接下锅煮就“废”了，也是最忌讳的，一定要用白醋和盐不断搓洗猪皮，这样保证煮好的猪皮晶莹剔透，而且还没腥味","参考资料：铭哥说美食"]],["5be3cbb5c7","猪肉烩酸菜是一道北方家常炖菜，酸香浓郁，五花肉软烂，排骨入味。主要提供蛋白质，酸菜也带来乳酸菌等有益成分。做法步骤清晰，新手也能按部就班完成，但需耐心慢炖，从头到尾大约需要 3 小时。",[["必备","猪五花肉或猪肉排骨","f",0],["必备","东北酸菜","f",0],["必备","大葱","f",0],["必备","姜","f",0],["必备","蒜","f",0],["必备","盐","s",0],["必备","生抽酱油","s",0],["必备","五香粉","s",0],["必备","料酒","s",0],["必备","大料","f",0]],[["参考用量",[["猪排骨或者五花肉（总共）","1500 克","f"],["东北酸菜","1000 克","f"],["大葱","1 根","f"],["姜","100 克","f"],["蒜","4 瓣","f"],["盐","10 克","s"],["生抽酱油","15 克","s"],["五香粉","10 克","s"],["料酒","20 毫升","s"],["大料","2 颗","f"]],["按照 3-5 个人吃的量："]]],[["制作步骤",["大葱切段；生姜 50 克切段， 50 克切末；大蒜切末，备用。","全部酸菜切丝，用水冲洗 2 ～ 3 遍备用。","-冲洗次数取决于个人口味，喜欢酸味，可以冲洗 2 遍。害怕酸味，可以冲洗 3 ～ 4 遍。不能不冲洗，否则会过酸。","排骨和五花肉入锅，倒入冷水淹没。放入全部葱段， 50 克生姜段和料酒 20 毫升。大火煮开后，等待 5 分钟。关火，将排骨和五花肉捞出，冷水冲洗掉浮沫，备用","煮好的五花肉切片或者切块，备用。","将之前的锅洗干净，并且擦干（不然加入油会崩出来）。","锅中加入油，开中火，放入姜蒜末爆香，放入五花肉和排骨。将五花肉和排骨煎至金黄，倒入 10 克五香粉和 15 克 生抽酱油，用铲子翻动 1 ～ 2 分钟。","将冲洗好的酸菜丝加入锅中，翻炒 3 分钟。","倒入纯净水至刚好没过食材，加入 2 颗大料，转大火，直到锅中水沸腾。转中火，盖锅盖焖煮。","等待 1.5 ～ 2 小时，直至五花肉软烂 （可以用筷子轻松扎穿）","掀开锅盖，开大火收汤，翻动锅中食材直至锅中剩余水分只覆盖锅底，转小火，准备调味。","调味：加入食用盐 10 克，搅拌均匀。","关火，出锅。"]]],["大火收汤时，注意不要糊锅，可以适当翻动来检查水位。","调味的技巧，最后加盐时，可以一点一点加入，搅拌后品尝味道，直到可以接受的口味","本菜品有酸菜的特殊风味"]],["417bb98a1b","这是一道经典广式风味菜肴，肉香浓郁，色泽红亮，带筋牛腩软烂入味，口感丰富。富含优质蛋白质和胶原蛋白，滋补暖身。虽需一定耐心，但使用高压锅能大幅缩短时间，对新手也较友好。普通炖煮约需 3 小时，用高压锅则约 1 小时即可完成。",[["必备","炖煮锅，高压锅（可选，但极度推荐！）","t",1],["必备","牛腩（首选坑腩，带筋的部位）","f",0],["必备","柱候酱（核心酱），郫县豆瓣酱，南腐乳，叉烧酱（可选），蚝油， 老抽，生抽","s",1],["必备","花雕酒，白酒","f",0],["必备","香叶， 花椒，八角，干辣椒，丁香，甘草，干辣椒，小米辣（可选），姜，蒜","f",1]],[["参考用量",[["牛腩","500-600g","f"],["姜","30g","f"],["蒜半头","","f"],["小米辣","1 条（可根据口味调整用量）","f"],["香叶","2 片","f"],["花椒","0.5g","s"],["八角","2 个","f"],["干辣椒","3 个（可根据口味调整用量）","f"],["丁香","3 个","f"],["甘草","2 片","f"],["南腐乳","2 块","f"],["郫县豆瓣酱","15g","s"],["冰糖","10g","s"],["花雕酒","10g","f"],["白酒","20g","f"],["柱候酱","50g","s"],["蚝油","20g","s"],["老抽","5g","s"],["生抽","60g","s"],["叉烧酱","20g","s"]],["以下为一份两人食用的量："]]],[["制作步骤",["先把辅料备好：","碗 1：姜切成 1.5cm\\1.5cm 的小块，半头蒜剥好皮，如果有小米辣切成 1cm 小段","碗 2：放入 2 片香叶，0.5g 花椒，2 个八角，3 个干辣椒，3 个丁香， 2 片甘草","碗 3: 放入 2 块南乳","碗 4: 放入 15g 豆瓣酱","碗 5: 放入 10g 冰糖","碗 6：倒入花雕酒 10g 和白酒 10g","碗 7：加入 50g 柱候酱，20g 蚝油，20g 叉烧酱，5g 老抽，60g 生抽","牛肉不用切，直接冷水下锅，开大火焯水，水沸腾时将牛肉捞出","冲洗牛肉表面的杂质后，切成 4cm\\4cm\\4cm 的大块，控干水后放入碗中备用","大火，热锅下油，把碗 1（姜、蒜、小米辣）倒入锅中，炒香","中小火，倒入碗 2（香料），翻炒均匀，大概 30 秒","中小火，放入碗 3（南乳），用锅铲把南乳压碎","中小火，放入碗 4（豆瓣酱），翻炒均匀，大概 30 秒","中小火，放入碗 5（冰糖），炒至融化","中小火，下入牛腩，炒至牛肉上色","大火，沿锅边淋入碗 6（酒），快速翻炒，炒至牛肉表面略微焦褐","倒入碗 7（酱料），快速翻炒，留意底层汁水，炒至不停冒小气泡，汤汁略微浓稠","将锅内全部食材转移至另一个炖煮锅或高压锅，加水淹过食材","根据使用的锅来选择炖肉的时间：","a. 普通炖煮锅：小火炖煮 3 个小时","b. 高压锅：压 40 分钟","时间到后开盖调味，如果不够咸加盐或生抽（少量加，不断尝味道，直到合适），不够甜则同理加糖","调好味道后便可以把牛腩先捞出","如果要吃萝卜土豆，则削皮切成 2cm 厚片倒入锅中煮 10 - 15 分钟（或煮至想要吃的口感），如果是高压锅则在加压煮 5 分钟","煮好后捞出萝卜土豆和牛腩放一起","把汤汁过滤淋入碗中"]]],["参考: 柱候牛腩+茅根马蹄竹蔗水教程","操作高压锅要注意安全哦！"]],["542a849607","孜然牛肉是一道香辣鲜嫩的家常小炒，浓郁的孜然风味与牛肉的软滑、青椒的清脆融合得恰到好处。牛肉富含优质蛋白和铁，搭配青椒还能补充维生素，营养均衡。制作需要一些刀工和火候把控，适合有一定下厨基础的爱好者尝试。算上腌肉和备菜，全程大约 45 分钟就能端上餐桌。",[["必备","牛柳或牛肩肉","f",0],["必备","青椒","f",0],["必备","孜然（颗粒>粉）","s",0],["必备","小米椒","f",0],["必备","生抽酱油","s",0],["必备","淀粉","s",0],["必备","油","s",0],["必备","盐","s",0],["必备","葱","f",0],["必备","捣药罐（可选）","f",1]],[["参考用量",[["牛肉用量为","250 g/人","f"],["青椒用量为","2 颗/人, 每颗 100g","f"],["孜然用量为","20 g/人","f"],["小米椒用量为","3 颗/人, 每颗 5g","f"],["生抽酱油用量为","20 ml/人","f"],["淀粉用量为","10g/人","f"],["油用量为","15ml/人","f"],["盐量用量为","3 g/人","f"],["葱用量为","1 根/人, 每颗 20g","f"]],["使用上述条件，计算出计划使用的原材料比例，依口味调整。"]]],[["制作步骤",["首先将小米椒切碎，和孜然粒一起放入捣药罐捣碎成颗粒，这样更入味。如果时间紧张可跳过捣碎步骤","青椒切头去籽（喜欢辣的可不去），切成丝。葱切段。","牛肉提前解冻，过一边水洗干净，晾干或用厨用纸吸干，将牛肉顺着纹理切成片","然后进行腌肉，加入生抽，淀粉，油，均匀搅拌，静止 30 分钟。腌肉方法也可参考学习腌","热锅下油，放入葱，爆出香味后放入腌好的牛肉煸炒","牛肉变色后均匀放入孜然辣椒颗粒并炒熟","然后下入青椒丝，断生后放盐","大🔥炒 1 分钟后关火再翻炒 30 秒保证受热均匀即可出锅"]]],[]],["f005ca41e4","这是一道山东淄博特色烧烤，小饼卷肉配大葱的吃法风味独特，肉香、酱香与葱香交融，口感层次丰富。五花肉富含优质蛋白质和脂肪，大葱提供膳食纤维，搭配小饼能快速补充能量。制作需要控制炭火火候和翻烤技巧，对新手稍具挑战，全程约 40 分钟即可完成。",[["必备","猪五花肉","f",0],["必备","小薄饼（市售现成）","f",0],["必备","大葱","f",0],["必备","芝麻酱","s",0],["必备","甜面酱","s",0],["必备","芝麻盐","s",0],["必备","烧烤炉","f",0],["必备","烤网","f",0],["必备","炭火或燃气","f",0]],[["参考用量",[["猪五花肉","200g","f"],["小薄饼","5 张","f"],["大葱","1 根（约 100g）","f"],["芝麻酱","20g","s"],["甜面酱","15g","s"]],["每份为 1 个人吃的量，多人按比例加量即可。","每份："]]],[["制作步骤",["五花肉切成厚度不超过 2cm 长的块，并串成串。（五花肉可以预先腌制一下，味道更佳）","大葱切成 5cm 长的葱段，备用","芝麻酱加 10ml 温水调稀，与甜面酱混合均匀，备用（可以换成\"芝麻盐\"）","点燃炭火，等待炭火烧至通红无明火状态（约 15 分钟）","将五花肉串均匀摆在在烤网上，烤至底面焦黄出油后翻面","继续烤制约 2 - 3 分钟，至两面焦黄、边缘微焦后取下","取一张小薄面饼平铺，抹上 3 - 4g 混合酱料","放上烤好的肉片和 1 - 2 段大葱，卷起即可食用"]]],["五花肉切片时建议放入冰箱冷冻 30 分钟后再切，更易切块。","炭火烤制风味优于燃气，有条件建议使用木炭。","酱料可根据个人口味调整芝麻酱与甜面酱的比例，也可以换成芝麻盐。"]],["065956e7b2","醉排骨是福州传统名菜，口感外酥里嫩，酸甜开胃，带着独特的鱼露鲜香。排骨富含蛋白质和钙质，营养解馋。这道菜需要掌握挂糊和复炸的技巧，更适合有一定下厨经验的朋友尝试，全程大约需要 40 分钟完成。",[["必备","排骨","f",0],["必备","白砂糖","s",0],["必备","食用油","s",0],["必备","鱼露","f",0],["必备","芝麻","f",0],["必备","番茄酱","s",0],["必备","香醋","s",0],["必备","蒜头","f",0],["必备","葱","f",0],["必备","地瓜粉","f",0],["必备","鸡蛋黄","f",0]],[["参考用量",[["排骨","200 g","f"],["白砂糖","10 g","s"],["食用油","500 ml","s"],["鱼露","5 ml","f"],["芝麻","5 g","f"],["番茄酱","5 g","s"],["香醋","5 ml","s"],["蒜头","2 粒","f"],["葱","1 根","f"],["地瓜粉","30 g","f"],["鸡蛋黄","1 个","f"]],["每份："]]],[["制作步骤",["排骨中加入 5 g 地瓜粉和水进行搅拌，清洗 2-3 遍后放入大碗备用","排骨中加入鱼露、地瓜粉、鸡蛋黄 充分搅拌","将排骨一个一个放入锅中（切记不可以整碗倒入），保证每个不要粘在一起","全部放入后，每 30 S 用勺子来回两面翻转瘦肉块，直至排骨表面金黄","取出排骨，一分钟后倒入油锅中继续炸，直至瘦肉块表面出现焦黄后，取出放入大碗备用","准备一个小碗，加入蒜末、香醋、白砂糖、鱼露、番茄酱、葱花、芝麻搅拌均匀，倒入 5 ml 热油","将汤汁浇灌入排骨，在充分搅拌后倒入盘中"]]],["鱼露，又称鱼酱油，是一种广东，福建等地常见的调味品。效果类似于生抽","本次制作过程中，由于疫情原因没有雨露，只能用老抽代替，所以排骨颜色偏黑，正常是金黄色"]]];
